window.JASTROW_CHUNKS[70]={"28000":{"h":"קֶרֶת","r":"S02202","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) = <a href=\"#\" data-headword=\"קִרְיָה I\">קִרְיָה</a>, <i>town, city</i>. <span class=\"citation\">Nidd. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"מָרוֹם\">מָרוֹם</a>.</div>","alt":[]},"28001":{"h":"קַרְתָּא","r":"S02203","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. IV, 17</span>. <span class=\"citation\">Targ. Is. XIX, 18</span>; a. fr.—<span class=\"citation\">Y. Taan. IV, 68ᵈ</span>, v. <a href=\"#\" data-headword=\"מֵרוֹן\">מֵרוֹן</a>. Ib. top <span dir=\"rtl\">טב ק׳</span>, v. <a href=\"#\" data-headword=\"טַב II\"><span dir=\"rtl\">טַב</span> II</a>. Ib., v. <a href=\"#\" data-headword=\"יָלֵיל\">יָלֵיל</a>.</div>","alt":["קַרְתָּה","קָ׳"]},"28002":{"h":"קָרְתָא","r":"S02204","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַר\">קְרַר</a>) <i>cold</i>. <span class=\"citation\">Targ. Prov. XXV, 20</span> (ed. Lag. <span dir=\"rtl\">קור׳</span>).</div>","alt":["(קֹרָ׳","קָרְתָּא)"]},"28003":{"h":"קַרִתּוּיֵי","r":"S02205","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְתּוּיִים\">next w.</a></div>","alt":[]},"28004":{"h":"קַרְתּוּיִים","r":"S02206","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Κόρτιοι, Polybius 5, 52, 5; Strabo XI, 13) <i>natives of Ḳartu</i> (mountaineers of Media). <span class=\"citation\">Yeb. 16ᵃ</span> <span dir=\"rtl\">ק׳ איתמר וכ׳</span> the traditional spelling is <i>Ḳartuyim</i> (and not Ḳarduyim), as people say, disqualified Kartuenians. <span class=\"citation\">Ib.</span> (Chald. form) <span dir=\"rtl\">קַרְתּוּיֵי וכ׳</span> Kartuenians are not the same as Ḳarduenians, as people say <span dir=\"rtl\">ק׳ פסילי</span>; v. <a href=\"#\" data-headword=\"קַרְדּוּיִים\">קרְדּוּיִים</a>.</div>","alt":["קַרְתּוּיִין"]},"28005":{"h":"קרתחייה","r":"S02207","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְתִּיגְנִי\">next w.</a></div>","alt":["קַרְתִּיגְנָאָה"]},"28006":{"h":"קַרְתִּיגְנִי","r":"S02208","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Carthago, -inis) <i>Carthage</i> (rebuilt under the Roman empire). <span class=\"citation\">Y. Shebi. VI, 36ᵇ</span> bot. (expl. <span dir=\"rtl\">קנזי</span>, <span class=\"citation\">Gen. XV, 19</span>) <a href=\"#\" data-headword=\"ק׳\">ק׳</a>; <span class=\"citation\">Y. Kidd. I, 61ᵈ</span> top <span dir=\"rtl\">קרתיגנ׳</span>; v. <a href=\"#\" data-headword=\"קַרְטִיגְנִי\">קַרְטִיגְנִי</a>.—Denom. <a href=\"#\" data-headword=\"קרתחייה\">קַרְתִּיגְנָאָה</a>, <span dir=\"rtl\">קַרְתִּיגְנָיָיא</span>. <span class=\"citation\">Y. Kil. VIII, 31ᵇ</span> bot.; a. fr. <span dir=\"rtl\"><span dir=\"rtl\">בא ק׳</span> (א</span>); Y. Sabb. VII, 9ᵈ <span dir=\"rtl\">קרט׳</span>. Ib. XVI, 15ᶜ bot. <span dir=\"rtl\">חיננא ק׳</span>; Y. Bets. I, 60ᶜ bot. <a href=\"#\" data-headword=\"קרתחייה\">קרתחייה</a> (corr. acc.); <span class=\"citation\">Keth. 27ᵇ</span> <span dir=\"rtl\">חנן קרט׳</span>; <span class=\"citation\">B. Kam. 114ᵇ</span> חנא קרתיגנאה Ms. M. (ed. <a href=\"#\" data-headword=\"קַרְטִיגְנָא\">קרטיגנא</a>, corr. acc.); <span class=\"citation\">ib.</span> <span dir=\"rtl\">אחא ק׳</span> (v. Rabb. D. S. a. l. note 4).</div>","alt":[]},"28007":{"h":"קַרְתִּיסָיָה","r":"S02209","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>of Ḳartes</i> (perh. Carthæa, on the island of Ceos). <span class=\"citation\">Y. Keth. II, 26ᵈ</span> bot. <span dir=\"rtl\">חנניה ק׳</span>.</div>","alt":[]},"28008":{"h":"קַרְתָּנִי","r":"S02210","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קֶרֶת\">קֶרֶת</a>) <i>townsman, provincial</i>. <span class=\"citation\">Dem. VI, 4</span> <a href=\"#\" data-headword=\"קַפָּר\">הק׳</a>, opp. to <a href=\"#\" data-headword=\"יְרוּשַׁלְמִי\">ירושלמי</a>; Y. ib. 25ᶜ bot.—[<span class=\"citation\">Lev. R. s. 24</span> <span dir=\"rtl\">מעשה בק׳</span>, read: <span dir=\"rtl\">בקריתנו</span>, v. <a href=\"#\" data-headword=\"קִרְיָה I\">קִרְיָה</a>.]—<i>Fem</i>. <a href=\"#\" data-headword=\"קַרְתָּנִי\">קַרְתָּנִית</a>. <span class=\"citation\">Cant. R. to I, 6</span>.</div>","alt":[]},"28009":{"h":"קַשׁ","r":"S02211","html":"<div class=\"sense\"><i>old</i>, v. <a href=\"#\" data-headword=\"קְשַׁשׁ I\">קְשַׁשׁ</a>.</div>","alt":[]},"28010":{"h":"קַשׁ ²","r":"S02212","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> קשש <i>to be hard, stiff</i>; cmp. <a href=\"#\" data-headword=\"קָשֶׁה\">קָשֶׁה</a>) <i>straw, stubble</i>. <span class=\"citation\">Sabb. III, 1</span> <span dir=\"rtl\">בקש ובגבבא</span> with straw or rakings. <span class=\"citation\">Ib. 66ᵃ</span> <span dir=\"rtl\">כוורת של קש</span>; <span class=\"citation\">Kel. XV, 1</span> <span dir=\"rtl\">כוורת הקש</span>, v. <a href=\"#\" data-headword=\"כְּוֶורֶת\">כְּוֶורֶת</a>. <span class=\"citation\">Ib. XVII, 17</span>, v. <a href=\"#\" data-headword=\"שְׁפוֹפֶרֶת\">שְׁפוֹפֶרֶת</a>. Y. Peah IV, beg. 18ᵃ <span dir=\"rtl\">הנח … בקַשָּׁהּ</span> leave for them (the poor) the grain with its straw (stalks); a. fr.—[<span class=\"citation\">Tosef. Sabb. IX</span> (<span class=\"citation\">X), 2</span> <span dir=\"rtl\">הקש שבחזיר</span> some ed. the stiff bristle &amp;c., v. <a href=\"#\" data-headword=\"קָשֶׁה\">קָשֶׁה</a>.]—Pl. <span dir=\"rtl\">קַשִּׁים</span>, <span dir=\"rtl\">קַשִּׁין</span>. <span class=\"citation\">Y. Peah V, end, 19ᵃ</span> <span dir=\"rtl\">בזוכר את הק׳</span> when he recalls the straw (with which he covered the sheaves). <span class=\"citation\">Taan. 6ᵃ</span> <span dir=\"rtl\">בקַשֶּׁיהָ</span>, v. <a href=\"#\" data-headword=\"מַלְקוֹשׁ\">מַלְקוֹשׁ</a>.</div>","alt":[]},"28011":{"h":"קַשָּׁא I","r":"S02213","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. XV, 7</span>. <span class=\"citation\">Targ. Is. XL, 24</span>.—Pl. <span dir=\"rtl\">קַשִּׁין</span>. <span class=\"citation\">Gen. R. s. 35</span> (play on <span dir=\"rtl\">קשתי</span>, <span class=\"citation\">Gen. IX, 13</span>) <span dir=\"rtl\">ק׳ דפֵירַי</span> the straw of my fruit (the least of my works); Yalk. ib. 61.</div>","alt":[]},"28012":{"h":"קַשָּׁא II","r":"S02214","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשַׁשׁ I\">קְשַׁשׁ</a>; cmp. <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קַשִּׁישׁ</a>), <a href=\"#\" data-headword=\"קַפָּרָא\">בַּר ק׳</a> <i>elder, officer</i>. <span class=\"citation\">Sabb. 110ᵃ</span> top. <span class=\"citation\">B. Bath. 110ᵇ</span> top <span dir=\"rtl\">מאן כו לירות אטו בר ק׳ וכ׳</span> (<a href=\"#\" data-headword=\"כַּו\">כּוּ</a> = <span dir=\"rtl\">כְּהוּ</span>, not <a href=\"#\" data-headword=\"בּוֹ\">בו</a>) who else should be the heir? should the officer of the town be the heir? [oth. opin. (v. <a href=\"#\" data-headword=\"קָשַׁשׁ I\"><span dir=\"rtl\">קָשַׁש</span> I</a>) <i>collector</i>.]</div>","alt":[]},"28013":{"h":"קְשָׁא","r":"S02215","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְשֵׁי\">קְשֵׁי</a></div>","alt":[]},"28014":{"h":"קָשַב","r":"S02216","html":"<div class=\"sense\"> (b. h.) <i>to be hard, stiff</i>.</div><div class=\"sense\"><b>Hif. הִקְשִׁיב</b> <div class=\"sense\"> [<i>to prick up the ear</i>,] <i>to listen</i>. <span class=\"citation\">Cant. R. to VIII, 13</span> אני … מַקְשִׁיבִים וכ׳ I and my household will listen to thy voice (of prayer). <span class=\"citation\">Sabb. 63ᵃ</span> <span dir=\"rtl\">הקב&quot;ה מַקְשִׁיב להם</span> the Lord listens to them. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שני … המקשיבים זה  לזה וכ׳</span> two students who patiently listen to each other in discussions of the <i>halakhah</i>; a. e.</div></div>","alt":[]},"28015":{"h":"קְשַׁב","r":"S02217","html":"<div class=\"sense\">, <i>to be attentive, watchful</i>. <span class=\"citation\">Gitt. 56ᵃ</span> דאינהו קַשְׁבֵי דחייא וכ׳ Ar. (ed. <span dir=\"rtl\">ידעי</span>) read: <span dir=\"rtl\">דאינהו ק׳ וידעי דחייא וכ׳</span></div>","alt":[]},"28016":{"h":"קִשְׁבָּא","r":"S02218","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> a species or variety of <i>dates; date-tree</i> (v. <a href=\"#\" data-headword=\"כּוֹתֶבֶת\">כּוֹתֶבֶת</a>). <span class=\"citation\">Ab. Zar. 14ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲצָב I\"><span dir=\"rtl\">חֲצָב</span> I</a>. <span class=\"citation\">B. Kam. 58ᵇ</span> <span dir=\"rtl\">קץ ק׳ מחבריה</span> (Ms. H. <a href=\"#\" data-headword=\"קִישְׁקוּשׁ\">קִישְׁ׳</a>; Alf. <a href=\"#\" data-headword=\"קִסְבָּא\">קסבא</a>; v. Rabb. D. S. a. l. note 20) cut one of his neighbor’s date-trees.—Pl. <span dir=\"rtl\">קִשְׁבֵּי</span>. <span class=\"citation\">Meg. 7ᵇ</span> מלא טסקא דק׳ Ms. M. (ed. <span dir=\"rtl\">דקשבא</span>) a basketful of dates; <span class=\"citation\">Yalk. Esth. 1059</span>.</div>","alt":[]},"28017":{"h":"קָשָׁה","r":"S02219","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קשי\">קשי</a></div>","alt":[]},"28018":{"h":"קְשֵׁה","r":"S02220","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְשֵׁי\">קְשֵׁי</a></div>","alt":[]},"28019":{"h":"קָשֶׁה","r":"S02221","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"קָשָׁה\">קָשָׁה</a> f. (b. h.; <a href=\"#\" data-headword=\"קְשֵׁה\">preced.</a>) <i>stiff, hard, difficult, severe; strong</i>. <span class=\"citation\">Tosef. Sabb. IX</span> (<span class=\"citation\">X), 2</span> <span dir=\"rtl\">שני זייפין מן הק׳ וכ׳</span> (some ed. <span dir=\"rtl\">הקַשׁ</span>) two of the stiffest bristles of the swine; <span class=\"citation\">Sabb. 90ᵇ</span> <span dir=\"rtl\">מקָשָׁה של חזיר אחת</span> carrying one of the stiff bristles of the swine is punishable. <span class=\"citation\">Taan. 20ᵇ</span> <span dir=\"rtl\">ק׳ כארז</span>, v. <a href=\"#\" data-headword=\"קָנֶה\">קָנֶה</a>. <span class=\"citation\">B. Bath. 88ᵇ</span> <span dir=\"rtl\">ק׳ עונשן של וכ׳</span> the responsibility for fraud in measures is severer than that for incest. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ גזל הדיוט וכ׳</span> robbing an individual is worse than robbing the altar. <span class=\"citation\">Gen. R. s. 26</span>, end <span dir=\"rtl\">ק׳ היא המחלוקת וכ׳</span> strife is as bad as (the sins of) the generation of the flood. <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">ק׳ היא התפלה וכ׳</span> prayer is a powerful factor, for it reversed the divine decree. <span class=\"citation\">Taan. 8ᵃ</span> <span dir=\"rtl\">שלמודו ק׳ עליו וכ׳</span> to whom his study is as hard as iron. <span class=\"citation\">Ib. 8ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">ק׳ יומא וכ׳</span>, v. <a href=\"#\" data-headword=\"קָשֵׁי\">קָשֵׁי</a>. <span class=\"citation\">Ex. R. s. 6</span> <span dir=\"rtl\">היה ק׳ בעיניהם וכ׳</span> it seemed too hard a task for them to give up idolatry; a. v. fr.—<span class=\"citation\">Erub. 83ᵇ</span> <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">בק׳</a> with difficulty, v. <a href=\"#\" data-headword=\"נַחַת\">נַחַת</a>.—[<span class=\"citation\">Num. R. s. 16</span> end <span dir=\"rtl\">קשה ערפם</span>, v. <a href=\"#\" data-headword=\"קְשִׁי\">קְשִׁי</a>.]—Pl. <span dir=\"rtl\">קָשִׁים</span>, <span dir=\"rtl\">קָשִׁין</span>; <a href=\"#\" data-headword=\"קָשׁוּת I\">קָשׁוֹת</a>. <span class=\"citation\">Yeb. 47ᵇ</span>, a. e. <span dir=\"rtl\">ק׳ גרים וכ׳</span>, v. <a href=\"#\" data-headword=\"סַפַּחַת\">סַפַּחַת</a>. <span class=\"citation\">Sot. 2ᵃ</span> <span dir=\"rtl\">ק׳ לזווגן</span> (<span class=\"citation\">Snh. 22ᵃ</span> <span dir=\"rtl\">קשה</span>), v. <a href=\"#\" data-headword=\"זָוַג\">זָוַג</a>. <span class=\"citation\">Pes. 118ᵃ</span> <span dir=\"rtl\">ק׳ … כקריעת וכ׳</span> the providential support of man is as difficult (wonderful) as the splitting of the Red Sea. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ … כפלים וכ׳</span> man’s support is twice as hard (painful) as travailing. <span class=\"citation\">Ber. 57ᵇ</span> (etymolog. play on <a href=\"#\" data-headword=\"קִישּׁוּאִים\">קישואים</a>) <span dir=\"rtl\">מפני שהם ק׳ לגוף וכ׳</span> because they are as hard on the body as swords. <span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">נבואות ק׳</span> hard (evil) prophecies; a. v. fr.</div>","alt":[]},"28020":{"h":"קִשְׂוָא","r":"S02222","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִסְוָה\">קִסְוָה</a></div>","alt":[]},"28021":{"h":"קִשּׁוּאִים","r":"S02223","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"קִישׁוּת I\"><span dir=\"rtl\">קִישׁוּת</span> I</a>) <i>cucumbers</i>. <span class=\"citation\">Ber. 57ᵇ</span>, v. <a href=\"#\" data-headword=\"קָשֶׁה\">קָשֶׁה</a>. <span class=\"citation\">B. Kam. VIII, 1</span> <span dir=\"rtl\">שומר ק׳</span> watchman in a cucumber field. <span class=\"citation\">Kil. III, 4</span>; a. fr.</div>","alt":["קִשּׁוּאִין","קִי׳"]},"28022":{"h":"קִשְׂוָה","r":"S02224","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קוּסְדֹּור\">קִסְ׳</a>, <a href=\"#\" data-headword=\"קוּסְדֹּור\">קַסְ׳</a>.</div>","alt":["קַשְׂוָוא"]},"28023":{"h":"קְשׁוֹט","r":"S02225","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשַׁט\">קְשַׁט</a>) </div><div class=\"sense\"><b>1)</b>  [<i>straightness</i>,] <i>truth, righteousness</i>. <span class=\"citation\">Targ. Gen. XXIV, 48</span>, sq. <span class=\"citation\">Targ. Y. ib. V, 22</span>; <span class=\"citation\">24</span>. <span class=\"citation\">Targ. II Chr. VI, 18</span> (h. text <span dir=\"rtl\">האמנם</span>); a. fr.—<span class=\"citation\">Lev. R. s. 26</span> אנא בעלם דק׳ … מילין דק׳ I (Samuel) am now in the world of truth (v. <a href=\"#\" data-headword=\"עָלַם III\">עָלְמָא</a>), and thou shalt hear from me none but words of truth; Tanḥ. Emor 2. <span class=\"citation\">Sabb. 104ᵃ</span> <span dir=\"rtl\">ק׳ קאי</span> truth stands firm (v. <a href=\"#\" data-headword=\"לְבַן\">לְבַן</a>). <span class=\"citation\">Snh. 97ᵃ</span> <span dir=\"rtl\">מריש … ליכא ק׳ בעלמא וכ׳</span> formerly I thought there was no truth in the world. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איקלע … ק׳ שמיה</span> he came to a place named Ḳushṭa (Truth); a. fr.—Pl. <span dir=\"rtl\">קוּשְׁטִין</span>. <span class=\"citation\">Targ. Y. Num. XXII, 37</span> <span dir=\"rtl\">מן ק׳</span> (h. text <span dir=\"rtl\">האמנם</span>).—Y. Ḥag. II, beg. 77ᵃ <span dir=\"rtl\">ק׳ אתון אמרין דהין וכ׳</span> do you (Jews) indeed say that the world is maintained by air?</div><div class=\"sense\"><b>—2)</b>  (sub. <a href=\"#\" data-headword=\"גְּבַר I\">גבר</a>) <i>true</i>. Targ. II Esth. I, 2 <span dir=\"rtl\">תמים וק׳</span> upright and true.</div>","alt":["קוּשְׁטָא"]},"28024":{"h":"קִשּׁוּט","r":"S02226","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קִישּׁוּט\">קִישּׁ׳</a>.</div>","alt":["קִישּׁוּטָא","קִשּׁוּי","קִשּׁוּיָא","קִשּׁוּר","קִשּׁוּרָא"]},"28025":{"h":"קָשׁוּת I","r":"S02227","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kil. I, 11</span> Var., v. <a href=\"#\" data-headword=\"כָּשׁוּת\">כָּשׁוּת</a></div>","alt":[]},"28026":{"h":"קָשׁוּת II","r":"S02228","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִישׁוּת II\"><span dir=\"rtl\">קִישׁוּת</span> II</a></div>","alt":[]},"28027":{"h":"קָשַׁט","r":"S02229","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) [<i>to be straight, strong</i>,] </div><div class=\"sense\"><b>1)</b> <i>to go in a straight line, to shoot forth</i>. <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">יש מזיק … וקוֹשֵׁט כחץ</span> some demon flies like a bird and shoots through the air like an arrow; <span class=\"citation\">Midr. Till. to Ps. XCI</span>; <span class=\"citation\">Yalk. ib. 842</span> <span dir=\"rtl\">וקוֹשֵׁת</span>; Tanḥ. Naso 23 <span dir=\"rtl\">וקושש</span> (corr. acc.); ed. Bub. 28.—<span class=\"citation\">Y. Meg. I, 72ᵇ</span> <span dir=\"rtl\">מאיכן ק׳ הקוֹשֵׁט הזה וכ׳</span> whence did this archer shoot (whence did he derive the opinion) that &amp;c. (cmp. <a href=\"#\" data-headword=\"יָרָה\">יָרָה</a> <i>Hif.</i>).</div><div class=\"sense\"><b>—2)</b> <i>to correct</i>. <span class=\"citation\">B. Mets. 107ᵇ</span>, v. infra.</div><div class=\"sense\"><b>Pi. קִישֵּׁט</b> <div class=\"sense\"><b>1)</b> <i>to shoot, aim, direct</i>. Tosef. Erub. IX (VI), 26 <span dir=\"rtl\">ביבין המְקַשְּׁטִין וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">המשקטין</span>, <span dir=\"rtl\">המְקַשְׁקְשִׁין</span>, v. <a href=\"#\" data-headword=\"קִשְׁקֵשׁ II\"><span dir=\"rtl\">קִשְׁקֵשׁ</span> II</a>) gutters which gush under the houses (cmp. <a href=\"#\" data-headword=\"קָלַח\">קָלַח</a>). <span class=\"citation\">Lam. R. to III, 12</span> מקושטים בה Ar. s. v. <a href=\"#\" data-headword=\"קוּרָה\">קורה</a>, read: <span dir=\"rtl\">מְקַשְּׁטִים</span> (Ar. ed. Koh. <span dir=\"rtl\">מְקוֹשְׁשִׁים</span>; ed. <a href=\"#\" data-headword=\"מוֹרִיר\">מוֹרִים</a>), v. <a href=\"#\" data-headword=\"חֵץ\">חֵץ</a>.—Part. pass. <span dir=\"rtl\">מְקוּשָּׁט</span>; f. <span dir=\"rtl\">מְקוּשֶּׁטֶת</span>; pl. <span dir=\"rtl\">מְקוּשָּׁטִים</span>, <span dir=\"rtl\">מְקוּשָּׁטִין</span>; <span dir=\"rtl\">מְקוּשָּׁטוֹת</span>. <span class=\"citation\">Pesik. R. s. 40</span> (play on <a href=\"#\" data-headword=\"מוֹרִיָּה\">מוריה</a>, with ref. to <span dir=\"rtl\">ירה יירה</span>, <span class=\"citation\">Ex. XIX, 13</span>) <span dir=\"rtl\">שהיתה מק׳ כנגד וכ׳</span> it (the holy land) was aimed towards (directly under) the heavenly altar (v. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>); <span class=\"citation\">Yalk. Cant. 988</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כשם שגודלת הזו … להיות מקושטים וכ׳</span> (not <span dir=\"rtl\">מקושטת</span>) as the hair-dresser dressing the bride puts every ornament in its proper place, so must the words of the Law be aimed, every word in its due place.</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">תקן</span>) <i>to dress, adorn, prepare</i>. Ib. <span dir=\"rtl\">שמְקַשֶּׁטֶת לכלה</span>, v. supra. <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">מְקַשֵּׁט כלות</span> he (the Lord) attires brides; <span class=\"citation\">Koh. R. to VII, 2</span>. Ib.; <span class=\"citation\">Gen. R. s. 18</span> <span dir=\"rtl\">משקִשְּׁטָהּ וכ׳</span> after having fitted her out with twenty-four kinds of ornaments; a. fr.—Part. pass. as ab. <span class=\"citation\">Sabb. 25ᵇ</span> <span dir=\"rtl\">מטה מוצעת ואשה מק׳ לתלמיד חכם</span> the scholar’s happiness when the couch is spread and the wife dressed (for the Sabbath). Ib. 153ᵃ <span dir=\"rtl\">כשהן מק׳</span> in festive dress, opp. <span dir=\"rtl\">מלוכלכין</span>; a. fr.—Trnsf. <i>to set right, correct</i>. <span class=\"citation\">Snh. 18ᵃ</span> (ref. to <span dir=\"rtl\">התקוששו וקושו</span>, <span class=\"citation\">Zeph. II, 1</span>) <span dir=\"rtl\">קַשֵּׁט … קשט אחרים</span> first correct thyself, then correct others; ib. 19ᵃ; <span class=\"citation\">B. Bath. 60ᵇ</span>; <span class=\"citation\">B. Mets. 107ᵇ</span> <span dir=\"rtl\">קְשׁוֹט וכ׳</span>; <span class=\"citation\">Yalk. Jer. 302</span>; <span class=\"citation\">Midr. Till. to Ps. LIII</span> <span dir=\"rtl\">אם תרצה לקַשֵּׁט אחרים וכ׳</span> if thou wishest to correct others, correct thyself first.</div></div><div class=\"sense\"><b>Hif. הִקְשִׁיט</b> <div class=\"sense\"><i>to prepare, make ready</i>. <span class=\"citation\">Gen. R. s. 28</span> <span dir=\"rtl\">הקב&quot;ה היפך … והִקְשִׁיטָן וכ׳</span> the Lord turned day into night and prepared them for visitations; (<span class=\"citation\">Yalk. Job 920</span> <span dir=\"rtl\">והתקינן</span>).</div></div><div class=\"sense\"><b>Hithpa. הִתְקַשֵּׁט</b> <div class=\"sense\"><b>1)</b> <i>to dress, adorn one’s self</i>. <span class=\"citation\">Num. R. s. 2</span> <span dir=\"rtl\">אבן יקרה שמִתְקַשְּׁטוֹת וכ׳</span> a precious stone with which women adorn themselves; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be verified, justified</i> (cmp. <a href=\"#\" data-headword=\"קְשׁוֹט\">קְשׁוֹט</a>). <span class=\"citation\">Gen. R. s. 55</span> <span dir=\"rtl\">בשביל שתִּתְקַשֵּׁט וכ׳</span>, v. <a href=\"#\" data-headword=\"קוֹשֶׁט\">קוֹשֶׁט</a>; <span class=\"citation\">Yalk. ib. 95</span>; <span class=\"citation\">Yalk. Ps. 777</span>.</div></div>","alt":[]},"28028":{"h":"קְשַׁט","r":"S02230","html":"<div class=\"sense\">—<i>Pa.</i> <a href=\"#\" data-headword=\"קַשָּׁט\">קַשֵּׁט</a> </div><div class=\"sense\"><b>1)</b> <i>to straighten, correct</i>. <span class=\"citation\">Targ. I Chr. XXIX, 18</span>.</div><div class=\"sense\"><b>—2)</b> <i>to go in a straight line, to shoot forth</i>. <span class=\"citation\">Targ. Hos. VI, 3</span> <span dir=\"rtl\">מְקַשֵּׁיט</span> (not <a href=\"#\" data-headword=\"מַדַּע\">מִ׳</a>; ed. Lag. <span dir=\"rtl\">מקשט</span>; h. text <a href=\"#\" data-headword=\"נָכוֹן\">נכון</a>).</div><div class=\"sense\"><b>—3)</b> <i>to prepare</i>. <span class=\"citation\">Yeb. 63ᵇ</span> (of a bad wife) <span dir=\"rtl\">מְקַשְּׁטָא … ומקשטא וכ׳</span> has a tray ready for him, and has her mouth ready for him (to scold); <span dir=\"rtl\">מק׳ … ומחדרא וכ׳</span> prepares a tray for him, and turns her back to him.</div><div class=\"sense\"><b>Ithpa. אִתְקַשֵּׁט  אִיקַּשַּׁט</b> <div class=\"sense\"><b>1)</b> <i>to be shot</i>. <span class=\"citation\">Targ. Y. II, Ex. XIX, 13</span> (ed. Vien. <span dir=\"rtl\">יתקשתין</span>).</div><div class=\"sense\"><b>—2)</b> <i>to be dressed, prepared</i>. <span class=\"citation\">Targ. Is. LXI, 10</span>. <span class=\"citation\">Targ. Am. IV, 12</span> (h. text <a href=\"#\" data-headword=\"כּוּן\">הכין</a>).—<span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">כי מִיקַּשְּׁטָא</span> is well dressed; a. e.</div></div>","alt":[]},"28029":{"h":"קַשָּׁט","r":"S02231","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשַׁט\">preced.</a>) <i>shooter, archer.</i>—Pl. <span dir=\"rtl\">קַשָּׁטִים</span>, <span dir=\"rtl\">קשָּׁטִין</span>. <span class=\"citation\">Y. Taan. IV, 69ᵇ</span> bot. <span dir=\"rtl\">בחרבן הראשׁון … ק׳ וכ׳</span> at the destruction of the first Temple she (Tadmor-Palmyra) furnished eighty thousand archers &amp;c.; <span class=\"citation\">Gen. R. s. 56</span> <span dir=\"rtl\">קַשָּׁתִים</span> (Var. <span dir=\"rtl\">קשט׳</span>); <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">קשת׳</span>.—V. <a href=\"#\" data-headword=\"קַשָּׁת\">קשָּׁת</a>.</div>","alt":[]},"28030":{"h":"קַשְׁטוּתָא","r":"S02232","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַשִּׁיטוּתָא\">קשִּׁיטוּתָא</a></div>","alt":[]},"28031":{"h":"קַשְׁטָן","r":"S02233","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּשְׁטָן\">קיּשְׁטָן</a></div>","alt":[]},"28032":{"h":"קַשְׁטָנִית","r":"S02234","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַשְׁטָן\">preced. art.</a>) <i>bow-shaped handle of a borer</i>, ‘<i>bow-drill</i>’ (v. Sm. Ant.<sup>3</sup> s. v. Terebra). <span class=\"citation\">Kel. XXI, 3</span> (ed. Dehr. <a href=\"#\" data-headword=\"קוּשְׁטָא\">קוּשְׁטָ׳</a>). <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 17</span> מטלטלין את הקשט׳ Ar. (ed. <span dir=\"rtl\">הקַשְׁתָּ׳</span>) you may handle the bow-drill (on the Sabbath); <span dir=\"rtl\">ולא יקדיח בק׳ וכ׳</span> but you must not bore (a wine cask &amp;c.) as you do on week days.</div>","alt":[]},"28033":{"h":"קשי","r":"S02235","html":"<div class=\"sense\"> (b. h.) <i>to be stiff, hard, difficult</i>. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> top <span dir=\"rtl\">קָשְׁתָה על דעתך</span> this is difficult according to (not reconcilable with) thy opinion; <span class=\"citation\">ib.</span> <span dir=\"rtl\">למה א&quot;ל קשתה</span> (not <span dir=\"rtl\">קשתיה</span>) why did he say to him, it is difficult?—V. <a href=\"#\" data-headword=\"קָשֶׁה\">קָשֶׁה</a>.</div><div class=\"sense\"><b>Pi. קִישָּׁה</b> <div class=\"sense\"> (<span dir=\"rtl\">קִישְּׁתָה</span>, with <span dir=\"rtl\">לילד</span> or without) <i>to have hard labor in travailing</i>. <span class=\"citation\">Ḥull. IV, 1</span> <span dir=\"rtl\">בהמה המְקַשָּׁה לילד וכ׳</span> if an animal is in labor, and &amp;c., v. <a href=\"#\" data-headword=\"עוּבָּר\">עוּבָּר</a>. <span class=\"citation\">Nidd. IV, 4</span> <span dir=\"rtl\">קִשְּׁתָה שלשה וכ׳</span> if she was in pain for three days within eleven days; <span class=\"citation\">Tosef. ib. V, 8</span> <a href=\"#\" data-headword=\"קישת\">קִישֵּׁת</a>, <span dir=\"rtl\">קִשֵּׁת</span>. <span class=\"citation\">Ib. 10</span>; a. fr.—[<span class=\"citation\">Gen. R. s. 61</span> <span dir=\"rtl\">שהיו מקשין וכ׳</span>, read: <span dir=\"rtl\">מקישין</span>, v. <a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>.]</div></div><div class=\"sense\"><b>Hif. הִקְשָׁה</b> <div class=\"sense\"><b>1)</b> <i>to stiffen, harden</i>. <span class=\"citation\">Nidd. 13ᵇ</span> <span dir=\"rtl\">המַקְשֶׁה עצמו וכ׳</span> he who causes erection wilfully. <span class=\"citation\">Ex. R. s. 11</span> <span dir=\"rtl\">הרשע הזה ה׳ את לבו וכ׳</span> this wicked (Pharaoh) hardened his heart against the first three signs; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to become hard</i>. Y. Pes. VI, 35ᵇ top <span dir=\"rtl\">שסופו להַקְשׁוֹת</span> which gets hard in the course of time. <span class=\"citation\">Shebi. II, 10</span> <span dir=\"rtl\">אם הִקְשׁוּ וכ׳</span> (Y. ed. a. Bart. <span dir=\"rtl\">הוּקְשׁוּ</span> <i>Hof.</i>) if they became hard (dry) and unfit for man to eat before New Year. (Y. ib. 34ᵃ bot. <span dir=\"rtl\">הקשו</span> a. <span dir=\"rtl\">הוקשו</span>).</div><div class=\"sense\"><b>—3)</b> <i>to be severe</i>. <span class=\"citation\">Gen. R. s. 19</span>, opp. <a href=\"#\" data-headword=\"רתי\">ריתה</a>, v. <a href=\"#\" data-headword=\"רָתָה\">רָתָה</a>.</div></div><div class=\"sense\"><b>Hof. הוּקְשֶׁה</b> <div class=\"sense\"><b>1)</b> <i>to become hard</i>, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to be found hard, distasteful</i>. Tanḥ. Sh’laḥ 5; <span class=\"citation\">Num. R. s. 16</span> <span dir=\"rtl\">ה׳ הדבר והרע וכ׳</span> the thing was distasteful to and displeased his father.</div></div><div class=\"sense\"><b>Hithpa. הִתְקַשֶּׁה</b> </div><div class=\"sense\"><b>Nithpa. נִתְקַשֶּׁה</b> <div class=\"sense\"><b>1)</b> <i>to suffer severely</i> (in travailing). <span class=\"citation\">Gen. R. s. 84</span> <span dir=\"rtl\">נִתְקַשֵּׁת אמו וכ׳</span> his mother was in hard labor at his birth.</div><div class=\"sense\"><b>—2)</b> <i>to become hard, stiff</i>. <span class=\"citation\">Tosef. Nidd. VI, 4</span> <span dir=\"rtl\">משׁיִתְקַשּׁוּ</span>, v. <a href=\"#\" data-headword=\"קִשְׁקֵשׁ I\"><span dir=\"rtl\">קִשְׁקֵשׁ</span> I</a>, a. II. <span class=\"citation\">Gen. R. s. 98</span>, a. <span dir=\"rtl\">שׁנִתְקַשֵּׁיתָה</span>, v. <a href=\"#\" data-headword=\"קַשְׁיוּת\">קַשְׁיוּת</a>.</div><div class=\"sense\"><b>—3)</b> <i>to find one’s self in difficulty, to be perplexed, unable to understand</i> or <i>remember</i>. <span class=\"citation\">Num. R. s. 15</span> beg. <span dir=\"rtl\">נ׳ משה במעשה וכ׳</span> Moses found the work of the candlestick more difficult to understand than &amp;c.; <span dir=\"rtl\">כיון שנ׳ אמר וכ׳</span> when he still could not remember it, the Lord said &amp;c. Ib.<sup>10</sup>; Tanḥ. B’haʿăl. 6 נִתְקַשֵּׁיתִי לעשותה I could not understand how to do it. Ib. <span dir=\"rtl\">נ׳ על משה</span> it was too difficult for Moses; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to be reluctant, strive against</i>. Tanḥ. Sh’moth 18 <span dir=\"rtl\">כמה נ׳ יונה שלא וכ׳</span> how hard did Jonah strive not to go on his mission. <span class=\"citation\">Deut. R. s. 9</span> <span dir=\"rtl\">מִתְקַשֶּׁה כנגדו</span> (the sun) refused to obey; a. e.</div><div class=\"sense\"><b>—5)</b> <i>to make one’s self obnoxious</i>. <span class=\"citation\">Gen. R. s. 61</span>; Yalk. Chr. 1073 (play on <a href=\"#\" data-headword=\"יַקְשָׁן\">יקשן</a>, <span class=\"citation\">Gen. XXV, 2</span>) <span dir=\"rtl\">שהיו מִתְקַשִּׁין בעולם</span> they were obnoxious to the world (were hard to deal with); (<span class=\"citation\">Midr. Till. to Ps. XCII</span> ed. Bub. <span dir=\"rtl\">שהיו בני אדם קשין</span>).</div></div>","alt":["קָשָׁה"]},"28034":{"h":"קְשֵׁי","r":"S02236","html":"<div class=\"sense\"><b>1)</b> <i>to be hard, difficult</i>. <span class=\"citation\">Targ. Deut. I, 17</span>. <span class=\"citation\">Ib. XV, 18</span>; a. e.—<span class=\"citation\">Yoma 28ᵇ</span> <span dir=\"rtl\">קָשׁוּ משמשא</span> are harder (on the eye) &amp;c., v. <a href=\"#\" data-headword=\"שַׁבְרִירֵי\">שַׁבְרִירֵי</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to find a thing difficult to understand, to object, argue against, dispute</i>. <span class=\"citation\">Y. Ter. V, 43ᶜ</span> bot. <span dir=\"rtl\">ר׳ סימון קַשְׁיְיתָהּ … קיימה</span> R. Simon argued against it (refuted it), but R. Ba. … proved it to be correct. Y. Kidd. III, 64ᶜ top [read:] <span dir=\"rtl\">לא כבר קְשׁוּנְתָּהּ הרי עולם לא כבר קַשְׁיְתָהּ וכ׳</span> have not mountains of the world (great scholars) disputed it? did not R. El. dispute it in the presence of &amp;c.; Y. Ned. VIII, 40ᵈ sq. (corr. acc.). <span class=\"citation\">B. Kam. 66ᵇ</span> האי מילתא ק׳ בה רבה לרב וכ׳ Rabbah argued this difficulty before R. Joseph for twenty-two years, and it was not solved; <span class=\"citation\">Keth. 42ᵇ</span> האי … קְשָׁאֵי רבה ורב וכ׳ Rabbah and R. Joseph discussed this difficulty &amp;c.—Part. <a href=\"#\" data-headword=\"קָשֵׁי\">קָשֵׁי</a>; f. <a href=\"#\" data-headword=\"קָשֵׁי\">קַשְׁיָא</a>, q. v.</div><div class=\"sense\"><b>—3)</b> <i>to get old</i>, v. <a href=\"#\" data-headword=\"קְשַׁשׁ II\"><span dir=\"rtl\">קְשַׁשׁ</span> II</a>.</div><div class=\"sense\"><b>Pa. קַשֵּׁי</b> <div class=\"sense\"><b>1)</b> <i>to be in pain of travailing</i>. <span class=\"citation\">Targ. Gen. XXXV, 17</span> <span dir=\"rtl\">בקַשָּׁיוּתָהּ</span> (not <span dir=\"rtl\">בקַשְׁיוּ׳</span>). <span class=\"citation\">Targ. O. ib. 16</span> (Y. II <i>Ithpa.</i>).</div><div class=\"sense\"><b>—2)</b> <i>to perplex</i>. <span class=\"citation\">Pes. 78ᵇ</span> <span dir=\"rtl\">מתניתן קַשִּׁיתֵיה וכ׳</span></div></div><div class=\"sense\"><b>Af. אַקְשֵׁי  אַקְשֵׁה</b> <div class=\"sense\"><b>1)</b> <i>to harden, make difficult</i>. <span class=\"citation\">Targ. Ex. VII, 3</span>. <span class=\"citation\">Targ. II Kings II, 10</span>. <span class=\"citation\">Targ. I Kings XII, 4</span>. <span class=\"citation\">Targ. Ps. XCV, 8</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be hard on, press heavily</i>. <span class=\"citation\">Cant. R. to II, 16</span> <span dir=\"rtl\">כד הוה צערא קשי עלוי … וכד הוה מַקְשֵׁי וכ׳</span></div><div class=\"sense\"><b>—3)</b> <i>to argue against, object, dispute</i>. <span class=\"citation\">Targ. Job VI, 6</span> Ms. Var. <span dir=\"rtl\">מדלית מַקְשׁה עליה</span> when there is none to dispute it.—<span class=\"citation\">Yeb. 77ᵃ</span> top <span dir=\"rtl\">א׳ להו דואג כל הני קושייתא</span> Doeg brought up before them all those arguments. Y. Yoma I, 38ᵈ bot. <span dir=\"rtl\">עד דאת מַקְשֵׁי … קְשַׁיְיתָהּ על וכ׳</span> (not <a href=\"#\" data-headword=\"קַשְׁיָיאתָא\">קשייתא</a>) instead of offering objection against R. J., rather offer it against &amp;c.; a. v. fr.</div></div><div class=\"sense\"><b>Ithpa. אִתְקֵשֵּׁי</b> </div><div class=\"sense\"><b>Ithpe. אִיקְּשֵׁי</b> <div class=\"sense\"><b>1)</b> <i>to be in pain of travailing</i>. <span class=\"citation\">Targ. Y. II, Gen. XXXV, 16</span>, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to be difficult, perplexing</i>. <span class=\"citation\">Yeb. 40ᵃ</span> <span dir=\"rtl\">ומִיקְּשֵׁה היא דאיקשי לך וכ׳</span> (Rashi <span dir=\"rtl\">דקשיא</span>) it was perplexing to thee, and thou didst reverse it.</div></div>","alt":["קְשֵׁה","קְשָׁא"]},"28035":{"h":"קְשִׁי","r":"S02237","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) = <a href=\"#\" data-headword=\"קוֹשִׁי\">קוֹשִׁי</a>, <i>hardness, stiffness; difficulty</i>. Tanḥ. Sh’laḥ ed. Bub., supplement 14 <span dir=\"rtl\">אל תבט בק׳ ערפם</span> look not at their stiffneckedness; <span class=\"citation\">Num. R. s. 16</span> end <a href=\"#\" data-headword=\"בַּקָּשָׁה\">בקשה</a> (corr. acc.).—Pl. <span dir=\"rtl\">קְשָׁיִין</span>. <span class=\"citation\">Sifré Deut. 305</span> <span dir=\"rtl\">אין חבר נקנה אלא בקשי ק׳</span> a friend can be acquired only with the greatest difficulty.</div>","alt":[]},"28036":{"h":"קָשֵׁי","r":"S02238","html":"<div class=\"sense\"> c. = h. <a href=\"#\" data-headword=\"קָשֶׁה\">קָשֶׁה</a>, <i>hard, strong, heavy, difficult</i>. <span class=\"citation\">Targ. Ex. VI, 9</span>. <span class=\"citation\">Targ. Y. ib. 12</span>. <span class=\"citation\">Targ. Gen. XLIX, 7</span>. <span class=\"citation\">Targ. Is. XIX, 4</span>. <span class=\"citation\">Targ. Ps. LX, 5</span>; a. fr.—<span class=\"citation\">Targ. Y. Num. VIII, 4</span> <span dir=\"rtl\">מינא ק׳</span> something hard to understand (v. <span class=\"citation\">Num. R. s. 15</span>, quot. s. v. <a href=\"#\" data-headword=\"קָשָׁה\">קָשָׁה</a> <i>Nithpa.</i>).—<span class=\"citation\">Yoma 28ᵇ</span> <span dir=\"rtl\">ק׳ משימשא</span> is harder to bear &amp;c., v. <a href=\"#\" data-headword=\"זוֹהֲמָא\">זוֹהֲמָא</a>. <span class=\"citation\">Ib. 29ᵃ</span> <a href=\"#\" data-headword=\"ק׳\">ק׳</a> ,<span dir=\"rtl\">מקייטא</span> v. <a href=\"#\" data-headword=\"קַיְטָא\">קַיְטָא</a>. <span class=\"citation\">B. Mets. 85ᵃ</span> <span dir=\"rtl\">ק׳ יומא דמיטרא וכ׳</span> a rainy day (preventing people from pursuing their vocations) is as hard as the day of judgment; <span class=\"citation\">Taan. 8ᵇ</span> <span dir=\"rtl\">קשה</span> (Rashi <a href=\"#\" data-headword=\"קשי\">קשי</a>); a. v. fr.—Pl. <span dir=\"rtl\">קָשִׁין</span>, <span dir=\"rtl\">קָשַׁיָּיא</span>, <span dir=\"rtl\">קָשָׁן</span>; <span dir=\"rtl\">קַשְׁיָין</span>, <a href=\"#\" data-headword=\"קַשְׁיָיאתָא\">קַשְׁיָיתָא</a>. <span class=\"citation\">Targ. I Sam. XX, 10</span>. <span class=\"citation\">Targ. II Sam. III, 39</span>. Targ. II Esth. IV, 1; a. fr.—<span class=\"citation\">Y. Sabb. VIII, 11ᵇ</span>. <span class=\"citation\">Koh. R. to III, 2</span> <span dir=\"rtl\">מן קל מיליא קַשְׁיָיאתָא וכ׳</span> on account of the hard things that I hear &amp;c.; a. e.</div>","alt":["(קְשֵׁי)","קַשְׁיָא I"]},"28037":{"h":"קַשְׁיָא II","r":"S02239","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָשֵׁי\">preced.</a>) <i>difficult, open to objection; unanswerable objection; contradiction</i>. <span class=\"citation\">Erub. 13ᵃ</span> <span dir=\"rtl\">הא גופא ק׳ וכ׳</span> this in itself is a contradiction; you said, R. I. did not say such a thing, which implies that this opinion is to be rejected, and then you said, this opinion is the adopted rule. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ שימוש אשימוש</span> there is a contradiction between the two narratives of R. Meir’s ministrations; <span dir=\"rtl\">ק׳ אסרה אאסרה</span> there is a contradiction between the relations concerning the teacher who forbade it; <span dir=\"rtl\">שימוש אשימוש לא ק׳ וכ׳</span> there is no contradiction between the two relations concerning the ministrations, (for I may say.) first he went &amp;c.; <span dir=\"rtl\">אלא אסרה אאסרה ק׳ ק׳</span> but between the relations as to who prohibited it, is there not a contradiction? There <i>is</i> a contradiction (it remains unanswered). <span class=\"citation\">Ber. 22ᵇ</span> <span dir=\"rtl\">לא ק׳ וכ׳</span> there is no contradiction (between the two traditions): the one speaks of a case where the thing is possible, the other &amp;c. <span class=\"citation\">Sabb. 22ᵇ</span> <a href=\"#\" data-headword=\"ק׳\">ק׳</a> the argument (of R. Papa) is unanswerable. Y. ib. XII, end, 13ᵈ <span dir=\"rtl\">וק׳ על דרבן וכ׳</span> and this is an argument against the opinion of Rabban G.; a. v. fr.</div>","alt":[]},"28038":{"h":"קַשְׁיָאתָא","r":"S02240","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַשְׁיְתָא\">קַשְׁיְתָא</a></div>","alt":[]},"28039":{"h":"קַשְׁיוּ","r":"S02241","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַשְׁיוּתָא\">קַשְׁיוּתָא</a></div>","alt":[]},"28040":{"h":"קַשְׁיוּת","r":"S02242","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַשְׁיוּ\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b>  (sub. <a href=\"#\" data-headword=\"עוֹרֶף\">עורף</a>) <i>stiffneckedness</i>; (sub. <a href=\"#\" data-headword=\"לֵב\">לב</a>) <i>hard-heartedness</i>. <span class=\"citation\">Taan. 6ᵃ</span>, v. <a href=\"#\" data-headword=\"מַלְקוֹשׁ\">מַלְקוֹשׁ</a>. Lam. R. introd. (R. Joḥ. 1) (play on <span dir=\"rtl\">מקשת אסרו</span>, <span class=\"citation\">Is. XXII, 3</span>) <span dir=\"rtl\">מקַשְׁיוּתָם נמסרו וכ׳</span> for their stubbornness they were given over to the governments. <span class=\"citation\">Gen. R. s. 53</span> (ref. to <span dir=\"rtl\">רבה קשת</span>, <span class=\"citation\">Gen. XXI, 20</span>) <span dir=\"rtl\">רָבָה וקַשְׁיוּתוֹ עמו</span> he (Ishmael) grew, and his stubbornness with him; [anoth. vers.] <span dir=\"rtl\">רבה וקשיותו אמו</span> he grew, and the cause of his renitence was his mother (who encouraged him in his sinful ways); a. e.</div><div class=\"sense\"><b>—2)</b> <i>erection, sensual desire</i>. Ib. s. 98 (play on <span dir=\"rtl\">קשתו</span>, <span class=\"citation\">Gen. XLIX, 24</span>) <span dir=\"rtl\">ק׳ שנִתְקַשֵּׁיתָה וכ׳</span> the sensual desire which seized thee when thou wast with thy mistress.</div>","alt":[]},"28041":{"h":"קַשְׁיוּתָא","r":"S02243","html":"<div class=\"sense\"><b>1)</b> <i>hardness, severity</i>. <span class=\"citation\">Targ. Ex. I, 14</span> (h. text <a href=\"#\" data-headword=\"פְּרַךְ I\">פרך</a>).</div><div class=\"sense\"><b>—2)</b> <i>stiffneckedness, renitence</i>. <span class=\"citation\">Y. Ber. VII, 11ᵇ</span> bot. <span dir=\"rtl\">עד כדון את בקַשְׁיוּתָךְ</span> dost thou still persist in thy renitence?; <span class=\"citation\">Koh. R. to VII, 11</span>. Y. Peah VII, 20ᵇ top. Esth. R. introd. (play on <span dir=\"rtl\">ממקשי</span>, <span class=\"citation\">Job XXXIV, 30</span>) <span dir=\"rtl\">מן קַשְׁיוּתֵיהֶן וחיביהן וכ׳</span> for the renitence and the guilt of men who do not the will of the Creator; a. e.</div>","alt":["קַשְׁיוּ"]},"28042":{"h":"קַשִּׁיט","r":"S02244","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשַׁט\">קְשַׁט</a>) <i>straight, upright, true</i>. <span class=\"citation\">Targ. Deut. XXXII, 4</span> (Y. ed. Vien. <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קָשִׁ׳</a>; h. text <span dir=\"rtl\">ישר</span>). Targ. Y. ib. VI, 5; a. e.—Pl. <span dir=\"rtl\">קַשִּׁיטִין</span>, <a href=\"#\" data-headword=\"קַשִּׁיט\">קְשִׁ׳</a>. Targ. O. ib. IV, 8 (h. text <span dir=\"rtl\">צדיק׳</span>). <span class=\"citation\">Targ. Num. XXIII, 10</span>; a. e.</div>","alt":["קַשִּׁיטָא","קְשִׁ׳"]},"28043":{"h":"קְשִׂיטָא","r":"S02245","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כְּסִיתָּא\">כְּסִיתָּא</a></div>","alt":[]},"28044":{"h":"קְשִׂיטָה","r":"S02246","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>Ḳ’siṭah</i>, name of a standard value; <i>a jewel</i>, also <i>a lamb</i> (v. <a href=\"#\" data-headword=\"*כְּסִיתָּא\">כְּסִיתָּא</a>). <span class=\"citation\">R. Hash. 26ᵃ</span> <span dir=\"rtl\">כשהלכתי … קורין למעה ק׳</span> when I was on my way to Africa, (I heard them) call a <i>m’ʿah ḳ’siṭah</i>; <span dir=\"rtl\">לפרושי מאה ק׳ דאורייתא</span> it serves to explain the Biblical ‘one hundred ḳ.’ (<span class=\"citation\">Gen. XXXIII, 19</span>). <span class=\"citation\">Gen. R. s. 79</span>, end, v. <a href=\"#\" data-headword=\"אוּנְקְיָא\">אוּנְקְיָא</a>.—V. <a href=\"#\" data-headword=\"חוּרְפָא\">חוּרְפָא</a>.</div>","alt":[]},"28045":{"h":"קַשִּׁיטוּתָא","r":"S02247","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַשִּׁיט\">קַשִּׁיט</a>) <i>uprightness</i>. Targ. II Esth. VIII, 13. <span class=\"citation\">Targ. O. Gen. XX, 5</span>, sq. (Y. <a href=\"#\" data-headword=\"קַשְׁטוּתָא\">קַשְׁטוּת</a>). <span class=\"citation\">Targ. Y. Deut. XXVIII, 47</span> ed. Lsb., v. <a href=\"#\" data-headword=\"שַׁפִּירוּתָא\">שַׁפִּירוּתָא</a>; a. e.</div>","alt":[]},"28046":{"h":"קַשְׁיָיאתָא","r":"S02248","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָשֵׁי\">קָשֵׁי</a>, a. <a href=\"#\" data-headword=\"קַשְׁיְתָא\">קַשְׁיְתָא</a>.</div>","alt":["קַשְׁיָיתָא"]},"28047":{"h":"קְשִׁירָא","r":"S02249","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">קְשִׁירֵי</span>, v. <a href=\"#\" data-headword=\"קִישּׁוּרָא\">קִישּׁוּרָא</a>.</div>","alt":[]},"28048":{"h":"קְשִׁירָה","r":"S02250","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָשַׁר\">קָשַׁר</a>) <i>knotting; tying</i>. <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span>; ib. XV, beg. 15ᵃ <span dir=\"rtl\">מה ק׳ וכ׳</span> what was the knotting done at the making of the Tabernacle? <span class=\"citation\">Y. Erub. III, 21ᵃ</span>, v. <a href=\"#\" data-headword=\"נְעִילָה\">נְעִילָה</a>.</div>","alt":[]},"28049":{"h":"קַשִּׁישׁ","r":"S02251","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשַׁשׁ I\">קְשַׁשׁ</a>) [<i>strong, hard</i>, cmp. <a href=\"#\" data-headword=\"יָשַׁן\">יָשַׁן</a>,] <i>old; old man, elder</i>. <span class=\"citation\">Targ. Job III, 18</span>. <span class=\"citation\">Targ. I Kings II, 22</span>; a. e.—<span class=\"citation\">B. Mets. 60ᵇ</span> אנא ק׳ מאבוך I am older than thy father. <span class=\"citation\">Yeb. 16ᵇ</span> <span dir=\"rtl\">מי ק׳ כוליה האי</span> was David so very old? <span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">ינוקא ק׳</span> the older child. <span class=\"citation\">Keth. 94ᵃ</span> אביי ק׳ Abaye senior; a. fr.—<span class=\"citation\">B. Bath. 142ᵇ</span> קַשִּׁישְׁנָא מינייכו I am older than you.—Pl. <a href=\"#\" data-headword=\"קִשִׁישִׁין\">קַשִּׁישִׁין</a>, <span dir=\"rtl\">קַשִּׁישַׁיָּא</span>, <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קַשִּׁישֵׁי</a>, <a href=\"#\" data-headword=\"קַשִּׁיט\">קְשִׁ׳</a>. <span class=\"citation\">Targ. Job XXXII, 6</span>. <span class=\"citation\">Ib. XII, 12</span>; a. e.—<span class=\"citation\">Hor. 11ᵇ</span> <span dir=\"rtl\">מי מלכי זוטרי מקמי ק׳</span> do the younger sons ascend the throne before the older? <span class=\"citation\">Ber. 30ᵃ</span> <span dir=\"rtl\">רבנן ק׳ מינן</span> teachers older than we are. <span class=\"citation\">Ib. 46ᵇ</span>. <span class=\"citation\">Cant. R. to VII, 9</span> (expl. <span dir=\"rtl\">הדברי</span>, <span class=\"citation\">Dan. III, 27</span>) <span dir=\"rtl\">ק׳ ואסטרולוגיסי</span> (not <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קשיש</a>) elders and astrologers; a. fr.</div>","alt":["קַשִּׁישָׁא","קָשִׁ׳"]},"28050":{"h":"קַשִּׁישׁוּתָא","r":"S02252","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַשִּׁישׁ\">preced.</a>) <i>old age, seniority</i>. <span class=\"citation\">B. Bath. 142ᵇ</span> <span dir=\"rtl\">מידי בק׳ וכ׳</span> does this depend on age? It depends on reason.</div>","alt":[]},"28051":{"h":"קִשִׁישִׁין","r":"S02253","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (קשש <i>to be straight, stiff</i>, v. <a href=\"#\" data-headword=\"קַשׁ\">קַשׁ</a>) <i>splints put about a fracture</i>. <span class=\"citation\">Sabb. 53ᵃ</span> <span dir=\"rtl\">ק׳ שעל גבי השבר</span> (Ms. M. <span dir=\"rtl\">כְּתִיתִין</span>, q. v.); <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">V), 5</span> <span dir=\"rtl\">בקַשְׁקַשִּׁין</span> ed. Zuck. (Var. <span dir=\"rtl\">בקְשׁוֹשִׁין</span>); Y. ib. V, 7ᵇ, sq. <a href=\"#\" data-headword=\"קִישׁוֹשׁוֹת\">קִישׁוֹשׁוֹת</a>.</div>","alt":[]},"28052":{"h":"קַשְׁיְתָא","r":"S02254","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשֵׁי\">קְשֵי</a>) <i>stone</i> of date or olive. <span class=\"citation\">Ḥull. 49ᵃ</span> <span dir=\"rtl\">האי ק׳ דאשתכחא וכ׳</span> (not <span dir=\"rtl\">דאשתכח</span>) a date stone was found in the gall &amp;c.—Pl. <a href=\"#\" data-headword=\"קַשְׁיָאתָא\">קַשְׁיָאתָא</a>, <a href=\"#\" data-headword=\"קַשְׁיָיאתָא\">קַשְׁיָיתָא</a>. <span class=\"citation\">Ber. 56ᵃ</span> thou shalt see in thy dream that the Romans capture thee <span dir=\"rtl\">וטחני בך ק׳ וכ׳</span> (different in Ms. M.) and make thee grind date stones in a golden mill. <span class=\"citation\">Yoma 79ᵇ</span> (prov.) <span dir=\"rtl\">תרי … דק׳ וכ׳</span> in two kabs of dates there is one kab of stones and more. <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">ק׳ דזיתי</span> olive stones.—V. <a href=\"#\" data-headword=\"קָשֵׁי\">קָשֵׁי</a>.</div>","alt":[]},"28053":{"h":"קִשְׁקוּשׁ","r":"S02255","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קִישְׁקוּשׁ\">קִישְׁ׳</a>.</div>","alt":["קִשְׁקוּשָׁא","קִשְׁקוּשֵׁי"]},"28054":{"h":"קִשְׁקֵשׁ I","r":"S02256","html":"<div class=\"sense\"> (<span dir=\"rtl\">קשש</span>; cmp, <a href=\"#\" data-headword=\"כִּשְׁכֵּשׁ\">כִּשְׁכֵּשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>to knock, strike, shake, tingle</i>. <span class=\"citation\">Sot. 9ᵇ</span> (ref. to <span dir=\"rtl\">לפעמו</span>, <span class=\"citation\">Jud. XIII, 25</span>) <span dir=\"rtl\">שהיתה שכינה מְקַשְׁקֶשֶׁת וכ׳</span> the Divine Presence rang before him as with a bell (v. <span dir=\"rtl\">פַּעֲמוֹן</span>); <span class=\"citation\">Gen. R. s. 18</span> לקַשְׁקֵשׁ ‘Rashi’, v. <a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>. <span class=\"citation\">Yalk. Ps. 862</span>, v. <a href=\"#\" data-headword=\"קִרְקֵשׁ\">קִרְקִשׁ</a>. <span class=\"citation\">Y. Sabb. II, 5ᵇ</span> bot. <span dir=\"rtl\">כיון … מקשקשת  עיסתה וכ׳</span> when the woman slaps her dough with water &amp;c. (v. <a href=\"#\" data-headword=\"לָטַשׁ\">לָטַשׁ</a>, a. <a href=\"#\" data-headword=\"קָטַף\">קָטַף</a>); <span class=\"citation\">Gen. R. s. 14</span>, beg. <span dir=\"rtl\">מְשַׁקְשֶׁקֶת</span>; <span class=\"citation\">Yalk. ib. 20</span>; <span class=\"citation\">32</span>; Tanḥ. Noah 1 (ed. Bub. <span dir=\"rtl\">נותנת מים בעיסה</span>, incorr.). <span class=\"citation\">Y. Taan. III, 67ᵃ</span> top <span dir=\"rtl\">כדי … ומקשקש וכ׳</span> when a person may be placed on the summit of ʿofel, and dangle his feet in the brook of Kidron; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">II), 1</span> <span dir=\"rtl\">מְשַׁקְשֵׁק</span> ed. Zuck. (Var. <span dir=\"rtl\">מְקַשְׁקֵישׁ</span>); Bab. <span class=\"citation\">Taan. 22ᵇ</span> <span dir=\"rtl\">וִישַׁכְשֵׁךְ</span>. <span class=\"citation\">Gen. R. s. 69</span> <span dir=\"rtl\">אפי׳ כן … מקשקשין וכ׳</span> yet it is for thy own good that they slap thee and polish (cleanse) thee from thy guilt (v. <a href=\"#\" data-headword=\"מָרַק\">מָרַק</a>); ib. s. 41 <span dir=\"rtl\">מְשַׁקְשְׁקִין</span>; <span class=\"citation\">Yalk. Is. 337</span>.</div><div class=\"sense\"><b>—2)</b> <i>to slap and crush the earth under the olive tree; to hoe</i>. <span class=\"citation\">B. Mets. 89ᵇ</span>, v. <a href=\"#\" data-headword=\"עָדַר\">עָדַר</a>. <span class=\"citation\">M. Kat. 3ᵃ</span> <span dir=\"rtl\">יכול לא יְקַשְׁקֵשׁ תחת וכ׳</span> lest you think that one may not hoe under the olive trees &amp;c. (in the Sabbatical year). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תשמטנה מלְקַשְׁקֵשׁ וכ׳</span> ‘thou shalt let it rest’ (<span class=\"citation\">Ex. XXIII, 11</span>) from hoeing &amp;c.; <span class=\"citation\">Succ. 44ᵇ</span>; <span class=\"citation\">Yalk. Ex. 354</span> (corr. acc.); a. e.</div><div class=\"sense\"><b>Hithpa. הִתְקַשְׁקֵשׁ</b> <div class=\"sense\"><i>to be shaken; to clap, ring</i>. <span class=\"citation\">Ḥull. 74ᵇ</span> <span dir=\"rtl\">כאגוז המִתְקַשְׁקֵשׁ וכ׳</span> like a nut that rattles in its shell. <span class=\"citation\">Ib. 94ᵃ</span> <span dir=\"rtl\">לגין המתקשקש</span> a bottle which gives a sound when shaken (half-filled). <span class=\"citation\">Ib. 125ᵃ</span> <span dir=\"rtl\">מוח המתק׳</span> brain that shakes in the skull; a. e.—[<span class=\"citation\">Nidd. 47ᵃ</span> <span dir=\"rtl\">משׁיִתְקַשְׁקְשׁוּ הדדין</span> when the breasts begin to shake (in walking), comment.; v., however, <a href=\"#\" data-headword=\"קִשְׁקֵשׁ II\"><span dir=\"rtl\">קִשְׁקֵשׁ</span> II</a>.]</div></div>","alt":[]},"28055":{"h":"קַשְׁקֵשׁ","r":"S02257","html":"<div class=\"sense\"><b>1)</b> <i>to knock, strike, ring</i>. <span class=\"citation\">Targ. Y. Gen. XLIII, 33</span>.</div><div class=\"sense\"><b>—2)</b> <i>to hoe</i>. <span class=\"citation\">Succ. 44ᵇ</span> לקַשְׁקוּשֵׁי כרמיא Ms. M. (ed. <span dir=\"rtl\">כרמים</span>) to hoe in vineyards. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומְקַשְׁקְשִׁין בכרמיא</span> and hoe in &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וקַשְׁקוּשֵׁי מי שרי</span> is it permitted to hoe (in the Sabbatical year)?; (<span class=\"citation\">M. Kat. 3ᵃ</span> <span dir=\"rtl\">וקִשְׁקוּשׁ בשביעית וכ׳</span>).</div>","alt":[]},"28056":{"h":"קִשְׁקֵשׁ II","r":"S02258","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קָשַׁשׁ II\"><span dir=\"rtl\">קָשַׁשׁ</span> II</a>) <i>to straighten, shoot forth</i>. Tosef. Erub. IX (VI), 26, v. <a href=\"#\" data-headword=\"קָשַׁט\">קָשַׁט</a>.</div><div class=\"sense\"><b>Hithpa. הִתְקַשְׁקֵשׁ</b> <div class=\"sense\"><i>to become stiff, hard, be erected</i>. <span class=\"citation\">Nidd. 47ᵃ</span> <span dir=\"rtl\">משׁיִתְקַשְׁקְשׁוּ הדדין</span> when the breasts become stiff; (Tosef. ib. VI, 4 <span dir=\"rtl\">משׁיִתְקַשּׁוּ</span>; Var. <span dir=\"rtl\">משיתקשקשו</span>).</div></div>","alt":[]},"28057":{"h":"קִשְׁקֵשׁ III","r":"S02259","html":"<div class=\"sense\"><i>to collect wood, rubbish</i> &amp;c., v. <a href=\"#\" data-headword=\"קָשַׁשׁ I\"><span dir=\"rtl\">קָשַׁשׁ</span> I</a>.</div>","alt":[]},"28058":{"h":"קַשְׁקַשִׁיּוֹת","r":"S02260","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַשְׁקַשִּׁים\">next w.</a></div>","alt":[]},"28059":{"h":"קַשְׁקַשִּׁים","r":"S02261","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קַשׁ\">קַשׁ</a>) <i>pieces of straw, chips</i> &amp;c. <span class=\"citation\">Keth. 60ᵃ</span> <span dir=\"rtl\">צינור שעלו בו ק׳</span> a spout into which rubbish entered (stopping its outflow); Tosef. Erub. XI (VIII), 10 <a href=\"#\" data-headword=\"קִישׁוֹשׁוֹת\">קִישׁוֹשׁוֹת</a> (Ar. ed. Koh. <a href=\"#\" data-headword=\"קִישׁוֹשׁוֹת\">קִישׁוֹשִׁיּוֹת</a>, oth. ed. <a href=\"#\" data-headword=\"קַשְׁקַשִׁיּוֹת\">קַשְׁקַשִּׁיּוֹת</a>).</div>","alt":[]},"28060":{"h":"קַשְׂקַשִּׂים","r":"S02262","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַשְׂקֶשֶׂת\">next w.</a></div>","alt":["קַשְׂקַשִּׂין"]},"28061":{"h":"קַשְׂקֶשֶׂת","r":"S02263","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [<i>incision</i>,] <i>rough skin, coat of scales</i>. <span class=\"citation\">Ḥull. III, 7</span>. <span class=\"citation\">Nidd. VI, 9</span>; <span class=\"citation\">Ḥull. 66ᵇ</span>, v. <a href=\"#\" data-headword=\"סְנַפִּיר\">סְנַפִּיר</a>. <span class=\"citation\">Ib. 27ᵇ</span> <span dir=\"rtl\">עופות … ק׳ ברגליהן וכ׳</span> fowls have on their feet a scaly skin like fishes, v. <a href=\"#\" data-headword=\"חַסְפְּנִיתָא\">חַסְפְּנִיתָא</a>. <span class=\"citation\">Ib. 66ᵇ</span> הוה אמינא מאי ק׳ סנפיר I might have thought <i>ḳasḳeseth</i> (rough skin) refers to fins. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וממאי דק׳ לבושא הוא</span> (Ms. R. 2 <span dir=\"rtl\">קלפי נינהו</span>) and whence do we learn that <i>ḳ</i>. means a covering (scales)? (Answ. ref. to <span class=\"citation\">I Sam. XVII, 5</span>); a. fr.—Sifra Sh’mini, Sh’ratsim, ch. IV, Par. 3 <span dir=\"rtl\">ק׳ אחת</span> one set of scales.—Pl. <a href=\"#\" data-headword=\"קַשְׂקַשִּׂים\">קַשְׂקַשִּׂים</a>, <a href=\"#\" data-headword=\"קַשְׂקַשִּׂים\">קַשְׂקַשִּׂין</a>. Ib. <span dir=\"rtl\">המרבה בק׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"סְנַפִּיר\">סְנַפִּיר</a>. Ib. (ref. to <span dir=\"rtl\">אפיקי מגנים</span>, <span class=\"citation\">Job XLI, 7</span>) <span dir=\"rtl\">אלו ק׳</span> that means scales; <span class=\"citation\">Ḥull. 67ᵇ</span>. <span class=\"citation\">Ib. III, 7</span> <span dir=\"rtl\">ואלו הן ק׳ הקבועין בו וכ׳</span> by <i>ḳaskassin</i> we mean those which are inflexible, by <i>s’nappirin</i> those with which the fish moves.—<span class=\"citation\">Tosef. Ohol. XVII, 3</span> <span dir=\"rtl\">שדה ק׳</span> (ed. Zuck. a. R. S. to Ohol. XVII, 1 <a href=\"#\" data-headword=\"קַסְקַסִּין\">קַסְקַסִּים</a>) a field full of scales (where all sorts of refuse are deposited).</div>","alt":[]},"28062":{"h":"קָשַׁר","r":"S02264","html":"<div class=\"sense\"> (b. h.) [<i>to strengthen</i>, v. <span class=\"citation\">Gen. XXX, 41</span>, sq.] <i>to join, knot, tie; to fold</i>. <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">הקוֹשֵׁר והמתיר</span> he that makes a knot or unties it. Y. ib. 10ᶜ <span dir=\"rtl\">שהיו קוֹשְׁרִין וכ׳</span> they knotted the ropes (of the Tabernacle). Ib. <span dir=\"rtl\">נפסק היה קוֹשְׁרוֹ</span> when a thread was broken (in weaving), one knotted it. <span class=\"citation\">Y. Gitt. VIII, end, 49ᵈ</span> <span dir=\"rtl\">אפי׳ קושר וכ׳</span> even if he folds (the document) up, and then has it signed. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בשׁקְשָׁרוֹ וחתמו וכ׳</span> when he folded it and had it signed inside; a. fr.—Trnsf. <i>a</i>) (cmp. <a href=\"#\" data-headword=\"חָרַז\">חָרַז</a>) <i>to compose and arrange</i> (<i>a funeral song or eulogy</i>). <span class=\"citation\">Y. Yoma I, 38ᵇ</span> <span dir=\"rtl\">קָשְׁרוּ הספידו</span> they arranged his eulogy. Lam. R. introd. (R. Joḥ. 1), v. <a href=\"#\" data-headword=\"מִסְפֵּד\">מִסְפֵּד</a>; a. fr.—<i>b</i>) <i>conceive, form an affection</i>. Pesik. B’shallaḥ, p. 80ᵃ <span dir=\"rtl\">הוא קושר לו אהבה וכ׳</span> he acquires love and affection for him; <span class=\"citation\">Gen. R. s. 54</span>; <span class=\"citation\">Yalk. Prov. 954</span>; a. e.—Part. pass. <a href=\"#\" data-headword=\"קִשּׁוּט\">קָשׁוּר</a>; f. <span dir=\"rtl\">קְשׁוּרָה</span> &amp;c. <span class=\"citation\">Y. Nidd. I, 49ᵇ</span> top <span dir=\"rtl\">אילו יהושע שהיה ק׳ למשה וכ׳</span> a Joshua who was tied to Moses (his constant attendant) could not have spoken so (that Moses had not said a certain thing), and he says so (of R. Jeremiah)? <span class=\"citation\">Erub. II, 1</span> <span dir=\"rtl\">קְשׁוּרוֹת</span>, v. <a href=\"#\" data-headword=\"נָתַר I\">נָתַר</a>. <span class=\"citation\">Y. Yeb. XVI, 15ᵈ</span> top, v. <a href=\"#\" data-headword=\"הֶסְפֵּד\">הֶסְפֵּד</a>; a. e.</div><div class=\"sense\"><b>Pi. קִישֵּׁר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קַשְׂקֶשֶׂת\">same</a>, esp. <i>to fold a document</i>, to write a portion and fold it and have witnesses signed on the fold, and so continue to the end of the document. Y. Gitt. l. c. <span dir=\"rtl\">היה מְקַשֵּׁר ראשון ראשון</span> if he folded up the signatures one by one; a. e.—Part. pass. <span dir=\"rtl\">מְקוּשָּׁר</span>. <a href=\"#\" data-headword=\"מוּקְדּוֹנְיָא\">מק׳</a> (<a href=\"#\" data-headword=\"גֵּט\">גט</a>) <i>a folded document</i>, opp. <a href=\"#\" data-headword=\"פָּשׁוּט\">פָּשׁוּט</a>. <span class=\"citation\">B. Bath. X, 1</span> <span dir=\"rtl\">גט פשוט … ומק׳ עדיו אחוריו</span> a plain document has its signatures of witnesses inside, a folded one, on its back. <span class=\"citation\">Ib. 160ᵃ</span> sq. (ref. to <span class=\"citation\">Jer. XXXII, 44</span>) <span dir=\"rtl\">וכתוב … וחתום זה מק׳</span> ‘and write the deed’, this refers to the plain document, ‘and sign’, this means the folded document; Y. ib. X, beg. 17ᶜ (ref. to Jer. ib. 11) <span dir=\"rtl\">את החתום זה המק׳ ואת הגלוי זה הפשוט שבמק׳</span> ‘the sealed’ means the folded, ‘and the open’ means the plain document which goes with the folded. Ib. bot. <span dir=\"rtl\">טופס שטרות מְקוּשָּׁרוֹת וכ׳</span> such is the formula of folded documents; a. fr.</div></div><div class=\"sense\"><b>Nif. נִקְשָׁר</b> <div class=\"sense\"><b>1)</b> <i>to be tied</i>. <span class=\"citation\">Snh. 108ᵇ</span> <span dir=\"rtl\">כלב נ׳</span> the dog was doomed to be tied.</div><div class=\"sense\"><b>—2)</b> <i>to be joined, harden, become knotty</i>. <span class=\"citation\">Shebi. III, 1</span> <span dir=\"rtl\">משׁיִקָּשֵׁר</span> (Mish. ed. <span dir=\"rtl\">משיקשור</span>, incorr.) when the <i>mathoḳ</i> (v. <a href=\"#\" data-headword=\"מָתוֹק II\"><span dir=\"rtl\">מָתוֹק</span> II</a>) gets knotty excrescences; (R. S.: when the dung in its juice becomes bound, begins to harden); expl. Y. ib. 34ᶜ top <span dir=\"rtl\">משיעשה קשרין קשרין</span> when it gets full of knotty excrescences; ib. <span dir=\"rtl\">מכיון שנקשר בו קשר וכ׳</span> R. S. to Shebi. l. c. (ed. <span dir=\"rtl\">שנִתְקַשֵּׁר</span>) as soon as the uppermost protuberance is formed, it begins to dry up.</div></div><div class=\"sense\"><b>Nithpa. נִתְקַשֵּׁר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קַשְׂקֶשֶׂת\">same</a>, <i>to become knotty; to become thick</i>. Y. Shebi. l. c., v. supra. <span class=\"citation\">Taan. 20ᵃ</span> <span dir=\"rtl\">נִתְקַשְּׁרוּ שמים וכ׳</span>, v. <a href=\"#\" data-headword=\"עָב II\"><span dir=\"rtl\">עָב</span> II</a>.</div></div><div class=\"sense\"><b>Hof. הוּקְשָׁר</b> <div class=\"sense\"><i>to be tied, joined</i>. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">יוּקְשְׁרוּ כולם אגודה וכ׳</span> let all of them be tied together with one band (of brotherhood; <span class=\"citation\">Yalk. ib. 651</span> <span dir=\"rtl\">יֵעָשׂוּ כולן וכ׳</span>).</div></div>","alt":[]},"28063":{"h":"קֶשֶׁר","r":"S02265","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קָשַׁר\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>knot, band, loop</i>. <span class=\"citation\">Sabb. XV, 1</span> <span dir=\"rtl\">ק׳ הגמלין</span> a knot like that which the camel drivers make (v. <a href=\"#\" data-headword=\"זְמַם ²\">זְמָמָא</a>); <span dir=\"rtl\">ק׳ הספנין</span> the sailors’ knot (v. <a href=\"#\" data-headword=\"אִיסְטְרִידָא\">אִיסְטְרִידָא</a>). Ib. 111ᵇ <span dir=\"rtl\">ק׳ שאינו של קיימא</span> a knot which is not intended to be permanent, a temporary knot. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">ק׳ של תפלין</span> the knot in the band of the T’fillin (resting on the back of the head); a. v. fr.—Trnsf. <i>union, conspiracy</i>. <span class=\"citation\">Snh. 26ᵃ</span> (ref. to <span class=\"citation\">Is. VIII, 12</span>) <span dir=\"rtl\">ק׳ רשעים הוא וק׳ רשעים אינו וכ׳</span> it is a council of wicked men &amp;c., v. <a href=\"#\" data-headword=\"מִנְיָן\">מִנְיָן</a>.—Pl. <span dir=\"rtl\">קְשָׁרִים</span>, <span dir=\"rtl\">קְשָׁרִין</span>. <span class=\"citation\">Sabb. XV, 1</span>. <span class=\"citation\">Bekh. 30ᵇ</span>; <span class=\"citation\">Ab. Zar. 39ᵃ</span> <span dir=\"rtl\">קִשְׁרֵי מוכס</span>, v. <a href=\"#\" data-headword=\"מוֹכֵס\">מוֹכֵס</a>. <span class=\"citation\">Mikv. X, 3</span> <span dir=\"rtl\">קשרי העני</span> the knots in the poor man’s garment. Tanḥ. Korah 12 <span dir=\"rtl\">ח׳ חוטין וה׳ ק׳</span> eight threads (of the show fringe) and five knots; <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">ח׳ גרורין וה׳ קִשּׁוּרִין</span>. <span class=\"citation\">Sabb. VI, 9</span> <span dir=\"rtl\">הבנים יוצאין בק׳</span> children may go out (on the Sabbath) with garlands, v. <a href=\"#\" data-headword=\"פּוּאָה\">פּוּאָה</a>; a. fr.—<span class=\"citation\">Sot. VIII, 5</span> <span dir=\"rtl\">קשרי המלחמה</span> the joined ranks in battle (Y. ed. <a href=\"#\" data-headword=\"קִישּׁוּי\">קישוי</a>, corr. acc.); Y. ib. VIII, end, 23ᵃ <span dir=\"rtl\">קִישְׁרֵי המלחמות</span>.—2) <i>protuberance, joint</i>. <span class=\"citation\">Y. Shebi. III, 34ᶜ</span> top, v. <a href=\"#\" data-headword=\"קָשַׁר\">preced.</a> <span class=\"citation\">Gen. R. s. 10</span> (ref. to <span class=\"citation\">Job XXXVIII, 31</span>) <span dir=\"rtl\">כסיל מושך בין ק׳ לק׳</span> the planet K’sil draws (the connection) between bud and bud (v. <a href=\"#\" data-headword=\"עָדַן\">עָדַן</a> <i>Hif.</i>); a. e.—<i>Pl.</i> as ab. Y. Shebi. l. c., v. <a href=\"#\" data-headword=\"קָשַׁר\">preced.</a> <span class=\"citation\">Nidd. 52ᵇ</span> <span dir=\"rtl\">קשרי אצבעותיה של יד</span> the joints of her fingers; <span dir=\"rtl\">של רגל</span> of her toes. <span class=\"citation\">Y. Ber. VIII, 12ᵃ</span> bot. <span dir=\"rtl\">עד קישרי אצבעותיו</span> to the second joints of the fingers, contrad. to <a href=\"#\" data-headword=\"פֶּרֶק\">פֶּרֶק</a>, q. v.; a. e.</div><div class=\"sense\"><b>—3)</b> <i>fold</i> of a document, <i>plicature</i>. <span class=\"citation\">B. Bath. 160ᵇ</span> <span dir=\"rtl\">בין ק׳ לק׳</span> the witnesses sign between the folds; a. fr.—Pl. as ab. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מתוך שנתרבה בקְשָׁרָיו וכ׳</span> because it has many folds, it must have many witnesses. <span class=\"citation\">Gitt. VIII, 10</span> (expl. <span dir=\"rtl\">גט קרח</span>, v. <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a>) <span dir=\"rtl\">כל שקשריו מרובין וכ׳</span> which has more folds than signatures of witnesses; a. fr.</div>","alt":[]},"28064":{"h":"קִירְקָנוֹת","r":"S01202","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">קירקרנ׳</span>, v. <a href=\"#\" data-headword=\"קִירְקוּר\">preced.</a>) <i>clappers</i>, a sort of <i>castanets</i>, used at wedding processions. <span class=\"citation\">Pesik. R. s. 43</span> <span dir=\"rtl\">טוענים קי׳ וכ׳</span> (ed. Fr. <span dir=\"rtl\">קו׳</span>) carrying castanets and marching before her.</div>","alt":["קוּרְ׳"]},"28065":{"h":"קִירְקָנֵי","r":"S01203","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קִירְקָנוֹת\">preced.</a> wds.) <i>croaking</i>. <span class=\"citation\">Ned. 51ᵃ</span> שתינא … ובק׳ דאימן I shall drink wine to thy father’s dancing and thy mother’s croaking (singing); [Rashi: <i>handing the cup</i>].</div>","alt":[]},"28066":{"h":"קירקוסיי","r":"S01204","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Kings 222</span>, v. <a href=\"#\" data-headword=\"קוּרְקְסָא\">קוּרְקְסָא</a></div>","alt":[]},"28067":{"h":"קִישׁ I","r":"S01205","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Kish</i>, the father of king Saul. <span class=\"citation\">Meg. 12ᵇ</span> <span dir=\"rtl\">בן ק̇יש̇ הק̇יש̇ וכ׳</span>, v. <a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>; a. e.</div>","alt":[]},"28068":{"h":"קִישׁ II","r":"S01206","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>) <i>clapping, the sound ḳish-ḳish</i>. <span class=\"citation\">B. Mets. 85ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּישׁ\">כִּישׁ</a>.</div>","alt":[]},"28069":{"h":"קִישׁ III","r":"S01207","html":"<div class=\"sense\">, part. of <a href=\"#\" data-headword=\"קְשַׁשׁ II\"><span dir=\"rtl\">קְשַׁשׁ</span> II</a>.</div>","alt":[]},"28070":{"h":"קִישְׁבָּא","r":"S01208","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִשְׁבָּא\">קִשְׁבָּא</a></div>","alt":[]},"28071":{"h":"קִישּׁוּאִים","r":"S01209","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִשּׁוּאִים\">קִשּׁוּאִים</a></div>","alt":["קִישּׁוּאִין"]},"28072":{"h":"קִישּׁוּט","r":"S01210","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָשַׁט\">קָשַׁט</a>) <i>dress, toilet, ornament.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"קִישּׁוּאִים\">קִישּׁוּטִים</a>, <a href=\"#\" data-headword=\"קִישּׁוּאִים\">קִישּׁוּטִין</a>, <a href=\"#\" data-headword=\"קִישּׁוּט\">קִשּׁ׳</a>. <span class=\"citation\">Lam. R. to II, 13</span> (play on <span dir=\"rtl\">אעידך</span>, ib.; cmp. <a href=\"#\" data-headword=\"עֲדִי II\"><span dir=\"rtl\">עֲדִי</span> II</a>) <span dir=\"rtl\">כמה ק׳ קשטתי אתכם</span> with how many ornaments did I adorn you!; Pesik. Naḥ., p. 124ᵇ. <span class=\"citation\">Keth. 71ᵇ</span> <span dir=\"rtl\">נהנית מריח קִשּׁוּטֶיהָ וכ׳</span> is benefited by the perfume of her toilet for thirty days (can be thirty days without perfumery). <span class=\"citation\">Ib.</span> (in Chald. diction) <span dir=\"rtl\">דתלנהו לקשוטיה וכ׳</span> (read: <span dir=\"rtl\">דתלתנהו</span>) when she attached her vow of abstinence from perfuming herself to marital intercourse &amp;c.; a. e.</div>","alt":["קִשּׁ׳"]},"28073":{"h":"קִישּׁוּטָא","r":"S01211","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XLIX, 18</span> <a href=\"#\" data-headword=\"קִישּׁוּט\">קִישּׁוּט</a> constr. (ed. Wil. <span dir=\"rtl\">קָשׁוּט</span>, corr. acc.).—Pl. <span dir=\"rtl\">קִישּׁוּטַיָּא</span>, <a href=\"#\" data-headword=\"קִישּׁוּט\">קִשּׁ׳</a>. <span class=\"citation\">Targ. Jer. II, 32</span> <a href=\"#\" data-headword=\"קִישּׁוּטָא\">קִישּׁוּטָהָא</a> (h. text <span dir=\"rtl\">קִשְּׁרֶיהָ</span>).</div>","alt":["קִשּׁ׳"]},"28074":{"h":"קִישּׁוּי","r":"S01212","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָשָׁה\">קָשָׁה</a>) <i>protracted travailing, laws of cleanness concerning discharges during protracted travailing</i>. <span class=\"citation\">Nidd. IV, 5</span> (<span class=\"citation\">36ᵇ</span>) <span dir=\"rtl\">כמה הוא קִשּׁוּיָהּ</span> (Bab. ed. <span dir=\"rtl\">היא קִישּׁ׳</span>) how long may her travailing last (in order to apply to her the laws concerning &amp;c.)?; <span class=\"citation\">Yeb. 83ᵃ</span>; Y. ib. IV, 6ᵃ; <span class=\"citation\">Y. Nidd. I, 49ᵇ</span> top <span dir=\"rtl\">קִישּׁוּיָיהּ</span>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">אין ק׳ יותר וכ׳</span> the laws apply only during two weeks. Bab. <span class=\"citation\">Nidd. 66ᵃ</span> <span dir=\"rtl\">אין ק׳ לנפלים</span> the law of <i>ḳishshuy</i> does not apply to cases of abortion; a. e.</div>","alt":["קִשּׁ׳"]},"28075":{"h":"קִישּׁוּיָא","r":"S01213","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשֵׁי\">קְשֵׁי</a>) <i>objection, argument</i>.—Pl. <a href=\"#\" data-headword=\"קִישּׁוּי\">קִישּׁוּיֵי</a>. <span class=\"citation\">Y. Pes. VII, 35ᵇ</span> top <span dir=\"rtl\">לית ליה כאילין ק׳</span> (not <a href=\"#\" data-headword=\"קִישּׁוּיָא\">קישויא</a>) does not agree with those arguments (does not consider them convincing).</div>","alt":[]},"28076":{"h":"קִישּׁוּר","r":"S01214","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָשַׁר\">קָשַׁר</a>) <i>binding, contraction</i>. <span class=\"citation\">Sabb. 16ᵇ</span> <span dir=\"rtl\">בשעת ק׳ עבים</span> when the clouds were gathering, opp. <a href=\"#\" data-headword=\"פִּיזּוּר\">פיזור</a>. <span class=\"citation\">Ib. XV, 1</span> <span dir=\"rtl\">כשם שהוא חייב על קִישּׁוּרָן וכ׳</span> as well as he is guilty (of violating the Sabbath laws), when he ties them (the knots) &amp;c., opp. <span dir=\"rtl\">התיר</span>. Y. ib. IV, 7ᵃ top; a. e.—Pl. <a href=\"#\" data-headword=\"קִישּׁוּאִים\">קִישּׁוּרִים</a>, <a href=\"#\" data-headword=\"קִישּׁוּט\">קִשּׁ׳</a> (b. h. <span dir=\"rtl\">קִשֻּׁרִים</span>) <i>beads, decorations</i>. <span class=\"citation\">Pirké d’R. El. ch. XXXII</span>, end <span dir=\"rtl\">ככלה בקִשּׁוּרֶיהָ</span> like a bride in her attire; <span class=\"citation\">Yalk. Gen. 114</span>. <span class=\"citation\">Sabb. 66ᵇ</span> (expl. <span dir=\"rtl\">קשרים</span>, Mish. <span class=\"citation\">ib. VI, 9</span>), <span dir=\"rtl\">קִשּׁוּרֵי פואה</span> (Ms. M. <span dir=\"rtl\">קישור פיאה</span>), v. <a href=\"#\" data-headword=\"פּוּאָה\">פּוּאָה</a>; Y. ib. VI, 8ᶜ <span dir=\"rtl\">בקושרי פיאה</span> (corr. acc.); a. e.</div>","alt":["קִשּׁ׳"]},"28077":{"h":"קִישּׁוּרָא","r":"S01215","html":"<div class=\"sense\"> <span class=\"citation\">Y. Sabb. IV, 7ᵃ</span> top <span dir=\"rtl\">קִישּׁוּרֵיה דרב וכ׳</span> the tying of which Rab speaks, referring to tying twigs for the purposes of a tent; <span dir=\"rtl\">קישוריה דר׳ אבא</span> the tying of which R. Abba speaks, referring to tying twigs for the purpose of making an implement (seats); a. e.—Pl. <a href=\"#\" data-headword=\"קִישּׁוּר\">קִישּׁוּרֵי</a>. Bab. <span class=\"citation\">Sabb. 66ᵇ</span> ק׳ Ms. M. a. Rashi (ed. <span dir=\"rtl\">קשירי</span>) a sort of <i>stilts</i>, tied to the legs; v. <a href=\"#\" data-headword=\"*אָנְקִטְמִין\">אָנְקִטְמִין</a>.</div>","alt":["קִשּׁ׳"]},"28078":{"h":"קִישׁוֹשׁוֹת","r":"S01216","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (קָשַׁשׁ I) </div><div class=\"sense\"><b>1)</b> <i>rakings, chips</i>. <span class=\"citation\">Tosef. Shebi. II, 14</span>. Tosef. Erub. XI (VIII), 10 (Ar. ed. Koh. <a href=\"#\" data-headword=\"קִישׁוֹשׁוֹת\">קִישׁוֹשִׁיּוֹת</a>; oth. ed. <a href=\"#\" data-headword=\"קַשְׁקַשִׁיּוֹת\">קַשְׁקַשִּׁיּוֹת</a>), v. <a href=\"#\" data-headword=\"קַשְׁקַשִּׁים\">קַשְׁקַשִּׁים</a>.</div><div class=\"sense\"><b>—2)</b> <i>splints put on a fracture</i>, v. <a href=\"#\" data-headword=\"קִשִׁישִׁין\">קְשִׁישִׁין</a>.</div>","alt":[]},"28079":{"h":"קִישׁוּת I","r":"S01217","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כָּשׁוּת\">כָּשׁוּת</a>) [<i>tufted fruit</i>,] <i>cucumber</i> (<i>sing</i>, a. <i>pl.</i>). <span class=\"citation\">Tosef. Dem. V, 10</span> <span dir=\"rtl\">ניטל מכל ק׳ וק׳</span> he takes tithe from each bunch of cucumbers. <span class=\"citation\">Ter. III, 1</span> <span dir=\"rtl\">התורם ק׳ ונמצאת וכ׳</span> if one separates a cucumber for T’rumah, and it is found to be bitter. <span class=\"citation\">Tosef. ib. IV, 5</span> <span dir=\"rtl\">אין לך מר בק׳ וכ׳</span> there is nothing bitter in the cucumber except the central part (the central cucumber in the bunch (?)); a. e.—<i>Pl.</i> (v. supra). <span class=\"citation\">Ib. V, 14</span>. <span class=\"citation\">Sabb. 109ᵃ</span> Ar. s. v. <a href=\"#\" data-headword=\"טָרִז\">טרז</a>; v. <a href=\"#\" data-headword=\"כָּשׁוּת\">כָּשׁוּת</a>.—V. <a href=\"#\" data-headword=\"קִשּׁוּאִים\">קִשּׁוּאִים</a>.</div>","alt":[]},"28080":{"h":"קִישׁוּת II","r":"S01218","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>) <i>comparison, likeness</i>. <span class=\"citation\">Gen. R. s. 35</span> (play on <span dir=\"rtl\">קַשְׁתִּי</span>, <span class=\"citation\">Gen. IX, 13</span>) <span dir=\"rtl\">קִישׁוּתִי וכ׳</span> my likeness, that which comes near to me (the halo of glory); Yalk. ib. 61 <span dir=\"rtl\">קָשׁוּתִי</span>; v. <a href=\"#\" data-headword=\"קַשָּׁא I\"><span dir=\"rtl\">קַשָּׁא</span> I</a>.</div>","alt":[]},"28081":{"h":"קִישָׁן","r":"S01219","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>) <i>one whose legs knock against each other, bandy-legged</i>. <span class=\"citation\">Bekh. 45ᵃ</span>; <span class=\"citation\">Tosef. ib. V, 9</span> <span dir=\"rtl\">היַקְשָׁן</span> (ed. Vien. <span dir=\"rtl\">העַקְשָׁן</span>, cmp. <a href=\"#\" data-headword=\"עִקֵּשׁ I\">עָקַשׁ</a>).</div>","alt":[]},"28082":{"h":"קִישְׁקוּשׁ","r":"S01220","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קִשְׁקֵשׁ I) <i>hoeing the ground</i> (around olive trees). <span class=\"citation\">M. Kat. 3ᵃ</span> <span dir=\"rtl\">מנין לעידור וק׳ וכ׳</span> whence is it learned that hoeing of vines, and hoeing of olive trees, and clearing are forbidden in the Sabbatical year? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וק׳ … שרי</span> is hoeing in the Sabbatical year permitted?; <span class=\"citation\">Succ. 44ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"קִשְׁקוּשׁ\">קַשְׁקוּשֵׁי</a>).</div>","alt":["קִשְׁ׳"]},"28083":{"h":"קִישְׁקוּשָׁא","r":"S01221","html":"<div class=\"sense\">—Pl. <a href=\"#\" data-headword=\"קִשְׁקוּשׁ\">קִישְׁקוּשֵׁי</a>, <a href=\"#\" data-headword=\"קִישְׁקוּשׁ\">קִשְׁ׳</a>. <span class=\"citation\">M. Kat. 3ᵃ</span>; <span class=\"citation\">Succ. 44ᵇ</span>; <span class=\"citation\">Yalk. Ex. 354</span> <span dir=\"rtl\">תרי ק׳ הוו וכ׳</span> there are two kinds of hoeing, one intended to make the tree stronger &amp;c., v. <a href=\"#\" data-headword=\"פִּילָא III\"><span dir=\"rtl\">פִּילָא</span> III</a>.</div>","alt":["קִשְׁ׳ I"]},"28084":{"h":"קִישְׁקוּשָׁא ²","r":"S01222","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">קשש</span>; cmp. <span class=\"citation\">Zeph. II, 1</span>) <i>gathering place</i> (in war times); <i>tower, fort</i>.—Pl. <a href=\"#\" data-headword=\"קִשְׁקוּשׁ\">קִישְׁקוּשֵׁי</a>, <a href=\"#\" data-headword=\"קִישְׁקוּשׁ\">קִשְׁ׳</a>. <span class=\"citation\">Sabb. 11ᵃ</span> <span dir=\"rtl\">אבל בק׳ וכ׳</span> but as to towers and turrets, we care not (they may be higher than the synagogue).</div>","alt":["קִשְׁ׳ II"]},"28085":{"h":"קִישְׁר־","r":"S01223","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֶשֶׁר\">קֶשֶׁר</a></div>","alt":[]},"28086":{"h":"קִישַׁרְתָּא","r":"S01224","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוֹשַׁרְתָּא\">קוֹשַׁרְתָּא</a></div>","alt":[]},"28087":{"h":"קישת","r":"S01225","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Nidd. V, 8</span>, v. <a href=\"#\" data-headword=\"קָשָׁה\">קָשָׁה</a><i>Pi.</i></div>","alt":[]},"28088":{"h":"קִיתוֹן","r":"S01226","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κώθων, confounded with κύαθος) <i>ladle</i> for drawing wine out of the mixing bowl into the cup; also for washing hands. <span class=\"citation\">Tosef. Bets. II, 9</span>; <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 13</span> <span dir=\"rtl\">ממלא הוא … או ק׳ לשתות וכ׳</span> he may (dip in and) fill a cup, bucket or ladle for drinking purposes, and intend to immerse them (for ritual purposes). <span class=\"citation\">Ib. XIV</span> (<span class=\"citation\">XV), 3</span>. <span class=\"citation\">Succ. II, 9</span> <span dir=\"rtl\">לעבד … ק׳ וכ׳</span> like the case of a servant that comes in to mix the cup for his master, and he pours the ladle in his face; <span class=\"citation\">ib. 29ᵃ</span> <span dir=\"rtl\">שפך לו רבו ק׳ וכ׳</span> his master poured &amp;c. <span class=\"citation\">Snh. 52ᵇ</span> <span dir=\"rtl\">בתחלה דומה לק׳ וכ׳</span> at first acquaintance he (the scholar) appears to him (the ignorant man) like a golden <i>kithon</i>; if he holds conversation with him, he appears like a silver <i>kithon</i>; if he accepts a benefit of him, he appears like an earthen <i>kithon</i>, which once broken cannot be mended. <span class=\"citation\">Yoma IV, 5</span> <span dir=\"rtl\">מקדש … מן הק׳ וכ׳</span> he sanctifies his hands and feet with a golden ladle; a. fr.—<span class=\"citation\">Yalk. Sam. 124</span> <span dir=\"rtl\">נטל קטן השמן וכ׳</span> (corr. acc.) he took the pitcher of oil and poured &amp;c.—Pl. <a href=\"#\" data-headword=\"קִיצוֹנִים\">קִיתוֹנִים</a>, <a href=\"#\" data-headword=\"קִיפוֹנוֹת\">קִיתוֹנוֹת</a>. <span class=\"citation\">Sifré Num. 158</span>. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 1</span> <span dir=\"rtl\">הלבס כדי לקבל ק׳ וכ׳</span> a defective caldron remains susceptible of levitical uncleanness so long as there is enough left to receive ladles, ladles, so long as they can contain small coins. <span class=\"citation\">Gen. R. s. 74</span> <span dir=\"rtl\">קִיתוֹנִיּוֹת</span>; <span class=\"citation\">Yalk. ib. 130</span> <span dir=\"rtl\">קיתונות</span>; a. e.</div>","alt":[]},"28089":{"h":"קִיתוֹן ²","r":"S01227","html":"<div class=\"sense\"> <span class=\"citation\">Esth. R. to II, 1</span> (introd.) the drunkard says, <span dir=\"rtl\">מה דהדין ק׳ דנחשא וכ׳</span> what this copper ladle serves for, an earthen ladle will do &amp;c. <span class=\"citation\">Y. Kidd. III, 64ᵃ</span> <span dir=\"rtl\">הב לי ק׳ דאית וכ׳</span> give me the <i>cyathus</i> which I have with thee; <span dir=\"rtl\">הב לי קותונה וכ׳</span> (read: <a href=\"#\" data-headword=\"*קִילוֹנִי\">קִיתוֹנִי</a>) give me my <i>cyathus</i>, and get the Denar (which I owe thee). <span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> <span dir=\"rtl\">הוה ליה קווקין וכ׳</span> (corr. acc.) had a ladle on which was the figure of a Roman deity; <span dir=\"rtl\">אהן ק׳ מכיון וכ׳</span> a ladle, since it is dipped in water, is considered a common vessel (ornamentations of which have no idolatrous character); a. e.—Pl. <span dir=\"rtl\">קַיתוֹנַיָּא</span>. <span class=\"citation\">Targ. Y. Num. XXXI, 23</span> (ed. Amst. <a href=\"#\" data-headword=\"קתוניא\">קַתּוּנְיָא</a>, corr. acc.).</div>","alt":["קִיתוֹנָא"]},"28090":{"h":"קִיתְרֹס","r":"S01228","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַתְרוֹס III\"><span dir=\"rtl\">קַתְרוֹס</span> III</a></div>","alt":[]},"28091":{"h":"קַל I","r":"S01229","html":"<div class=\"sense\"><i>to be light</i>, v. <a href=\"#\" data-headword=\"קָלַל\">קָלַל</a>.</div>","alt":[]},"28092":{"h":"קַל II","r":"S01230","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קַל I\">preced.</a>) <i>light</i>; </div><div class=\"sense\"><b>1)</b> <i>unimportant, of minor value; easy to achieve</i>.—<span dir=\"rtl\">קל וחומר</span>, v. <a href=\"#\" data-headword=\"חוֹמֶר I\"><span dir=\"rtl\">חוֹמֶר</span> I</a>. <span class=\"citation\">Ḥull. XII, 5</span> <span dir=\"rtl\">מצוה ק׳ שהיא כאיסר</span> a slight religious act which is performed at a sacrifice of one Isar. <span class=\"citation\">Y. Kidd. I, 61ᵇ</span> bot. <span dir=\"rtl\">השוה הכתוב מצוה ק׳ שבקַלּוֹת וכ׳</span> the Bible put the lightest of the light acts (<span class=\"citation\">Deut. XXII, 7</span>) on the same level with the most serious (<span class=\"citation\">Ex. XX, 12</span>). Tosef. Yoma V (IV), 4 <span dir=\"rtl\">מאכילין אותו הקל הקל</span> you must give him to eat (of forbidden things on hand) that which is of comparatively minor import; a. fr.—Pl. <a href=\"#\" data-headword=\"קַלִּי\">קַלִּים</a>, <span dir=\"rtl\">קַלִּין</span>; <a href=\"#\" data-headword=\"קַלּוּת\">קַלּוֹת</a>.—<span dir=\"rtl\">קלים וחמורים</span>, v. <a href=\"#\" data-headword=\"חוֹמֶר I\"><span dir=\"rtl\">חוֹמֶר</span> I</a>.—<span class=\"citation\">Dem. I, 1</span> <span dir=\"rtl\">הק׳ שבדמאי</span> those fruits with which, in cases of doubt as to tithes (v. <a href=\"#\" data-headword=\"דְּמַאי\">דְּמַאי</a>), the law deals most leniently. <span class=\"citation\">Yoma VIII, 8</span> <span dir=\"rtl\">על עבירות ק׳</span> for minor transgressions (to which the lowest penalty is attached); ib. 85ᵇ <span dir=\"rtl\">אלו הן ק׳ וכ׳</span> these are the minor transgressions: omission of a positive command &amp;c. (v. <a href=\"#\" data-headword=\"עָשָׂה\">עָשָׂה</a>); Tosef. ib. V (IV), 5. <span class=\"citation\">R. Hash. 25ᵇ</span>, a. e. <span dir=\"rtl\">שלשה קַלֵּי עולם</span> the three worthless (chiefs) in Israel’s history, opp. <span dir=\"rtl\">חמורי עולם</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אפי׳ קל שבק׳ וכ׳</span> (not <span dir=\"rtl\">קלין</span>) even the most worthless of worthless men, if once appointed a leader, should be respected like the strongest &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>lowly, poor.</i>—<i>Pl.</i> as ab. <span class=\"citation\">Arakh. 24ᵃ</span> <span dir=\"rtl\">שלא ישהא מרגלית לק׳</span> one must not delay the valuation of a jewel dedicated for its value by poor men (for the sake of taking it to a large town where a higher price can be obtained, but it must go by its local value); <span class=\"citation\">ib. 18ᵃ</span> <span dir=\"rtl\">מרגלית לק׳</span> as to local valuation.</div><div class=\"sense\"><b>—3)</b> <i>quick</i>. <span class=\"citation\">Ab. III, 12</span>, v. <a href=\"#\" data-headword=\"נוֹחַ II\"><span dir=\"rtl\">נוֹחַ</span> II</a>. <span class=\"citation\">Ib. V, 20</span> <span dir=\"rtl\">הוי … קל כנשר וכ׳</span> be … swift as an eagle, and run like a deer to do the will of thy Father in heaven. <span class=\"citation\">Sabb. VIII, 5</span> <span dir=\"rtl\">ביצה ק׳ שבבצים</span> the lightest of eggs; expl. <span class=\"citation\">ib. 80ᵇ</span> <span dir=\"rtl\">ק׳ לבשל</span> quick to boil; Y. ib. VIII, 11ᵇ top. <span class=\"citation\">Gen. R. s. 16</span>, v. <a href=\"#\" data-headword=\"חַד I\"><span dir=\"rtl\">חַד</span> I</a>. <span class=\"citation\">Keth. 112ᵃ</span> (ref. to <span class=\"citation\">Jer. III, 19</span> <span dir=\"rtl\">נחלת צבי</span>) <span dir=\"rtl\">מה צבי זה קל … ק׳ לבשל וכ׳</span> as the deer is the swiftest of beasts, so the land of Israel is the swiftest of all lands to ripen its fruits. <span class=\"citation\">Ex. R. s. 19</span>, a. fr. <span dir=\"rtl\">לשעה קלה</span> after a short time; a. fr.—<i>Pl.</i> as ab. Gen. R. l. c.; a. e.</div>","alt":["קַלָּה"]},"28093":{"h":"קַל III","r":"S01231","html":"<div class=\"sense\"> c. = h. <a href=\"#\" data-headword=\"קוֹל\">קוֹל</a>, <i>voice, sound; rumor</i>. <span class=\"citation\">Targ. Ez. XI, 13</span>. <span class=\"citation\">Targ. Gen. XXVII, 22</span>. <span class=\"citation\">Targ. Ps. XCII, 12</span>; a. fr.—<span class=\"citation\">M. Kat. 18ᵇ</span> <span dir=\"rtl\">ק׳ דלא פסיק</span>, v. <a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a>. <span class=\"citation\">B. Bath. 5ᵃ</span> <span dir=\"rtl\">רמא ביה ק׳</span> raised his voice against him (rebuked him). <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top [read:] <span dir=\"rtl\">ואזל ק׳ דקרעין לגופפתה</span> and the sound of (the lamentations at) the rending of garments went as far as Gof’fatha; <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> <span dir=\"rtl\">ואזיל קָלָה לקרעין וכ׳</span> (corr. acc.); a. fr.—<span dir=\"rtl\">בת ק׳</span>, <span dir=\"rtl\">ברת ק׳</span> = h. <span dir=\"rtl\">בת קול</span> (v. <a href=\"#\" data-headword=\"בַּת I\"><span dir=\"rtl\">בַּת</span> I</a>) <i>divine voice</i>. <span class=\"citation\">Targ. Y. Gen. XXXVIII, 26</span>; a. e.—<span class=\"citation\">Snh. 96ᵇ</span> <span dir=\"rtl\">נפקת בת ק׳</span> (not <span dir=\"rtl\">נפקא ק׳</span>) a divine voice came forth; a. fr.—Pl. <a href=\"#\" data-headword=\"קָלִי ²\">קָלַיָּא</a>, <span dir=\"rtl\">קָלִין</span>, <a href=\"#\" data-headword=\"קְלֵי\">קָלֵי</a>. <span class=\"citation\">Targ. Ex. IX, 23</span>. <span class=\"citation\">Ib. 29</span>; a. fr.—<span class=\"citation\">Targ. Ps. XCIII, 4</span> <a href=\"#\" data-headword=\"קָלָן\">קָלָן</a>.—<span class=\"citation\">B. Mets. 85ᵃ</span> <span dir=\"rtl\">מעבר ליה קָלֵיה לקָלַיְהוּ</span> the sound of his cry (in pain) drowned their (the beasts’) voices. <span class=\"citation\">R. Hash. 27ᵃ</span> <span dir=\"rtl\">תרי ק׳</span> two simultaneous (or immediately consecutive) sounds; a. e.</div>","alt":["קָל I","קָלָא"]},"28094":{"h":"קָל II","r":"S01232","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַל III\">preced.</a>) <i>Ḳal</i> (<i>Voice</i>), name of the genius of Nebuchadnezzar. <span class=\"citation\">Ex. R. s. 21</span> (ref. to <span class=\"citation\">Dan. IV, 28</span>).</div>","alt":[]},"28095":{"h":"קָלָא","r":"S01233","html":"<div class=\"sense\"><i>voice</i>, v. <a href=\"#\" data-headword=\"קַל III\"><span dir=\"rtl\">קל</span> III</a>.—[<span class=\"citation\">Yalk. Ps. 662</span> <span dir=\"rtl\">קלא באטין</span>, read: <a href=\"#\" data-headword=\"*אַקּוּבִּיטוֹן\">אַקּוּבִיטוֹן</a>.]</div>","alt":[]},"28096":{"h":"קֹלָא","r":"S01234","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוֹלָא I\"><span dir=\"rtl\">קוֹלָא</span> I</a></div>","alt":[]},"28097":{"h":"קְלָא I","r":"S01235","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"קוֹלָא I\"><span dir=\"rtl\">קוֹלָא</span> I</a>, II) [<i>something round</i>,] <i>clod, stone</i>. <span class=\"citation\">Ab. Zar. 18ᵇ</span> <span dir=\"rtl\">שקל ק׳ וכ׳</span> he took up a clod and threw it at them; <span class=\"citation\">Pes. 62ᵇ</span>, a. e. <span class=\"citation\">B. Kam. 92ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּיר\">כֵּיר</a>. <span class=\"citation\">Taan. 4ᵃ</span>, v. <a href=\"#\" data-headword=\"פַּרְצִידָא\">פַּרְצִידָא</a>; a. e.</div>","alt":[]},"28098":{"h":"קְלָא II","r":"S01236","html":"<div class=\"sense\"><i>to burn</i>, v. <a href=\"#\" data-headword=\"קְלֵי\">קְלֵי</a>.</div>","alt":[]},"28099":{"h":"קְלָא III","r":"S01237","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלָאִילָּן\">קְלָאִילָּן</a></div>","alt":["קְ׳ אִילָּן"]},"28100":{"h":"קלא","r":"S01238","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלָאפַנְדָּר\">קְלָאפַנְדָּר</a></div>","alt":["ק׳ פנדר"]},"28101":{"h":"קלאונא","r":"S01239","html":"<div class=\"sense\">, <span class=\"citation\">Deut. R. s. 10</span>, v. <a href=\"#\" data-headword=\"קָלָנְיָא\">קְלָנְיָא</a></div>","alt":[]},"28102":{"h":"קְלָאִילָּן","r":"S01240","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְלָא II a. <a href=\"#\" data-headword=\"אִילָּן\">אִילָּן</a>) [<i>ashes of a tree</i>,] <i>a vegetable blue dye</i>, an imitation of the genuine purple-blue <a href=\"#\" data-headword=\"תְּכֵלֶת\">(תְּכֵלֶת</a>); [Ar.: <i>indigo</i>, an adaptation of καλλάΐνον, callainum, Sachs, Beitr. I, p. 132]; <i>woolen threads dyed with ḳ’la-illan</i>. <span class=\"citation\">Tosef. Ab. Zar. VI</span> (<span class=\"citation\">VII), 1</span> ק׳ שדשו בעצי וכ׳ <i>ḳ’la-illan</i> wool which has been stamped with wood of an <i>ăsherah</i> (<a href=\"#\" data-headword=\"אֲשֵׁרָה\">אֲשֵׁרָה</a>) must be burnt; others say, it is under the restriction of the law until it resumes its natural color (by washing &amp;c.). <span class=\"citation\">Meïl. 13ᵃ</span> הדש קלעילון בשדה וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"קְלָעִילּוֹן\">קלעילין</a>) he that stamps <i>ḳ’laillan</i> wool in a field belonging to the Temple. <span class=\"citation\">B. Kam. 93ᵇ</span> <span dir=\"rtl\">בק׳ א׳ דלא עבר</span> a <i>ḳ</i>. dye which cannot be removed with soap (v. <a href=\"#\" data-headword=\"צָפוֹן I\"><span dir=\"rtl\">צָפוֹן</span> I</a>). <span class=\"citation\">B. Mets. 61ᵇ</span> <span dir=\"rtl\">מי שתולה ק׳ א׳ בבגדו וכ׳</span> he that attaches <i>ḳ</i>. threads to his garment and says, it is <i>t’kheleth</i>. <span class=\"citation\">Men. 41ᵇ</span> <span dir=\"rtl\">טלית שכולה … מן ק׳ א׳</span> if a cloak is entirely of purple wool, any threads of a different color may be used as show-fringes, except <i>ḳ</i>. (because it may be mistaken for <i>t’kheleth</i>). <span class=\"citation\">Tosef. Kil. V, 26</span> <span dir=\"rtl\">ק׳ א׳ וכ׳</span> (Var. <span dir=\"rtl\">קלע אילן</span>) threads of <i>ḳ.</i> (used in place of <i>t’kheleth</i>) … are not subject to the laws of mixed materials <a href=\"#\" data-headword=\"כִּלְאַיִם\">(כִּלְאַיִם</a>).</div>","alt":["קְלָא אִילָּן"]},"28103":{"h":"קְלָאִים","r":"S01241","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָלִי\">קָלִי</a></div>","alt":["קְלָאִין"]},"28104":{"h":"קלאמין","r":"S01242","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלָמוּס\">כְּלָמוּס</a></div>","alt":[]},"28105":{"h":"קְלָאפַנְדָּר","r":"S01243","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (a comp. of κλεπ- and ανδρ-) <i>ḳ’lafandar</i> (Man-Stealer), fictitious name of one of the judges of Sodom. <span class=\"citation\">Gen. R. s. 50</span> Ar. (ed. <span dir=\"rtl\">קלא פ׳</span>, combine); Yalk. ib. 84 <a href=\"#\" data-headword=\"קְלָאפַנְדָּר\">קלפ׳</a>.</div>","alt":["קְלָפַ׳"]},"28106":{"h":"קִלָּארִון","r":"S01244","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִילָּרִין\">קִילָּרִין</a></div>","alt":[]},"28107":{"h":"*קַלְבָּא","r":"S01245","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קלב <i>to stick</i>) <i>resin</i>. <span class=\"citation\">Sabb. 133ᵇ</span> <span dir=\"rtl\">קירא וק׳</span> (strike out <a href=\"#\" data-headword=\"רישינא\">רישינא</a>, a commentator’s gloss; v. Rabb. D. S. a. l. note; Var. in Mss. <a href=\"#\" data-headword=\"תַּבְלָא\">תבלא</a>, <span dir=\"rtl\">קבלא</span>, <span dir=\"rtl\">קילבא</span>, <span dir=\"rtl\">קלאבא</span>, v. Rabb. l. c.) wax and resin (Var. <span dir=\"rtl\">קירא דק׳</span> wax of resin); <span class=\"citation\">B. Kam. 85ᵃ</span>. [Ar.: <i>butter</i>].</div>","alt":[]},"28108":{"h":"קָלְבּוֹן","r":"S01246","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוֹלְבּוֹן\">קוֹלְבּוֹן</a></div>","alt":[]},"28109":{"h":"קלבוס","r":"S01247","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 120ᵃ</span>, v. <a href=\"#\" data-headword=\"קוֹלְבִין\">קוֹלְבִין</a></div>","alt":[]},"28110":{"h":"*קְלִיבִּינִטִירִין","r":"S01248","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a corrupt. of κλινο-βατήριον = βάθριον, corresp. to Lat. scamnum) <i>step placed before the bed</i>. <span class=\"citation\">Y. Ber. III, 5ᵈ</span> bot. <span dir=\"rtl\">שומט קלבינטרין וכ׳</span> (ed. Lehm. <a href=\"#\" data-headword=\"קַרְבִיטִין\">קרביטין</a>, corr. acc.; Mus. in Ar. ed. Koh. <span dir=\"rtl\">קלבינטירין</span>, oth. ed. <span dir=\"rtl\">קלבינטר׳</span>; Ar. <span dir=\"rtl\">קליבנטירין</span>) he detaches the footstool from the state-bed <a href=\"#\" data-headword=\"דַּרְגֵּשׁ\">(דרגש</a>), and that is enough (as a sign of mourning); <span class=\"citation\">Y. Ned. VII, end, 40ᶜ</span> <a href=\"#\" data-headword=\"קלונטרון\">קלונטרון</a> ed. Krot. (Mus. l. c. <a href=\"#\" data-headword=\"קלינטרין\">קלינטרין</a>, corr. acc.); <span class=\"citation\">Y. M. Kat. III, 83ᵃ</span> top <span dir=\"rtl\">קלמנטרין</span> (corr. acc.).</div>","alt":["קְלִיבִּינְטְרִין"]},"28111":{"h":"קלבסים","r":"S01249","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִוְוסִין\">קְלִוְוסִין</a></div>","alt":[]},"28112":{"h":"קְלַבְרִיאָה","r":"S01250","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Calabria</i>, the peninsula in the south-east of Italy. <span class=\"citation\">Y. Shek. VI, 50ᵃ</span>; <span class=\"citation\">Gen. R. s. 23</span>, end <span dir=\"rtl\">בראשונה עלה עד ק׳ וכ׳</span> the first time the flood rose as far as Calabria, the second time as far as the rocks &amp;c., v. <a href=\"#\" data-headword=\"בַּרְבַּרְיָא\">בַּרְבַּרְיָא</a>.</div>","alt":[]},"28113":{"h":"קַלְגָּס","r":"S01251","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (caliga, accus. pl.) <i>soldier’s nail-studded shoe</i>.—Pl. <span dir=\"rtl\">קַלְגָּסִים</span>, <span dir=\"rtl\">קַלְגָּסִין</span>. <span class=\"citation\">Sot. VIII, 1</span> <span dir=\"rtl\">שפעת הק׳</span> the noise of the trampling shoes; <span class=\"citation\">Sifré Deut. 192</span> <a href=\"#\" data-headword=\"עקלגסים\">עקלגסים</a> (corr. acc.; Var. <span dir=\"rtl\">גַּלְגָּסִין</span>, v. <a href=\"#\" data-headword=\"*גַּלִּיגָאס\">גַּלִּיגָאס</a>).</div>","alt":[]},"28114":{"h":"קלגריפון","r":"S01252","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַלִּיגְרָפוֹן\">קלִּיגְרָפוֹן</a></div>","alt":[]},"28115":{"h":"קְלַד","r":"S01253","html":"<div class=\"sense\">, <i>Af</i>. <span dir=\"rtl\">אַקְלֵיד</span> (denom. of <a href=\"#\" data-headword=\"אַקְלִידָא\">אַקֶלִידָא</a>) <i>to lock up, insert the key</i></div><div class=\"sense\"><b>Ithpe. אִיקְּלִיד</b> <div class=\"sense\"><i>to be inserted like a key; to be swallowed up, disappear</i>. <span class=\"citation\">Ḥull. 93ᵇ</span> <span dir=\"rtl\">אִיקְּלוּדֵי מִיקְּלִיד</span> (or <span dir=\"rtl\">אַקְלוּדֵי</span>; Ms. R. <span dir=\"rtl\">אַקְלִידֵי</span>; Ms. R. 2 <span dir=\"rtl\">קַלּוּדֵי מִקְּלַד</span>, or <span dir=\"rtl\">מְקַלַּד</span>; v. Rabb. D. S. a. l. note 4) the sinew disappears in the flesh.</div></div>","alt":[]},"28116":{"h":"קלדה","r":"S01254","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַלְרָהִי\">קַלְרָהִי</a></div>","alt":["קלדהי","קלדוהי"]},"28117":{"h":"קַלָּה I","r":"S01255","html":"<div class=\"sense\">, fem. of <a href=\"#\" data-headword=\"קַל I\">קַל</a>.</div>","alt":[]},"28118":{"h":"קַלָּה II","r":"S01256","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḳallah</i>, name of a servant of R. Judah the Nasi. Y. Bets. I, 60ᵈ <span dir=\"rtl\">ק׳ דרומא</span>.</div>","alt":[]},"28119":{"h":"קָלָה I","r":"S01257","html":"<div class=\"sense\"><i>voice</i>, v. <a href=\"#\" data-headword=\"קָלָא\">קָלָא</a>.</div>","alt":[]},"28120":{"h":"קָלָה II","r":"S01258","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קלי\">קלי</a></div>","alt":[]},"28121":{"h":"קְלוּבְקרִין","r":"S01259","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּפְקְרֵי\">גְּלוּפְקְרִין</a></div>","alt":[]},"28122":{"h":"קַלּוּדַיָּא","r":"S01260","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (calida) <i>hot drink of wine and water</i>, kept in a large bowl (v. Sm. Ant. s. v.); [the spelling <span dir=\"rtl\">קלור׳</span> induced by Latin <i>calor</i>]. <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">קלוד׳</span> ed. Wil. (oth. eds. <span dir=\"rtl\">קלור׳</span>); <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">קלור׳</span>; Yalk. Am. 545 <span dir=\"rtl\">קלור׳</span>.</div>","alt":["(קלוריא)"]},"28123":{"h":"קִלְוָואן","r":"S01261","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κελεύων) <i>commanding</i>. <span class=\"citation\">Gen. R. s. 63</span> אנא ק׳ אנא וכ׳ I do order that &amp;c.—[<span class=\"citation\">Ib.</span> <span dir=\"rtl\">יהיב קילוון</span>, v. next art.]—Pl. <span dir=\"rtl\">קִלְוָואנִין</span>, <a href=\"#\" data-headword=\"קִלְוָון\">קִלְוָונִ׳</a>, <a href=\"#\" data-headword=\"קוֹלְבָן\">קִילְ׳</a>. <span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">ק׳ אנא וכ׳</span> (not <span dir=\"rtl\">קלווניא</span>) we do order that &amp;c.; <span class=\"citation\">Koh. R. to II, 20</span>.—[<span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">קלוונין דידי</span>, v. next art.]</div>","alt":["קִלְוָון","קִילְ׳"]},"28124":{"h":"קלוויא","r":"S01262","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּלְיָא II\"><span dir=\"rtl\">קוּלְיָא</span> I</a></div>","alt":[]},"28125":{"h":"קִלְוָון","r":"S01263","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִלְוָואן\">קִלְוָואן</a></div>","alt":[]},"28126":{"h":"קלווסים","r":"S01264","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִוְוסִין\">next w.</a></div>","alt":[]},"28127":{"h":"קְלִוְוסִין","r":"S01265","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (κέλευσις) <i>command</i>. <span class=\"citation\">Y. Ned. IX, end, 41ᶜ</span> <span dir=\"rtl\">נפקת ק׳ וכ׳</span> (not <span dir=\"rtl\">סים …</span>) an order was issued by the king &amp;c. <span class=\"citation\">Pesik. R. s. 10</span> <span dir=\"rtl\">כבר הוצאתי קלווני׳ עליו וכ׳</span> (corr. acc.) I have once issued a decree concerning him that they should ‘lift up’ his head &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יכולה קילוילוסיו שלך קיימת וכ׳</span> (read: <a href=\"#\" data-headword=\"קילווני׳\">קילווסין</a>) thy decree may stand, and yet thy son may remain in his place (rank) uninjured. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ונמצא ק׳ שלך קיימת וכ׳</span> (not <span dir=\"rtl\">סים …</span>) and thus thy decree will be upheld, and high rank will be thy son’s. <span class=\"citation\">Gen. R. s. 5</span> נלך ונעשה ק׳ של הקב&quot;ה Ar. (ed. <span dir=\"rtl\">קילוסין להקב&quot;ה</span>, corr. acc.) let us go and carry out the Lord’s command. <span class=\"citation\">Lam. R. to V, 5</span> אדריינוס … אפיק ק׳ Ar. (v. Matt. K. a. l.; differ. in ed.) Hadrian … issued a decree. Ib. to I, 5 <span dir=\"rtl\">בגין דעברת על קלוונין דידי</span> (corr. acc.) whereas thou hast disobeyed my order. <span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">אנא יהיב קילוון וכ׳</span> (corr. acc.) I give out an order &amp;c. <span class=\"citation\">Lev. R. s. 7</span> <span dir=\"rtl\">נימוס וקלוסים הוא וכ׳</span> (corr. acc.; some ed. <span dir=\"rtl\">נ׳ ק׳</span> corr. acc.; Ar. <span dir=\"rtl\">נ׳ הוא וקילוסין הוא</span>) it is a custom and a decree that he &amp;c.—[Lam. R. introd. (R. Abbahu 2) <a href=\"#\" data-headword=\"קלבסים\">קלבסים</a> Ar. (ed. <span dir=\"rtl\">קלסים</span>); <span class=\"citation\">Yalk. Ez. 363</span> <span dir=\"rtl\">קלווסי׳</span>, v. <a href=\"#\" data-headword=\"*קְלִירוֹס\">קְלִירוֹס</a>.]</div>","alt":["קְלִוְוסִיס","קִילִ׳"]},"28128":{"h":"קִלּוּחַ","r":"S01266","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קוֹלְבָן\">קִילּ׳</a>.</div>","alt":["קִלּוּחָא"]},"28129":{"h":"קלולי","r":"S01267","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Par. III</span> (<span class=\"citation\">II), 4</span> Var., v. <a href=\"#\" data-headword=\"קָלָל\">קָלָל</a></div>","alt":[]},"28130":{"h":"קלומית","r":"S01268","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרוֹמִית\">קְרוֹמִית</a></div>","alt":[]},"28131":{"h":"קָלוֹן I","r":"S01269","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>degradation, disgrace</i>, opp. <a href=\"#\" data-headword=\"כָּבוֹד\">כָּבוֹד</a>. <span class=\"citation\">Gen. R. s. 1</span>, a. e. <span dir=\"rtl\">בקְלוֹן חבירו</span>, v. <a href=\"#\" data-headword=\"כָּבֵד I\"><span dir=\"rtl\">כָּבֵד</span> I</a>. <span class=\"citation\">Ab. d’R. N. ch. XXIX</span> <span dir=\"rtl\">המכבד … שנפטר ממנו בק׳</span> he that honors his fellow-man for the sake of wealth, will finally part with him in disgrace. <span class=\"citation\">Snh. 55ᵃ</span> (of an animal that has been carnally abused) <span dir=\"rtl\">תקלה וק׳ בעינן</span> (to condemn it to death) is it necessary that it must have been both a stumbling-block (cause of a scandal) and a disgrace (to the criminal and his survivors)? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">זה קָלוֹנוֹ … קלונו מועט</span> in this case (of a Jew being the criminal) his disgrace is great, and in the other (that of a gentile) his disgrace is little (it being not unusual). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">והרי אילנות דאין קָלוֹנָן וכ׳</span> but in the case of trees (that have been worshipped and must be destroyed) the disgrace through them is not great, and yet &amp;c. Esth. R. introd. to Par. 3, v. <a href=\"#\" data-headword=\"קוּא\">קוּא</a>; a. fr.—Esp. <i>prostitution, house of prostitution; sodomy</i>. <span class=\"citation\">Lam. R. to I, 16</span> אספסיאנוס … להושיבן בק׳ של רומי Vespasian filled three ships with the nobles of Jerusalem to place them in the Roman houses of prostitution. <span class=\"citation\">Ib. to IV, 2</span> <span dir=\"rtl\">תינוק אחד … בק׳</span> a Jewish boy is in prison doomed to prostitution; Y. Hor. III, 48ᵇ. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שניהם עומדין בק׳ וכ׳</span> if a man and a woman are (in prison) threatened with exposure to prostitution, the redemption of the man has the precedence &amp;c.; a. fr.—Trnsf. <i>idolatrous statue</i> or <i>temple</i>. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top (in Chald. dict.) <span dir=\"rtl\">כד דמך … נפל ק׳ דטיבריא</span> when R. H. died, the idol (or temple) of Tiberias fell in (cmp. <a href=\"#\" data-headword=\"טִימִי I\"><span dir=\"rtl\">טִימִי</span> I</a>).</div>","alt":[]},"28132":{"h":"קָלוֹן II","r":"S01270","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קָלָה II) <i>combustion</i>. <span class=\"citation\">Num. R. s. 11</span> (play on <span dir=\"rtl\">קלין</span>, <span class=\"citation\">Prov. III, 35</span>). <span dir=\"rtl\">ירימו בחלקם ק׳ … לאש</span> they shall carry off combustion as their share, because finally they will go into fire; <span dir=\"rtl\">ואין ק׳ אלא שריפה וכ׳</span> <i>ḳalon</i> means burning (ref. to <span class=\"citation\">Jer. XXIX, 22</span>).—[<span class=\"citation\">B. Bath. 99ᵇ</span> <span dir=\"rtl\">בית הק׳</span>, v. <a href=\"#\" data-headword=\"קִילוֹן\">קִילוֹן</a>.]</div>","alt":[]},"28133":{"h":"קַלּוֹן","r":"S01271","html":"<div class=\"sense\"> (calo) <i>I proclaim</i>. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> top, v. <a href=\"#\" data-headword=\"*דיאו\">דיאו</a>.</div>","alt":[]},"28134":{"h":"קלונטרון","r":"S01272","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*קְלִיבִּינִטִירִין\">קְלִיבִּינְטִירִין</a></div>","alt":[]},"28135":{"h":"קָלוֹנְיָא","r":"S01273","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָלָנְיָא\">קָלָנְיָא</a></div>","alt":[]},"28136":{"h":"קלונינפי","r":"S01274","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִינְפֵי\">נִינְפֵי</a></div>","alt":["קלוניפו"]},"28137":{"h":"קָלוֹנִית","r":"S01275","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (קָלוֹן I) <i>brothel-keeper</i>. Y’lamd. to Gen. XLIII, 14 <span dir=\"rtl\">אמרו זה לזה נלך אצל הק׳ וכ׳</span> (not <span dir=\"rtl\">חקול׳</span>, <span dir=\"rtl\">הקיל׳</span>) they (Joseph’s brothers) said to one another, let us go to the brothel-keeper’s, perhaps he has been sold thither.</div>","alt":[]},"28138":{"h":"קלוניתא","r":"S01276","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִנְתְּיָא\">קְלִנְתְּיָא</a></div>","alt":[]},"28139":{"h":"קִלּוּס","r":"S01277","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קוֹלְבָן\">קִילּ׳</a>.</div>","alt":["קִלּוּסָא"]},"28140":{"h":"קלוסטור","r":"S01278","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלַסְטֵיר ²\"><span dir=\"rtl\">קְלַסְטֵיר</span> I</a></div>","alt":["קלוסטר"]},"28141":{"h":"קְלוֹסְטְרָא","r":"S01279","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוֹסְטְרָא\">גְּלוֹסְטְרָא</a></div>","alt":[]},"28142":{"h":"קְלוֹסְטְרִין","r":"S01280","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*קְלוּסַנְטְרִין\">קְלוּסַנְטְרִין</a></div>","alt":[]},"28143":{"h":"קלוסים","r":"S01281","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 7</span>, v. <a href=\"#\" data-headword=\"קְלִוְוסִין\">קְלִוְוסִיס</a>.</div>","alt":["קלוסין"]},"28144":{"h":"קלוסיתה","r":"S01282","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּלְסִיתָא\">קוּלְסִיתָא</a></div>","alt":[]},"28145":{"h":"*קְלוּסַנְטְרִין","r":"S01283","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (a corrupt. of γελοιαστήρ = γελοιαστής) <i>jesters, buffoons, king’s fools</i> (v. <a href=\"#\" data-headword=\"קְלַסְתָּא\">קְלַסְתָּא</a>). <span class=\"citation\">Targ. Esth. II, 21</span> <span dir=\"rtl\">תרין ק׳</span> two merry-makers, opp. <a href=\"#\" data-headword=\"*בַּכְיָין\">בַּכְיָן</a>; <span class=\"citation\">Yalk. Esth. 1053</span> (in Hebr. dict.) <span dir=\"rtl\">קלוסנט׳</span> (some ed. <a href=\"#\" data-headword=\"קְלוֹסְטְרִין\">קְלוֹסְטְרִין</a>, <span dir=\"rtl\">קְלִיסְטְ׳</span>), opp. <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבָּרִי</a> (v., however, <a href=\"#\" data-headword=\"*קְלַסְרִיקִין\">קְלַסְרִיקִין</a>).</div>","alt":["קְלוּסַנְתְּרִ׳"]},"28146":{"h":"קְלוּסְקָא","r":"S01284","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּסְקָא\">גְּלוּסְקָא</a></div>","alt":[]},"28147":{"h":"קְלוּסְקוֹם","r":"S01285","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"גלוסקוים\">גְּלוּסְקוֹם</a>. Ohol. IX, 15 Ar. (ed. <a href=\"#\" data-headword=\"ג׳\">ג׳</a>, not <span dir=\"rtl\">גלוסקוס</span>).</div>","alt":[]},"28148":{"h":"קְלוּסְקִין","r":"S01286","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גְּלוּסְקָא\">גְּלוּסְקָא</a></div>","alt":[]},"28149":{"h":"קלוע","r":"S01287","html":"<div class=\"sense\">, <span class=\"citation\">Targ. I Kings XIV, 3</span> some ed., read: <a href=\"#\" data-headword=\"זְלוּעַ\">זְלוּעַ</a>.</div>","alt":[]},"28150":{"h":"קִלּוּפָא","r":"S01288","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"קוֹלְבָן\">קִילּ׳</a>.</div>","alt":["קִלּוּפָה"]},"28151":{"h":"קְלוֹפָא","r":"S01289","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">קְלוֹפִין</span> (<a href=\"#\" data-headword=\"קְלַף\">קְלַף</a>) <i>peel, husks</i>. <span class=\"citation\">Targ. Y. Num. VI, 4</span> [read:] <a href=\"#\" data-headword=\"מוּקְדּוֹנְיָא\">מִקְּ׳</a>, v. <a href=\"#\" data-headword=\"מקלופין\">מקלופין</a>.</div>","alt":[]},"28152":{"h":"קְלוּפַטְרָא","r":"S01290","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִיאוֹפַטְרָא\">קְלִיאוֹפַטְרָא</a></div>","alt":[]},"28153":{"h":"קְלוּפִיתָא","r":"S01291","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְלַף\">קְלַף</a>) <i>peel, husk; thin skin</i> (<i>gut for sausages</i>).—Pl. <span dir=\"rtl\">קְלוּפְיָיתָא</span>, <span dir=\"rtl\">קְלוּפְיָיתָה</span>. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> bot. <span dir=\"rtl\">כד מבחר בק׳</span> when he makes a selection from among the guts; <span class=\"citation\">ib.</span> <span dir=\"rtl\">בקלופיתיה</span> (corr. acc.). [Levy, Neuhebr. Wört. quotes <span dir=\"rtl\">קְלִיפַיָּיא</span>.]</div>","alt":[]},"28154":{"h":"קְלוּפְסִין","r":"S01292","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוּפְסִין\">כְּלוּפְסִין</a></div>","alt":[]},"28155":{"h":"קלוקלון","r":"S01293","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִילְקִלִּין\">קִילְקִלִּין</a></div>","alt":[]},"28156":{"h":"קְלוּקַסְיָה","r":"S01294","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוֹלְקַסְיָיא\">קוֹלְקַסְיָיא</a></div>","alt":["קְלוּקַסְיָיה"]},"28157":{"h":"*קְלַוְקְרוֹן","r":"S01295","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cervical, κερβικάριον, S.) <i>pillow</i>. Mekh. B’shall., Amalek, s. 1 <span dir=\"rtl\">וכי לא … כר … כסת … או ק׳ אחד וכ׳</span> had Moses no bolster, or cushion, or pillow to be placed under him?; (<span class=\"citation\">Taan. 11ᵃ</span> only <a href=\"#\" data-headword=\"כַּר\">כר</a> a. <a href=\"#\" data-headword=\"כֶּסֶת\">כסת</a>).</div>","alt":[]},"28158":{"h":"קלורוס","r":"S01296","html":"<div class=\"sense\">, <span class=\"citation\">Yoma 84ᵃ</span>, v. <a href=\"#\" data-headword=\"קלירוס\">קלירוס</a></div>","alt":[]},"28159":{"h":"קלוריא","r":"S01297","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַלּוּדַיָּא\">קַלּוּדַיָּא</a></div>","alt":[]},"28160":{"h":"קִלּוּרִין","r":"S01298","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִילּוּר\">קִילּוּר</a>, a. <a href=\"#\" data-headword=\"קִילָּרִין\">קִילָּרִין</a>.</div>","alt":[]},"28161":{"h":"קִלּוּרִית","r":"S01299","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">קילּ׳</span>.</div>","alt":["קִלּוּרִיתָא","קִלּוּרִיתָה"]},"28162":{"h":"קַלּוּת","r":"S01300","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (קַל II) <i>lightness, swiftness</i>. Tanḥ. Vayḥi 16; <span class=\"citation\">Yalk. Gen. 161</span> <span dir=\"rtl\">קַלּוּתוֹ של איל</span> the swiftness of the hart; a. e.—<span dir=\"rtl\">ק׳ ראש</span> (or sub. <span dir=\"rtl\">ראש</span>) <i>light-mindedness, irreverence, disregard of custom</i>. <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">ונהג ק׳ בעצמו וכ׳</span> and set the example of disregard of custom through himself (inaugurated simplicity at burial), when (according to his request) they buried him in linen garments; <span class=\"citation\">M. Kat. 27ᵇ</span> <span dir=\"rtl\">ק׳ ראש</span>; <span class=\"citation\">Tosef. Nidd. IX, 17</span> <span dir=\"rtl\">הנהיג … ק׳ ר׳ וכ׳</span>. <span class=\"citation\">Succ. 51ᵇ</span> <span dir=\"rtl\">והיו באים לידי ק׳ ר׳</span> and they were led into irreverence (through the presence of women); <span class=\"citation\">Tosef. ib. IV, 1</span>. <span class=\"citation\">Ab. III, 13</span> <span dir=\"rtl\">שחוק וק׳ ר׳ מרגילין וכ׳</span> laughter and frivolity make man familiar with unchastity. Tanḥ. Miḳḳ. 9 <span dir=\"rtl\">שלא ינהוג ק׳ ר׳ בגבורה</span> lest man become irreverent towards the Almighty.</div>","alt":[]},"28163":{"h":"קלותא","r":"S01301","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. I, 3ᵈ</span> top, v. <a href=\"#\" data-headword=\"קוּלְתָא\">קוּלְתָא</a></div>","alt":[]},"28164":{"h":"קָלַח","r":"S01302","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"קֶלַח\">קֶלַח</a>) <i>to rise in a column</i>. <span class=\"citation\">B. Kam. 61ᵃ</span> <span dir=\"rtl\">בקוֹלַחַת</span>, v. <a href=\"#\" data-headword=\"קָדַח\">קָדַח</a>.</div><div class=\"sense\"><b>Pi. קִילֵּחַ</b> <div class=\"sense\"><b>1)</b> <i>to bring forth an uninterrupted jet, cause an uninterrupted flow; to splash</i>. <span class=\"citation\">Ab. Zar. 12ᵃ</span> <span dir=\"rtl\">פרצופות המְקַלְּחִין</span>, v. <a href=\"#\" data-headword=\"פַּרְצוֹף\">פַּרְצוֹף</a>. Tosef. Erub. IX (VI), 23 <span dir=\"rtl\">המְקַלֵּחַ</span>, v. <a href=\"#\" data-headword=\"צִנּוֹר\">צִנּוֹר</a>. <span class=\"citation\">Ker. 22ᵃ</span> <span dir=\"rtl\">כל זמן שמקלח</span> as long as the blood gushes forth, v. <a href=\"#\" data-headword=\"תַּמְצִית\">תַּמְצִית</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cause gushing forth by interposing an object, to dam in and cause an overflow</i>. <span class=\"citation\">Eduy. VII, 4</span>; <span class=\"citation\">Zeb. 25ᵇ</span> <span dir=\"rtl\">זוחלין שקִילְּחָן וכ׳</span> dripping liquids caused to overflow in a continuous current by a dam of burs of nuts.</div><div class=\"sense\"><b>—3)</b>  (of locusts) <i>to come in dense columns</i>. <span class=\"citation\">Tosef. Sabb. XII</span> (<span class=\"citation\">XIII), 5</span>; Y. ib. XIV, beg. 14ᵇ; Bab. <span class=\"citation\">ib. 106ᵇ</span> <span dir=\"rtl\">אם היו מְקַלְּחוֹת ובאות</span> if they come on in dense columns.</div><div class=\"sense\"><b>—4)</b> <i>to collect</i> (coins in a tube). <span class=\"citation\">Tosef. Shek. III, 2</span>; <span class=\"citation\">4</span>, sq. <span dir=\"rtl\">כהנים מקלחין אזתן</span> (Var. <span dir=\"rtl\">מקבלין</span>) the priests collect these moneys (put them in a horn, v. <a href=\"#\" data-headword=\"שֹׁופָר\">שׁוֹפָר</a>).</div></div>","alt":[]},"28165":{"h":"קְלַח","r":"S01303","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"קָלַח\">קַלַּח</a> ch. same, <i>to cast with force</i>, (of trees) <i>to shed fruit prematurely</i>. <span class=\"citation\">Targ. Y. Lev. XXVI, 20</span>.</div>","alt":[]},"28166":{"h":"קֶלַח","r":"S01304","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"קִילָא II\"><span dir=\"rtl\">קִילָא</span> II</a>, a. <a href=\"#\" data-headword=\"קוּלִית\">קוּלִית</a>) </div><div class=\"sense\"><b>1)</b> <i>tube, stem, stalk</i>. <span class=\"citation\">Keth. 111ᵇ</span>, a. fr. <span dir=\"rtl\">ק׳ של כרוב</span> a cabbage stalk; <span class=\"citation\">Y. Peah VII, 20ᵇ</span> top <span dir=\"rtl\">ק׳ אחד של חרדל</span> a mustard stalk. <span class=\"citation\">Pes. 39ᵇ</span> <span dir=\"rtl\">אק׳</span> referring to the stalk (of the herbs mentioned); a. fr.—Pl. <span dir=\"rtl\">קְלָחִים</span>, constr. <a href=\"#\" data-headword=\"קִילְחָא\">קִלְחֵי</a>, <a href=\"#\" data-headword=\"קוֹלְבָן\">קִילְ׳</a>; <span dir=\"rtl\">קוֹלְחוֹת</span>, <a href=\"#\" data-headword=\"קִילְחָא\">קִילְחוֹת</a>. <span class=\"citation\">Y. Kil. III, 28ᵈ</span> bot. <span dir=\"rtl\">בעושה ק׳ יחידים</span> when planting single stalks, opp. <span dir=\"rtl\">רצף</span>. <span class=\"citation\">Par. XI, 9</span>. <span class=\"citation\">Peah III, 2</span>. <span class=\"citation\">Ib. 5</span> <span dir=\"rtl\">המוכר קלחי אילן וכ׳</span> if a man sells the stems of plants in his field (without selling the soil); a. e.—<span class=\"citation\">Men. X, 4</span> (<span class=\"citation\">66ᵃ</span>) <span dir=\"rtl\">בקנים ובקליחות וכ׳</span> (read: <span dir=\"rtl\">ובקיל׳</span>; Bab. ed. <span dir=\"rtl\">ובקולחות</span>; Mish. Cambr. <span dir=\"rtl\">ובקִלְחוֹת</span>, v. Rabb. D. S. a. l. note 4) they threshed it with reeds and stalks of plants (instead of using flails); <span class=\"citation\">Lev. R. s. 28</span>; <span class=\"citation\">Pesik. R. s. 18</span> <span dir=\"rtl\">ובקולח׳</span>; Pesik. Haʿomer, p. 69ᵃ <span dir=\"rtl\">ובקלקת</span> (corr. acc.); <span class=\"citation\">Yalk. Lev. 643</span> <span dir=\"rtl\">ובקו׳</span>. <span class=\"citation\">Erub. 16ᵃ</span> <span dir=\"rtl\">קו׳</span> (ed. Sonc. <a href=\"#\" data-headword=\"קִרְיָיא\">קי׳</a>); a. e.</div><div class=\"sense\"><b>—2)</b>  (of liquids) <i>column, jet</i>. <span class=\"citation\">Toh. II, 1</span> <span dir=\"rtl\">ספק שהק׳ וכ׳</span> if there is a doubt whether the jet touched her hand. <span class=\"citation\">Tosef. T’bul Yom II, 9</span>; a. e.</div>","alt":[]},"28167":{"h":"קִלְחָא","r":"S01305","html":"<div class=\"sense\">, <i>stalk, stem</i>. <span class=\"citation\">Ḥull. 119ᵃ</span> בקל׳ Ar. (ed. <span dir=\"rtl\">בקו׳</span>) the stem (of the plants) is meant.—Pl. <span dir=\"rtl\">קִלְחִין</span>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a>. <span class=\"citation\">Targ. Y. Num. XIX, 18</span>.</div>","alt":["קִי׳","קוּ׳"]},"28168":{"h":"קַלַּחַת","r":"S01306","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קִלְחָא\">preced.</a> wds.) <i>flesh-pot</i>. <span class=\"citation\">B. Bath. 74ᵃ</span> <span dir=\"rtl\">כבשר בק׳</span> as flesh is turned in the pot.</div>","alt":[]},"28169":{"h":"קָלַט","r":"S01307","html":"<div class=\"sense\"> (b. h.) [<i>to surround</i>,] </div><div class=\"sense\"><b>1)</b> <i>to close, press</i>.—Part. pass. <span dir=\"rtl\">קָלוּט</span>; f. <span dir=\"rtl\">קְלוּטָה</span>; pl. <span dir=\"rtl\">קְלוּטִים</span>; <span dir=\"rtl\">קְלוּטיֹת</span>. Sifra Emor, Par. 7, ch. VII (expl. <span dir=\"rtl\">קלוט</span>, <span class=\"citation\">Lev. XXII, 23</span>) <span dir=\"rtl\">פרסוֹת וכ׳</span> an animal whose hoofs resemble those of a horse &amp;c.; <span class=\"citation\">Bekh. VI, 7</span> (<span class=\"citation\">40ᵃ</span>) <span dir=\"rtl\">שרגליו ק׳ וכ׳</span>. <span class=\"citation\">Bekh. 6ᵃ</span> <span dir=\"rtl\">פרסותיה ק׳</span> its hoofs are closed, opp. <span dir=\"rtl\">סדוקות</span> cloven. <span class=\"citation\">Ib. VII, 6</span> <span dir=\"rtl\">אצבעותיו … או ק׳ וכ׳</span> if his fingers lie one above the other or are grown together up to the root <a href=\"#\" data-headword=\"פֶּרֶק\">(פֶּרֶק</a>). <span class=\"citation\">Y. Sot. IX, 23ᵈ</span>; a. e.—In gen. <span dir=\"rtl\">קָלוּט</span> <i>an animal with uncloven hoofs</i> (having the sign of uncleanness) <i>born of a clean animal, monster</i> or <i>hybrid</i>. <span class=\"citation\">Bekh. 7ᵃ</span> <span dir=\"rtl\">ק׳ בן פרה</span> a <i>ḳaluṭ</i> born of a cow; <span class=\"citation\">Ḥull. 68ᵇ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ במעי פרה</span> a <i>ḳaluṭ</i> found in a cow (after ritual slaughtering); <span class=\"citation\">ib. 69ᵃ</span>. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">זרעיך כק׳ וכפרדה וכ׳</span> thy seed be like a <i>ḳ</i>. and like a mule &amp;c. (Rashi: ‘like one whose semen is locked up’); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to clutch, intercept, receive; to conceive, retain, absorb</i>. <span class=\"citation\">Ḥull. 65ᵃ</span> <span dir=\"rtl\">כל עוף הקוֹלֵט מן האויר וכ׳</span> any bird that snatches in the air (for things thrown to it) is unclean. <span class=\"citation\">Gen. R. s. 41</span> <span dir=\"rtl\">אינה קוֹלֶטֶת</span>, v. <a href=\"#\" data-headword=\"פֶּרֶד II\"><span dir=\"rtl\">פֶּרֶד</span> II</a>. <span class=\"citation\">Ker. 5ᵃ</span> <span dir=\"rtl\">וק׳ את הריח</span> and the oil retained (absorbed) the scent. <span class=\"citation\">Gen. R. s. 5</span> <span dir=\"rtl\">קְלָטָן הים</span> the sea absorbed them (the waters of the rivers); <span class=\"citation\">Yalk. Ps. 848</span> <span dir=\"rtl\">קְלָטָם</span>. <span class=\"citation\">Ab. V, 15</span> <span dir=\"rtl\">שמוציאה את היין וקולטת וכ׳</span> which passes the wine and retains the lees; <span dir=\"rtl\">שמוציאה … וק׳ את הסולת</span> which passes the common flour and retains the fine flour (v. <a href=\"#\" data-headword=\"צוּף\">צוּף</a>). <span class=\"citation\">Snh. 108ᵇ</span> <span dir=\"rtl\">כל שהתיבה קוֹלַטְתּוֹ</span> whatever animal the ark received. <span class=\"citation\">Sabb. I, 6</span> <span dir=\"rtl\">כדי שיִקְלוֹט העין</span> when there is time enough before the Sabbath for the wool to assume the color of the dye. <span class=\"citation\">Lev. R. s. 14</span> <span dir=\"rtl\">אין האשה קולטת וכ׳</span> a woman conceives only shortly after menstruation. <span class=\"citation\">Shebi. II, 6</span> <span dir=\"rtl\">כל הרכבה שאינה קולטת וכ׳</span> a grafting which does not take root within three days, will never do so; a. v. fr.—<span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">ק׳ דרך וכ׳</span> he (Moses) adopted the manner of his ancestors (finding wives at the well); Tanḥ. Sh’moth 10 <span dir=\"rtl\">לקח</span>.—Esp. (v. <a href=\"#\" data-headword=\"מִקְלָט\">מִקְלָט</a>) <i>to protect, give the shelter of an asylum</i>. <span class=\"citation\">Macc. 12ᵃ</span> <span dir=\"rtl\">אינו קולט אלא גגו</span> only the top of the altar protects him that flees to it; <span dir=\"rtl\">אינו קולט … עולמים</span> only the altar of the permanent sanctuary (in Jerusalem) offers protection; <span dir=\"rtl\">אינו קולט אלא כהן וכ׳</span> protects only the priest while at service &amp;c. Ib. <span dir=\"rtl\">אינה קולטת אלא בצר</span> only Bezer is an asylum (but not Bozrah). Ib.ᵇ <span dir=\"rtl\">פלכו קוֹלְטוֹ</span> his (the Levite’s) district protects him. Ib. <span dir=\"rtl\">עיר שקְלָטַתּוּ כבר</span> a town which has received him once before. <span class=\"citation\">Sifré Num. 160</span> <span dir=\"rtl\">אין לי אלא שקוֹלְטוֹת בארץ</span> this would indicate only that they (these cities) offer asylum for manslaughter committed in Palestine. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא קָלְטָה אחת מהם עד וכ׳</span> none of those cities had the right of asylum until all of them had been designated; a. fr.—<span class=\"citation\">Macc. 10ᵃ</span> <span dir=\"rtl\">מנין … קוֹלְטִין</span> whence do you learn that the words of the Law offer protection (to its students)?; <span class=\"citation\">ib.</span> <span dir=\"rtl\">קולטין ממלאך וכ׳</span> they protect from the angel of death.</div><div class=\"sense\"><b>—3)</b>  (of sacred precincts) <i>to retain; to make export illegal</i>. Ib. 19ᵇ <span dir=\"rtl\">קְלָטוּהוּ מחיצות</span> the sacred precincts have retained it (and it cannot be redeemed and taken out of Jerusalem again); ib. 20ᵃ. Ib. <span dir=\"rtl\">מחיצה לִקְלוֹט דרבנן</span> that the precincts have retaining power is merely a rabbinical enactment; <span class=\"citation\">Snh. 113ᵃ</span>; <span class=\"citation\">B. Mets. 53ᵇ</span>.—Part. pass. as ab. <span class=\"citation\">Sabb. 4ᵃ</span>, a. fr. <span dir=\"rtl\">קלוטה כמי שהונחה דמיא</span>, v. <a href=\"#\" data-headword=\"נוּחַ\">נוּחַ</a>.</div>","alt":[]},"28170":{"h":"קְלַט","r":"S01308","html":"<div class=\"sense\"><b>1)</b> <i>to close</i>.—Part. pass. <a href=\"#\" data-headword=\"קָלִיט\">קָלִיט</a>, <i>pl</i>. <span dir=\"rtl\">קְלִיטִין</span>. <span class=\"citation\">Targ. Y. Lev. XXI, 20</span>.</div><div class=\"sense\"><b>—2)</b> <i>to clutch, intercept, receive; to absorb</i>. <span class=\"citation\">Ḥull. 65ᵃ</span> <span dir=\"rtl\">ציפרתי נמי מִקְלַט קָלְטָא</span> the <i>tsipparti</i>, too, snaps at things in the air (and yet it is a clean bird). Y. Pes. III, beg. 29ᵈ <a href=\"#\" data-headword=\"דִּיקְלוּט\">דיִקְלוֹט</a>, v. <a href=\"#\" data-headword=\"צִבְעָא ²\"><span dir=\"rtl\">צִבְעָא</span> I</a>; a. fr.—<span class=\"citation\">Meïl. 11ᵇ</span>, v. infra.</div><div class=\"sense\"><b>—3)</b> <i>to offer an asylum, protect</i>. <span class=\"citation\">Targ. Y. Num. XXXV, 6</span>; a. e.</div><div class=\"sense\"><b>—4)</b>  (of sacred precincts) <i>to retain</i>. <span class=\"citation\">Pes. 52ᵃ</span> <span dir=\"rtl\">אטו גבא דחמרא קַלְטִינְהוּ</span> (not <a href=\"#\" data-headword=\"אַגַּבָּא\">אגבא</a>) does the back of the ass (on which the fruit was brought to the place) form a sacred precinct (so that it cannot be exported again)?</div><div class=\"sense\"><b>Ithpe. אִיקְּלַט  אִיקְּלִיט</b> <div class=\"sense\"><i>to be received, intercepted</i>. <span class=\"citation\">Succ. 49ᵇ</span> <span dir=\"rtl\">בדא׳</span> when the remnant of the libation poured into the depth was intercepted in a vessel; <span class=\"citation\">Meïl. 11ᵇ</span> <span dir=\"rtl\">דאי קְלַט</span> (<span dir=\"rtl\">קתני</span>) it refers to a case when one intercepted the libation (v. Rashi a. Tosaf. for Var. Lect.).</div></div>","alt":[]},"28171":{"h":"קַלְטָא","r":"S01309","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְלַט\">preced.</a>) <i>reception, asylum</i>. <span class=\"citation\">Targ. Y. Num. XXXV, 25</span>, sq. <span dir=\"rtl\">קַלְטֵיה</span> (h. text <span dir=\"rtl\">מקלטו</span>).</div>","alt":[]},"28172":{"h":"קָלְטָא","r":"S01310","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַלְטָא\">preced.</a>) <i>receiving, protecting.</i> <i>—</i> Pl. <span dir=\"rtl\">קָלְטַן</span>. <span class=\"citation\">Targ. Y. Num. XXXV, 11</span>; <span class=\"citation\">13</span>, sq.</div>","alt":[]},"28173":{"h":"קִלְטָא","r":"S01311","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָלְטָא\">preced.</a> wds.; cmp. <a href=\"#\" data-headword=\"סָפַג\">סָפַג</a>, <a href=\"#\" data-headword=\"בְּלַע\">בְּלַע</a>) [<i>absorbing</i>,] <i>receiving punishment</i>. <span class=\"citation\">Y. Yeb. II, 4ᵃ</span> top <span dir=\"rtl\">חבוט … דהוא טבא בק׳</span> go on beating, for there is a benefit in taking it (it will teach me a lesson); <span class=\"citation\">Y. Kidd. III, 64ᵈ</span> bot. <span dir=\"rtl\">בקִלְטָה</span>; <span class=\"citation\">Gen. R. s. 7</span>; Tanḥ. Huḳḳ. 6; <span class=\"citation\">Koh. R. to VII, 23</span>; <span class=\"citation\">Pesik. R. s. 14</span> <span dir=\"rtl\">בקליטי</span>, read: <span dir=\"rtl\">בקִילְטִי</span>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">בקליטה</span> (corr. acc.); Pesik. Par., p. 35ᵇ, sq. <span dir=\"rtl\">בקילתא</span> (corr. acc.).</div>","alt":["קִי׳","קוּ׳"]},"28174":{"h":"קָלָטוֹר","r":"S01312","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (calator) <i>an officer arranging the royal receptions</i>. <span class=\"citation\">Lev. R. s. 28</span>; <span class=\"citation\">Koh. R. to IX, 11</span>, a. e., v. <a href=\"#\" data-headword=\"קוֹמֵיס\">קוֹמֵיס</a>.</div>","alt":[]},"28175":{"h":"קלטיקה","r":"S01313","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"לֶקְטִיקָא\">לֶקְטִיקָה</a> or <span dir=\"rtl\">קְלֶקְטִיקָה</span> m. (v. <a href=\"#\" data-headword=\"גְּלוּגְדְּקָא\">גְּלוּגְדְּקָא</a>) (<i>the teacher’s) litter</i> in college or synagogue. <span class=\"citation\">Y. Meg. III, 73ᵈ</span> bot.</div>","alt":["קלטירה"]},"28176":{"h":"קַלֵּי","r":"S01314","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (καλή) <i>handsome</i>. <span class=\"citation\">Ex. R. s. 52</span>, end, a. e., v. <a href=\"#\" data-headword=\"נִינְפֵי\">נִינְפֵי</a>.</div>","alt":[]},"28177":{"h":"קַלִּי","r":"S01315","html":"<div class=\"sense\"> adv. (apocop. of <a href=\"#\" data-headword=\"קַלִּיל I\">קליל</a>), <span dir=\"rtl\">ק׳ ק׳</span> <i>little by little, slowly</i>. <span class=\"citation\">Erub. 51ᵃ</span> <span dir=\"rtl\">כי מסגי ק׳ ק׳</span> when he walks step by step, opp. <span dir=\"rtl\">רהט</span>. <span class=\"citation\">Sabb. 153ᵇ</span> <span dir=\"rtl\">דוקא רץ אבל ק׳ ק׳ לא</span> only when one runs (is it permitted), but when one walks leisurely is it not?</div>","alt":[]},"28178":{"h":"קלי","r":"S01316","html":"<div class=\"sense\"> (b. h.) <i>to be light, disregarded</i>.</div><div class=\"sense\"><b>Pi. קִלָּה  קִילָּה</b> <div class=\"sense\"> (by ref. to <span dir=\"rtl\">ונקלה</span>, <span class=\"citation\">Deut. XXV, 3</span>) <i>to disgrace</i> (one’s self), <i>to have loose bowels; to collapse under the lashes</i>. <span class=\"citation\">Macc. 23ᵃ</span> <span dir=\"rtl\">ק׳ בין בראשונה וכ׳</span> if he collapses either at the first or at the second lash, he must be released. Tosef. ib. V (IV), 14 <span dir=\"rtl\">אם קי׳ באחד מהן</span> if he collapsed at one of them. Ib. <span dir=\"rtl\">ק׳ עד שלא לקה</span> if he collapsed (from fear) before receiving lashes. Ib. <span dir=\"rtl\">אמדוהו שאם ילקה וקי׳</span> (Var. <span dir=\"rtl\">יקלקל</span>) if the experts opine that he will collapse, when he is lashed; <span dir=\"rtl\">שאם יוצא מב&quot;ד קי׳</span> (Var. <span dir=\"rtl\">וקלקל</span>) that he will collapse on leaving the court; Macc. l. c. <span dir=\"rtl\">יְקַלֶּה</span> Ms. M. (or <span dir=\"rtl\">יִקָּלֶה</span>; ed. <span dir=\"rtl\">קלה</span>). Ib. <span dir=\"rtl\">והכהו … ולא שיקלה כבר וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">שלקה</span>, corr. acc.; Var. <span dir=\"rtl\">שנִקְלָה</span>) we read, ‘lest if he should exceed …, thy brother be disgraced’, but he must not be beaten at all, if he has collapsed in court ere this; <span class=\"citation\">Yalk. Deut. 937</span> <span dir=\"rtl\">שנקלה וכ׳</span>; a. e.</div></div><div class=\"sense\"><b>Nif. נִקְלָה</b> <div class=\"sense\"><i>to be disgraced</i>. Ib. <span dir=\"rtl\">כפתוהו … מ&quot;ט ונקלה והא נ׳</span> if he runs away from court after they have tied him, he is released; why? The text says, <i>v’niḳlah</i>, and he has been disgraced; Macc. l. c. Ms. M. (not in ed.), v. supra; a. e.</div></div>","alt":["קָלָה I"]},"28179":{"h":"קְלֵי","r":"S01317","html":"<div class=\"sense\">, <i>to be disgraced</i>. <span class=\"citation\">Targ. O. Deut. XXV, 3</span> ויִקְלֵי Ms. III (ed. Berl. <span dir=\"rtl\">ויִקַּל</span>, oth. ed. <span dir=\"rtl\">ויֵקַל</span>, fr. <a href=\"#\" data-headword=\"קְלַל\">קְלַל</a>).</div><div class=\"sense\"><b>Pa. . קַלֵּי</b> </div><div class=\"sense\"><b>Af. אַקְלֵי</b> <div class=\"sense\"><i>to hold in light esteem, revile</i>. <span class=\"citation\">Targ. O. Deut. XXVII, 16</span> <span dir=\"rtl\">דִּיקַלֵּי</span> ed. Berl. (oth. ed. <span dir=\"rtl\">דיַקְלֵי</span>; ed. Vien. <span dir=\"rtl\">דיִקְלֵי</span>, corr. acc.; Regia <span dir=\"rtl\">דיֵקַל</span> fr. <a href=\"#\" data-headword=\"קְלַל\">קְלל</a>; v. Berl. Targ. O. II, p. 57).</div></div>","alt":[]},"28180":{"h":"קלי ²","r":"S01318","html":"<div class=\"sense\"><i>to consume, burn; to roast, parch</i>. Sifra Vayikra, N’dab., ch. XIV, Par. 13 <span dir=\"rtl\">אפשר יִקְלֶנּוּ גרש</span> the text might have meant that one must parch it as grit; <span dir=\"rtl\">יקלנו אביב</span> one must parch it in the ear. <span class=\"citation\">Pes. 75ᵃ</span> <span dir=\"rtl\">ונִקְלֶהָ</span>, v. next w.—Part. pass. <span dir=\"rtl\">קָלוּי</span>. Sifra l. c., v. <a href=\"#\" data-headword=\"קָלִי\">קָלִי</a>. <span class=\"citation\">Men. 66ᵇ</span> <span dir=\"rtl\">אם אביב ק׳ אם גרש ק׳</span> whether parched in the ear or as grit; a. e.</div><div class=\"sense\"><b>*. הִתְקַלֶּה</b> <div class=\"sense\"><i>to consume one’s self in longing</i>. <span class=\"citation\">Cant. R. to III, 11</span> <span dir=\"rtl\">מִתְקַלְהָא</span>, v. <a href=\"#\" data-headword=\"קָהָא\">קָהָה</a>.</div></div>","alt":["קָלָה II"]},"28181":{"h":"קְלֵי ²","r":"S01319","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. XXIX, 22</span>. <span class=\"citation\">Targ. O. Num. XXI, 6</span> <span dir=\"rtl\">חיוין קָלָן</span> (h. text <span dir=\"rtl\">הנחשים השרפים</span>); a. fr.—[<span class=\"citation\">Targ. Hos. IX, 16</span> <a href=\"#\" data-headword=\"דִּקְלָא\">דקלא</a>, read as ed. Lag. <span dir=\"rtl\">דילְקָא</span>.]—Part. pass. <a href=\"#\" data-headword=\"קְלֵי\">קְלֵי</a>, <a href=\"#\" data-headword=\"קָלִי\">קָלִי</a>; <a href=\"#\" data-headword=\"קוּלְיָא II\">קַלְיָא</a>. <span class=\"citation\">Targ. Lev. II, 14</span>. <span class=\"citation\">Targ. I Sam. XXX, 3</span>; a. e.—<span class=\"citation\">Pes. 75ᵃ</span> נקיף … ונִיקַלְיָיהּ Ms. M. (ed. <span dir=\"rtl\">ונקלה</span>) (may we not understand the text so) that we put bundles of twigs around her and burn her to death? <span class=\"citation\">B. Mets. 74ᵃ</span> <span dir=\"rtl\">הא מחוסר מִקְלֵי ואפוקי וכ׳</span> (some ed. <a href=\"#\" data-headword=\"מִקְלָה\">מִקְלֵה</a>) but it (the lime) lacks burning and taking out of the kiln and crushing! <span class=\"citation\">Snh. 31ᵃ</span>, sq. <span dir=\"rtl\">אי בעיא קלְתֵיה</span> if she wanted, she might have burned it (the document). <span class=\"citation\">Ḥull. 52ᵇ</span> <span dir=\"rtl\">לא קָלֵי זיהריה</span>, v. <a href=\"#\" data-headword=\"זִיהֲרָא II\"><span dir=\"rtl\">זִיהֲרָא</span> II</a>. <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">קְלַנְהִי אמרא וכ׳</span> roast them on a new shovel. <span class=\"citation\">Snh. 96ᵇ</span> <span dir=\"rtl\">היכלא קליא קְלִית</span> a burnt temple thou didst burn (v. <a href=\"#\" data-headword=\"טְחַן\">טְחַן</a>); a. fr.—Trnsf. <i>to expose to the evil eye</i> or <i>to the covetousness of thieves</i>. <span class=\"citation\">B. Mets. 30ᵃ</span> <span dir=\"rtl\">דמִקְלָא קָלֵי לה וכ׳</span> (by exhibiting the found object) he exposes it to loss through the evil eye or through thieves.</div><div class=\"sense\"><b>Ithpe. אִיקְּלֵי</b> <div class=\"sense\"><i>to be burnt</i>. Snh. l. c. <span dir=\"rtl\">מטא … היכלא מִיקְּלֵי</span> the time has arrived for the sanctuary to be destroyed and the Temple to be burnt.</div></div>","alt":["קְלָא"]},"28182":{"h":"קָלִי","r":"S01320","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קְלֵי ²\">preced.</a>) <i>parched ears</i>. <span class=\"citation\">Men. X, 4</span> (<span class=\"citation\">66ᵃ</span>) <span dir=\"rtl\">כדי לקיים בו מצות ק׳</span> in order to comply with the law requiring it to be parched (<span class=\"citation\">Lev. II, 14</span>); Sifra Vayikra, N’dab., ch. XIV, Par. 13 <span dir=\"rtl\">קָלוּי</span> (v. <a href=\"#\" data-headword=\"קָלָה II\"><span dir=\"rtl\">קָלָה</span> II</a>). <span class=\"citation\">Men. 66ᵇ</span> אין לשון ק׳ אלא דבר אחר Ms. M. (v. Rabb. D. S. a. l. note, a. <span class=\"citation\">Yalk. Lev. 456</span>) by <i>ḳoli</i> (parched) we understand the intercession of something else between the fire and the object to be affected by it; <span dir=\"rtl\"><span dir=\"rtl\">קליל וכ׳</span> (<span dir=\"rtl\">דבר</span>) <span dir=\"rtl\">ל&quot;א אין לשון ק׳ אלא</span></span> another version reads: by <i>ḳoli</i> we understand, parched in a vessel (in something hollow); how is this? A tube for parching grain was there &amp;c. Sifra Emor ch. XI, Par. 10 <span dir=\"rtl\">קמח ק׳</span> flour made of parched grain; <span class=\"citation\">Men. X, 5</span> <span dir=\"rtl\">קמח וק׳</span> (Bab. ed. 67ᵇ <span dir=\"rtl\">קמח ק׳</span>); <span class=\"citation\">Pes. 10ᵇ</span> bot. <span dir=\"rtl\">קמח וק׳</span> (corr. acc.). <span class=\"citation\">Ib. 11ᵃ</span> <span dir=\"rtl\">מק׳ ואילך</span> from the time the grain is parched and onward (when the soft grain is unfit for immediate consumption); <span dir=\"rtl\">עד ק׳</span> up to the time when grain can be parched; <span class=\"citation\">Men. 68ᵃ</span>. <span class=\"citation\">Sabb. 155ᵇ</span> <span dir=\"rtl\">אין גובלין את הק׳</span> you must not mix flour of parched grains (with oil &amp;c., on the Sabbath). <span class=\"citation\">Tosef. Pes. II</span> (<span class=\"citation\">III), 4</span> <span dir=\"rtl\">ק׳ שירד לתוכו דלף</span> (not <span dir=\"rtl\">לתוכה</span>) parched grain on which drippings have fallen; a. fr.—Pl. <span dir=\"rtl\">קְלָיוֹת</span>, <a href=\"#\" data-headword=\"קְלָאִים\">קְלָאִים</a>, <a href=\"#\" data-headword=\"קְלָאִים\">קְלָאִין</a>. <span class=\"citation\">Men. 66ᵇ</span> <span dir=\"rtl\">אבוב של ק׳</span> (not <span dir=\"rtl\">אביב</span>); <span class=\"citation\">Kel. II, 3</span>; Sifra Vayikra, l. c.; <span class=\"citation\">Yalk. Lev. 456</span>, v. <a href=\"#\" data-headword=\"אַבּוּב\">אַבּוּב</a>. <span class=\"citation\">Keth. II, 1</span> <span dir=\"rtl\">חלוק ק׳</span>, v. <a href=\"#\" data-headword=\"חִילּוּק\">חִילּוּק</a>. Y. ib. 28ᵇ top <span dir=\"rtl\">בתולה … אין לה חילוק ק׳</span> at the wedding of a virgin that had been married before, no distribution of roasted ears takes place; a. fr.</div>","alt":[]},"28183":{"h":"קָלִי ²","r":"S01321","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. XXIII, 14</span> (Y. ed. Amst. <a href=\"#\" data-headword=\"קְלֵי\">קְלִי</a>). <span class=\"citation\">Targ. Ruth II, 14</span>. <span class=\"citation\">Targ. I Sam. XVII, 17</span> (some ed. <a href=\"#\" data-headword=\"קַלְיָא II\">קָלְיָא</a>). <span class=\"citation\">Ib. XXV, 18</span> (ed. Wil. <a href=\"#\" data-headword=\"קָלִי ²\">קָלַיָּא</a> pl.).—V. <a href=\"#\" data-headword=\"קוּלְיָא II\"><span dir=\"rtl\">קוּלְיָא</span> I</a>.</div>","alt":["קְלֵי II","קַלְיָא I"]},"28184":{"h":"קַלְיָא II","r":"S01322","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָלִי ²\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>fiery</i> (<i>poisonous</i>) <i>serpent</i>. <span class=\"citation\">Targ. O. Num. XXI, 8</span>.</div><div class=\"sense\"><b>—2)</b> <i>ashes of an alkaline plant</i>, v. <a href=\"#\" data-headword=\"קוּלְיָא II\"><span dir=\"rtl\">קוּלְיָא</span> II</a>.</div>","alt":["קָלְיָא"]},"28185":{"h":"קְלִיאוֹפַטְרָא","r":"S01323","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>Cleopatra</i>, queen of Egypt. <span class=\"citation\">Nidd. 30ᵇ</span> <span dir=\"rtl\">ק׳ מלכה אלכסנדרוס</span> (read: <span dir=\"rtl\">מ׳ אלכסנדרית</span> or <span dir=\"rtl\">מלכת אלכסנדריא</span>) C. the queen of Alexandria; <span class=\"citation\">ib.</span> <span dir=\"rtl\">קלפטרא מלכת יוונית</span> (corr. acc.); <span class=\"citation\">Tosef. ib. IV, 17</span> <span dir=\"rtl\">גלפטרה מלכת אלכנדריס</span> ed. Zuck. (oth. ed. <span dir=\"rtl\">גלופטרא … אלכסנדרית</span>, <a href=\"#\" data-headword=\"קְלוּפַטְרָא\">קלופטרא</a>).</div>","alt":[]},"28186":{"h":"קְלִיבוֹסֶת","r":"S01324","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כַּלְבּוּס\">כַּלְבּוּס</a>) <i>the lowest end of the vertebrae, coccyx</i>. <span class=\"citation\">Sabb. 152ᵃ</span> (expl. <span dir=\"rtl\">השקד</span>, <span class=\"citation\">Koh. XII, 5</span>) <span dir=\"rtl\">זו ק׳</span> that means the coccyx (v. <a href=\"#\" data-headword=\"לוּז II\"><span dir=\"rtl\">לוּז</span> II</a>).</div>","alt":[]},"28187":{"h":"קְלִיבוּסְתָּא","r":"S01325","html":"<div class=\"sense\"> <span class=\"citation\">Ḥull. 93ᵃ</span> תרבא דאַקְּ׳ Ar. (ed. <a href=\"#\" data-headword=\"דּוֹקְרָנָא\">דק׳</a>) the fat on the coccyx.</div>","alt":[]},"28188":{"h":"קליבסים","r":"S01326","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִוְוסִין\">קְלִוְוסִין</a></div>","alt":[]},"28189":{"h":"קַלִּיגְרָפוֹן","r":"S01327","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (καλλιγραφῶν) [<i>fine writer</i>,] name of <i>a baker’s tool</i> resembling the stylus, with one pointed end to pick up the bread, called ‘the tooth’, and one flat and broad end to scrape the ashes out (v. <a href=\"#\" data-headword=\"גָּרַף\">גָּרַף</a>), called ‘the palm.’ <span class=\"citation\">Kel. XIII, 2</span> ק׳ שניטלה כפה וכ׳ Ar. (ed. <span dir=\"rtl\">קוליגריפון</span>; ed. Dehr. <a href=\"#\" data-headword=\"קלגריפון\">קלגריפון</a>) a <i>ḳ</i>. that has lost its palm, is susceptible to uncleanness on account of its tooth &amp;c. (v. <span class=\"citation\">Tosef. Kel. B. Mets. III, 7</span>, quot. s. v. <a href=\"#\" data-headword=\"צִנּוֹרָא III\"><span dir=\"rtl\">צִנּוֹרָא</span> III</a>).</div>","alt":[]},"28190":{"h":"קַלִּיד","r":"S01328","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלִּיד\">כַּלִּיד</a></div>","alt":["קַלִּידָא"]},"28191":{"h":"קְלִידָא","r":"S01329","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְלִידָא\">אַקְלִידָא</a></div>","alt":[]},"28192":{"h":"קָשַׁשׁ I","r":"S02266","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"קוּשׁ\">קוּשׁ</a>) (b. h.; <i>to join closely; to collect</i> (v. <span class=\"citation\">Targ. Zeph. II, 1</span>), esp. <i>to gather wood, rubbish</i> &amp;c. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">כמה … שׁיָקוֹשּׁוּ אותה עכשיו שקָשַׁשְׁתָּה וכ׳</span> how many working men should I have needed to gather it! Now that thou hast done it, come and receive thy reward; <span class=\"citation\">Yalk. Is. 313</span> <span dir=\"rtl\">שׁיְקוֹשְׁשׁוּ</span>; <span class=\"citation\">Yalk. Gen. 76</span> <span dir=\"rtl\">שׁיְקַשְׁקְשׁוּ … שׁקִישְׁקשְׁתָּ</span>.</div><div class=\"sense\"><b>Polel. קיֹשֵׁשׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קֶשֶׁר\">same</a>. Y. Snh. V, 22ᵈ top <span dir=\"rtl\">מְקוֹשֵׁשׁ משום וכ׳</span> of which crime was the gatherer of sticks (<span class=\"citation\">Num. XV, 32</span>) found guilty? of plucking, or of harvesting?; <span class=\"citation\">Sabb. 96ᵇ</span>; <span class=\"citation\">Sifré Num. 113</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומצאו אותו מק׳ וכ׳</span></div></div>","alt":[]},"28193":{"h":"קָשַׁשׁ II","r":"S02267","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"קוּשׁ\">קוּשׁ</a>) (v. <a href=\"#\" data-headword=\"קָשַׁט\">קָשַׁט</a>) <i>to be straight, stiff</i>. Denom. <a href=\"#\" data-headword=\"קַשׁ\">קַשׁ</a>. [Tanḥ. Naso 23 <span dir=\"rtl\">וקושש וכ׳</span>, v. <a href=\"#\" data-headword=\"קָשַׁט\">קָשַׁט</a>.]</div><div class=\"sense\"><b>Polel. קוֹשֵׁשׁ</b> <div class=\"sense\"><i>to shoot, aim</i>. <span class=\"citation\">Lam. R. to III, 12</span> מְקוֹשְׁשִׁים Ar. ed. Koh., v. <a href=\"#\" data-headword=\"קָשַׁט\">קָשַׁט</a>.</div></div>","alt":[]},"28194":{"h":"קְשַׁשׁ I","r":"S02268","html":"<div class=\"sense\"><b>Polel. קוֹשֵׁשׁ</b> <div class=\"sense\"><i>to straighten, correct</i>, v. infra.</div></div><div class=\"sense\"><b>Ithpolel. אִתְקוֹשֵׁשׁ</b> <div class=\"sense\"><i>to correct one’s self</i>. Y. Taan. II, 65ᵃ bot. (ref. to <span class=\"citation\">Zeph. II, 1</span>) <span dir=\"rtl\">נִתְקוֹשֵׁשׁ גרמן עד דלא נְקוֹשֵׁשׁ חורנין</span> let us correct ourselves before we correct others; v. <a href=\"#\" data-headword=\"קָשַׁט\">קָשַׁט</a></div></div>","alt":[]},"28195":{"h":"קְשַׁשׁ II","r":"S02269","html":"<div class=\"sense\"> (cmp. preced; a. <a href=\"#\" data-headword=\"קְשֵׁי\">קְשֵי</a>) [<i>to be hard</i>, cmp. <a href=\"#\" data-headword=\"יָשַׁן\">יָשַׁן</a>,] <i>to be old</i>. <span class=\"citation\">Targ. I Sam. XII, 2</span> קַשֵּׁית Levita (Regia <a href=\"#\" data-headword=\"קְשַׁת\">קָשֵׁית</a>; ed. Wil. <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קָשֵׁישׁ</a>, v. <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קַשִּׁישׁ</a>).—<span class=\"citation\">Keth. 95ᵇ</span> <span dir=\"rtl\">וקַשׁ לחמש שנין</span> and after five years the orchard grew old (ceased to bear). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כיון … עביד דקִישׁ</span> since they knew that an orchard is liable to get old. <span class=\"citation\">B. Bath. 167ᵇ</span> מֵיקַשׁ הוא דקַשְׁיָא וכ׳ Ms. R. (ed. <span dir=\"rtl\">מיקש הוא דקַשָּׁה לה</span>; Rashb. <span dir=\"rtl\">מִיקְשָׁא קשיא</span>) she has grown old, and her voice is rough. <span class=\"citation\">Ḥag. 13ᵃ</span> לא קַשָּׁאִי I am not old enough; <span dir=\"rtl\">כי קַשׁ נח וכ׳</span> when he was old enough, R. Joḥ. was dead. Ib. 5ᵇ. <span class=\"citation\">Snh. 108ᵇ</span> יהא רעוא דתֵיקוּשׁ ותינוק ולא תמות Ar. s. v. <a href=\"#\" data-headword=\"חל\">חל</a> 3 (ed. <span dir=\"rtl\">יהא רעוא דלא תמות</span>) be it God’s will that thou grow old and grow young again and never die; a. e.—V. <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קַשִּׁישׁ</a>.</div>","alt":[]},"28196":{"h":"קְשַׁת","r":"S02270","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קְשַׁט\">קְשַׁט</a>) <i>to shoot</i>. <span class=\"citation\">Targ. Ez. XXI, 26</span>. <span class=\"citation\">Targ. Y. II, Ex. XV, 4</span>; a. e.</div><div class=\"sense\"><b>Af. אַקְשֵׁית</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קְשַׁשׁ II\">same</a>. <span class=\"citation\">Targ. Is. XXXVII, 33</span> <span dir=\"rtl\">יַקְשִׁית</span> ed. Wil. (ed. Lag. <span dir=\"rtl\">יִקְשַׁת</span>); <span class=\"citation\">Targ. II Kings XIX, 32</span>.</div></div><div class=\"sense\"><b>Ithpa. אִתְקַשֵּׁת</b> <div class=\"sense\"><i>to be shot forth</i>. <span class=\"citation\">Targ. Y. II, Ex. XIX, 13</span> (v. <a href=\"#\" data-headword=\"קְשַׁט\">קְשַׁט</a>).</div></div>","alt":["קְשֵׁית"]},"28197":{"h":"קֶשֶׁת","r":"S02271","html":"<div class=\"sense\"> c. (b. h.; <a href=\"#\" data-headword=\"קְשַׁת\">preced.</a>) <i>bow; rainbow</i>. <span class=\"citation\">Erub. 55ᵃ</span> <span dir=\"rtl\">עיר העשויה כק׳</span> a town built in the shape of a bow; <span class=\"citation\">ib.</span> <span dir=\"rtl\">עשויה כמין ק׳</span>. <span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">הרואה את הק׳ בענן</span> he who sees a rainbow in the clouds. <span class=\"citation\">Ḥag. 16ᵃ</span>. <span class=\"citation\">Gen. R. s. 35</span>; a. fr.—Pl. <span dir=\"rtl\">קְשָתוֹת</span>. Lam. R. introd. (R. Joḥ. 1) (ref. to <span class=\"citation\">Is. XXII, 3</span>) <span dir=\"rtl\">שהיו מתירין גידי קַשְׁתּוֹתָם וכ׳</span> they loosened the strings of their bows and tied them with them; <span class=\"citation\">Yalk. Is. 289</span>. <span class=\"citation\">Sifré Deut. 18</span> <span dir=\"rtl\">עקרבים כק׳</span> scorpions as large as bows; <span class=\"citation\">Yalk. ib. 803</span>; a. e.—Trnsf. <i>membrum virile, potentia virilis</i>. <span class=\"citation\">Sot. 36ᵇ</span>; <span class=\"citation\">Y. Hor. II, 46ᵈ</span>; a. e.</div>","alt":[]},"28198":{"h":"קֶשֶׁת ²","r":"S02272","html":"<div class=\"sense\"><b>1)</b> <i>bow; rainbow</i>. <span class=\"citation\">Targ. Is. XXI, 15</span>. <span class=\"citation\">Targ. Gen. XXI, 16</span>. <span class=\"citation\">Ib. IX, 13</span>; a. fr.—Pl. <span dir=\"rtl\">קַשְׁתִּין</span>, <a href=\"#\" data-headword=\"קֶשֶׁת ²\">קַשְׁתָּן</a>, <span dir=\"rtl\">קַשְׁתָּתָא</span>, <span dir=\"rtl\">קַשְׁוָותָא</span>. <span class=\"citation\">Targ. Is. VII, 24</span>. <span class=\"citation\">Targ. II Chr. XXVI, 14</span>. <span class=\"citation\">Targ. I Sam. II, 4</span> <a href=\"#\" data-headword=\"קֶשֶׁת ²\">קַשְׁתַּת</a> constr. (followed by <span dir=\"rtl\">ד־</span>). <span class=\"citation\">Targ. Y. Gen. XXI, 20</span>. <span class=\"citation\">Targ. Ps. XXXVII, 14</span>, sq.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>the curved side of the stomach</i>, opp. to <a href=\"#\" data-headword=\"יִתְרָא\">יִתְרָא</a>. <span class=\"citation\">Ḥull. 50ᵃ</span> <span dir=\"rtl\">דאק׳</span></div>","alt":["קַשְׁתָּא"]},"28199":{"h":"קַשָּׁת","r":"S02273","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קֶשֶׁת ²\">preced.</a>) <i>archer</i>; esp. <a href=\"#\" data-headword=\"ק׳\">ק׳</a> (<a href=\"#\" data-headword=\"מַזָּל\">מזל</a>) <i>Sagittarius</i>, a sign of the Zodiac. <span class=\"citation\">Gen. R. s. 98</span>. <span class=\"citation\">Pesik. R. s. 20</span>; <span class=\"citation\">Yalk. Ex. 418</span>; a. e.—Pl. <span dir=\"rtl\">קַשָּׁתִים</span>, <span dir=\"rtl\">קַשָּׁתִין</span>. <span class=\"citation\">Lam. R. to II, 2</span>, a. e., v. <a href=\"#\" data-headword=\"קַשָּׁט\">קַשָּׁט</a>.</div>","alt":[]},"28200":{"h":"קַשָּׁתָא","r":"S02274","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XXI, 20</span> <span dir=\"rtl\">רביא ק׳</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"קֶשֶׁת ²\">קַשְׁתָּא</a>).—Pl. <span dir=\"rtl\">קַשָּׁתַיָּא</span>. <span class=\"citation\">Targ. I Sam. XXXI, 3</span> (not <span dir=\"rtl\">קַשְׁתַּיָּא</span>); <span class=\"citation\">Targ. I Chr. X, 3</span>. <span class=\"citation\">Ib. XVIII, 17</span>; <span class=\"citation\">Targ. II Sam. VIII, 18</span> (not <a href=\"#\" data-headword=\"קִישְׁקוּשָׁא\">קְשָׁ׳</a>; h. text <span dir=\"rtl\">כרתי</span>).—V. <a href=\"#\" data-headword=\"קַשְׁתּוֹיָא\">קַשְׁתּוֹיָא</a>.</div>","alt":[]},"28201":{"h":"קַשְׁתָּא I","r":"S02275","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֶשֶׁת\">קֶשֶׁת</a> ch.</div>","alt":[]},"28202":{"h":"קַשְׁתָּא II","r":"S02276","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḳashta</i>. <span class=\"citation\">B. Bath. 41ᵇ</span></div>","alt":[]},"28203":{"h":"קַשְׁתּוֹיָא","r":"S02277","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"קַשָּׁתָא\">קַשָּׁתָא</a>, <i>archer.</i>—Pl. <span dir=\"rtl\">קַשְתּוֹיֵי</span>. <span class=\"citation\">Yeb. 16ᵇ</span> (Tadmor furnished) <span dir=\"rtl\">שיתא אלפי ק׳</span> six thousand archers; v. <a href=\"#\" data-headword=\"קַשָּׁט\">קַשָּׁט</a>.</div>","alt":[]},"28204":{"h":"קַתְּ","r":"S02278","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"קֶנֶת\">קֶנֶת</a>, <i>handle, helve</i>. <span class=\"citation\">Macc. II, 1</span> <span dir=\"rtl\">נשמט הברזל מִקַּתּוֹ</span> if the axe-head slipped off its handle; v. <a href=\"#\" data-headword=\"קֶנֶת\">קֶנֶת</a>.</div>","alt":[]},"28205":{"h":"קַתָּא","r":"S02279","html":"<div class=\"sense\"> <span class=\"citation\">B. Mets. 82ᵃ</span>; <span class=\"citation\">Shebu. 43ᵇ</span> <span dir=\"rtl\">ההיא דאוזפיה … ק׳ דמגלא וכ׳</span> if one lends to his neighbor a thousand Zuz, and the latter leaves as a pledge the handle of a saw; <span dir=\"rtl\">אבד ק׳ וכ׳</span> if the handle is lost, the loan is lost. Ib. <span dir=\"rtl\">אבל ק׳ ונסכא</span> but if he deposits a handle and a silver bar. <span class=\"citation\">B. Mets. 103ᵃ</span> <span dir=\"rtl\">מהדר ליה קַתֵּיה</span> he returns to him the handle (of the broken mattock). <span class=\"citation\">Snh. 27ᵇ</span> top, v. <a href=\"#\" data-headword=\"*בּוּרְטְיָא\">בּוּרְטְיָא</a>; a. e.—Pl. <a href=\"#\" data-headword=\"קַבַּיָּא\">קַתַּיָּא</a>, <span dir=\"rtl\">קַתָּתָא</span>, <a href=\"#\" data-headword=\"קַתָּאתֵי\">קַתָּתֵי</a>. <span class=\"citation\">Pes. 30ᵇ</span> <span dir=\"rtl\">קַתַּיְיהוּ בטינא וכ׳</span> cover the helves of the knives with clay &amp;c. <span class=\"citation\">Bets. 33ᵇ</span>; <span class=\"citation\">Yoma 37ᵇ</span>, v. <a href=\"#\" data-headword=\"נַרְגָּא\">נַרְגָּא</a>. Shebu. l. c. <span dir=\"rtl\">קתתי</span> Ms. M. (ed. <a href=\"#\" data-headword=\"קַתָּאתֵי\">קִתָּאתֵי</a>).</div>","alt":[]},"28206":{"h":"קָתָא","r":"S02280","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קָאָת\">קָאָת</a>, <i>pelican</i>. <span class=\"citation\">Targ. O. Lev. XI, 18</span> <span dir=\"rtl\">קתא</span> ed. Berl. (oth. ed. <span dir=\"rtl\">קאתא</span>); <span class=\"citation\">Deut. XIV, 17</span> (Y. <span dir=\"rtl\">קקא</span>). <span class=\"citation\">Targ. Ps. CII, 7</span> (ed. Lag. <span dir=\"rtl\">קקתא</span>).</div>","alt":["קָאתָא"]},"28207":{"h":"קתאליקי","r":"S02281","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָתוֹלִיקוֹס\">קָתוֹלִיקוֹס</a></div>","alt":[]},"28208":{"h":"קְתָארָא","r":"S02282","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְתָרָא\">קְתָרָא</a></div>","alt":[]},"28209":{"h":"קַתָּאתֵי","r":"S02283","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַתָּא\">קַתָּא</a></div>","alt":[]},"28210":{"h":"קַתְבִּי","r":"S02284","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּטְבִּי\">קוּטְבִּי</a></div>","alt":[]},"28211":{"h":"קְתִדְרָא","r":"S02285","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (καθέδρα) <i>a soft seat, chair with back</i>. <span class=\"citation\">Keth. V, 5</span> <span dir=\"rtl\">ארבע יושבת בק׳</span> (not <a href=\"#\" data-headword=\"אַרְבְּעָה\">ארבעה</a>) if the wife brought four maids, she may sit in the chair (need not do any house work). <span class=\"citation\">Ib. 61ᵃ</span>. <span class=\"citation\">Kel. IV, 3</span> <span dir=\"rtl\">כמין ק׳</span> (Mish. ed. <span dir=\"rtl\">רָה …</span>) in the shape of a cathedra (with a curved or hollow back). <span class=\"citation\">Ib. XXIV, 2</span> <span dir=\"rtl\">העשויה כק׳</span> a wagon seat formed like a cathedra. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"ק׳\">ק׳</a> (<a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a>) <span dir=\"rtl\">בכל מקום … מציעין לו</span></span> wherever one of the sons of Jerusalem came to a country place, they spread for him a cathedra to sit on it, in order to hear his wisdom. Pesik. Vayḥi, p. 7ᵇ (ref. to <span class=\"citation\">I Kings X, 19</span>) <span dir=\"rtl\">כהדא ק׳ דמשה</span> like the seat of Moses (v. Revue des Ét. Juives XXXIV, p. 99, sq.); <span class=\"citation\">Esth. R. to I, 2</span> <span dir=\"rtl\">קדירתא דדרניש</span> (read: <span dir=\"rtl\">קתידרא</span>); <span class=\"citation\">Ex. R. s. 43</span> <span dir=\"rtl\">ק׳ עשו לו כק׳ וכ׳</span> they made for him (Moses) a seat like the scholars’ cathedra in which one sits and yet seems to be standing; a. e.—Pl. <span dir=\"rtl\">קְתִדְראוֹת</span>, <span dir=\"rtl\">קְתִדְרָיוֹת</span>, <a href=\"#\" data-headword=\"קְתִדְרָא\">קְתִיד׳</a>. <span class=\"citation\">Y. Succ. V, beg. 55ᵃ</span> <span dir=\"rtl\">ושבעים ק׳ וכ׳</span> seventy gilt chairs were there (in the synagogue of Alexandria), beset with precious stones &amp;c.; Bab. <span class=\"citation\">Succ. 51ᵇ</span>; <span class=\"citation\">Tosef. ib. IV, 6</span> <span dir=\"rtl\">שבעים ואחת ק׳</span>. Y. Ber. VI, 10ᵈ top; a. e.</div>","alt":["קְתִדְרָה","קְתִידְ׳"]},"28212":{"h":"קְתִדְרִין","r":"S02286","html":"<div class=\"sense\"> m. (καθέδριον) <a href=\"#\" data-headword=\"קְתִדְרָא\">same</a>. <span class=\"citation\">Y. Yoma IV, 41ᶜ</span> top <span dir=\"rtl\">כמלך … על ק׳ שלו</span> like a king seated on his chair. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">ק׳ דדין לקבל ק׳ דדין</span> the chair of one opposite that of the other; a. e.</div>","alt":["קְתִידְ׳"]},"28213":{"h":"קתוליכוס","r":"S02287","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָתוֹלִיקוֹס\">next w.</a></div>","alt":[]},"28214":{"h":"קָתוֹלִיקוֹס","r":"S02288","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (καθολικός) <i>financial officer, controller</i>, esp. <i>catholicos</i>, an officer of the Temple treasury. <span class=\"citation\">Ex. R. s. 37</span>, beg. <span dir=\"rtl\">למלך … ק׳ ומנהו וכ׳</span> like a king that had a friend, and when he wanted to appoint a controller, he appointed him over his entire treasury; Y’lamd. to Gen. XLIX, 1 quot. in Ar. <a href=\"#\" data-headword=\"קתוליכוס\">קתוליכוס</a> (corr. acc.). <span class=\"citation\">Num. R. s. 18</span> קרח שהיה ק׳ וכ׳ Korah who was the controller of Pharaoh’s palace and had in charge the keys &amp;c. Y. Shek. V, 49ᵃ <span dir=\"rtl\">קתיליקוס</span>, <a href=\"#\" data-headword=\"קתיליקון\">קתיליקון</a>, <span dir=\"rtl\">קתיליקיס</span> (Bab. ed. <span dir=\"rtl\">קתליקין</span>, <span dir=\"rtl\">קתליקין</span>; corr. acc.); a. e.—Pl. <span dir=\"rtl\">קָתוֹלִיקִין</span>. Ib. <span dir=\"rtl\">אין פיחתין משני ק׳</span> (Bab. ed. a. ed. Zyt. <span dir=\"rtl\">כתל׳</span>, corr. acc.) there were never less than two catholici in the Temple treasury.—<span class=\"citation\">Cant. R. to VII, 9</span> (expl. <a href=\"#\" data-headword=\"*פְּחוּתָא\">פחותא</a>, <span class=\"citation\">Dan. III, 2</span>) <a href=\"#\" data-headword=\"קתאליקי\">קתאליקי</a> (some ed. <span dir=\"rtl\">קאת׳</span>), read <span dir=\"rtl\">קָתוֹלִיקֵי</span> or <span dir=\"rtl\">קָאת׳</span> (ch. pl.) controllers.</div>","alt":["קָתְלִי׳"]},"28215":{"h":"קתוניא","r":"S02289","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Num. XXXI, 23</span>, v. <a href=\"#\" data-headword=\"קִיתוֹן ²\">קִיתוֹנָא</a></div>","alt":[]},"28216":{"h":"קתיליקון","r":"S02290","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָתוֹלִיקוֹס\">קָתוֹלִיקוֹס</a></div>","alt":["קוס","קיס"]},"28217":{"h":"קתכו","r":"S02291","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּטְבִּי\">קוּטְּבִי</a></div>","alt":[]},"28218":{"h":"קָתְלָא","r":"S02292","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">קָתְלֵי</span>, v. <a href=\"#\" data-headword=\"כּוֹתְלָא\">כּוֹתְלָא</a>.</div>","alt":[]},"28219":{"h":"קתליכוס","r":"S02293","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָתוֹלִיקוֹס\">קָתוֹלִיקוֹס</a></div>","alt":["יקוס","קין"]},"28220":{"h":"*קֶתֶר","r":"S02294","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">קְתָרִין</span> (cmp. <a href=\"#\" data-headword=\"קֶשֶׁר\">קֶשֶׁר</a>) <i>hard, rocky substances, bowlders</i>. Y’lamd. to Lev. XXVI, 3 quot. in Ar. (ref. to <span class=\"citation\">Lev. XXVI, 4</span>, a. <span class=\"citation\">19</span>) [read:] <span dir=\"rtl\">ונתנה הארץ יבולה ואין הארץ מתקנת לכם ק׳ ואת ארצכם כנחושה הרי הארץ מתקנת לכם ק׳</span> ‘and the land shall yield its increase’, and the land shall not generate bowlders for you, ‘and your earth as brass’, behold, the land shall generate bowlders for you; [Landau: ‘<i>thorns and thistles</i>, v. Löw, Pfl., p. 341; v. however, next w.]</div>","alt":[]},"28221":{"h":"קְתָרָא","r":"S02295","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*קֶתֶר\">preced.</a>, cmp. also <a href=\"#\" data-headword=\"קָתְלָא\">קתלא</a> a. <span dir=\"rtl\">כתלא</span>; v. P. Sm. 3777) <i>rocky cleft.</i>—Pl. <span dir=\"rtl\">קְתָרִין</span>. <span class=\"citation\">Targ. Prov. XXX, 26</span> (ed. Lag. <span dir=\"rtl\">קְתָארִי</span>; h. text <a href=\"#\" data-headword=\"סֶלַע\">סלע</a>).</div>","alt":[]},"28222":{"h":"קַתְרוֹס I","r":"S02296","html":"<div class=\"sense\"><i>cedar</i>, v. <a href=\"#\" data-headword=\"קַדְרוֹס I\"><span dir=\"rtl\">קַדְרוֹס</span> I</a>.—[<span class=\"citation\">Tosef. Ukts. I, 6</span>, v. <a href=\"#\" data-headword=\"קִינָרָס\">קִינָּרָס</a>.]</div>","alt":[]},"28223":{"h":"קַתְרוֹס II","r":"S02297","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḳathros</i>. <span class=\"citation\">Pes. 57ᵃ</span> <span dir=\"rtl\">בית ק׳</span> name of a priestly family, (supposed to be identical with Κανθηρᾶς, Jos. Ant. XX, 1, 3); <span class=\"citation\">Tosef. Men. XIII, 21</span> <a href=\"#\" data-headword=\"קַדְרוֹס I\">קַדְרוֹס</a>.</div>","alt":[]},"28224":{"h":"קַתְרוֹס III","r":"S02298","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κιθάρα, κίθαρις, prob. of Semitic origin) a kind of <i>lute</i> or <i>lyre</i>. [<span class=\"citation\">Dan. III, 5</span>, K’thib <a href=\"#\" data-headword=\"קִיתְרֹס\">קִיתְרֹס</a>] <span class=\"citation\">Targ. Is. V, 12</span> (some ed. <a href=\"#\" data-headword=\"קַנְתְּרוֹס\">קנתרוס</a>; h. text <a href=\"#\" data-headword=\"תֹּף\">תֹּף</a>!).—Pl. <span dir=\"rtl\">קַתְרוֹסִין</span>. <span class=\"citation\">Targ. Koh. II, 8</span>.</div>","alt":[]},"28225":{"h":"ר","r":"T00000","html":"<div class=\"sense\"><i>Resh</i>, the twentieth letter of the alphabet. It interchanges with <a href=\"#\" data-headword=\"ל\">ל</a>, v. <a href=\"#\" data-headword=\"ל\">ל</a>; with <a href=\"#\" data-headword=\"ד\">ד</a>, e. g. <a href=\"#\" data-headword=\"גָּרַר I\">גָּרַר</a> a. <a href=\"#\" data-headword=\"גָּרַד\">גָּרַד</a>, <a href=\"#\" data-headword=\"צָרַר\">צָרַד</a> a. <a href=\"#\" data-headword=\"צָרַר\">צָרַר</a>.—It is frequently inserted between the first and the second radical letters, forming Parel verbs or nouns, e.g. <a href=\"#\" data-headword=\"גַּרְבֵּל\">גַּרְבֵּל</a>, <a href=\"#\" data-headword=\"קִרְסֵם\">קִרְסֵם</a>, <a href=\"#\" data-headword=\"שַׁרְבִיט\">שַׁרְבִיט</a>. It is sometimes a formative letter added at the end, e. g. <a href=\"#\" data-headword=\"חֲלִיטָר\">חֲלֵיטַר</a>, <a href=\"#\" data-headword=\"קִנְטֵר\">קִנְטֵר</a>.—<a href=\"#\" data-headword=\"ר\">ר</a> dropped at the end, e. g. <a href=\"#\" data-headword=\"אֲמִי\">אֲמִי</a> = <a href=\"#\" data-headword=\"אֲמַר\">אֲמַר</a>.</div>","alt":[]},"28226":{"h":"ר׳","r":"T00001","html":"<div class=\"sense\">, as a numeral letter, <i>two hundred</i>, v. <a href=\"#\" data-headword=\"א׳\">א׳</a>.</div>","alt":[]},"28227":{"h":"ראבג","r":"T00002","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XVIII, 8</span> <span dir=\"rtl\">מראבגן</span> some ed., read: <span dir=\"rtl\">מדאבנן</span>, v. <a href=\"#\" data-headword=\"*דַּאֲבַן\">דַּאֲבַן</a>.</div>","alt":[]},"28228":{"h":"רָאֵג","r":"T00003","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (part. of <span dir=\"rtl\">רוג</span> = <a href=\"#\" data-headword=\"רְגַג\">רְגַג</a>) <i>desirous for, coveting, anxious for</i>. <span class=\"citation\">Targ. Prov. XII, 12</span>. <span class=\"citation\">Ib. XXI, 26</span>.—<i>Fem</i>. <span dir=\"rtl\">רָיְגָא</span>, <span dir=\"rtl\">רָיְיגָא</span>. <span class=\"citation\">Ib. 10</span>.</div>","alt":["רָאֵיג"]},"28229":{"h":"ראגניות","r":"T00004","html":"<div class=\"sense\">, Tanḥ. Naso 12, v. <a href=\"#\" data-headword=\"רוֹטְנָנִית\">רוֹטְנָנִית</a></div>","alt":[]},"28230":{"h":"רַאֲגָתָא","r":"T00005","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ראגניות\">preced. art.</a>) <i>gratification of desires, caresses</i>. <span class=\"citation\">Targ. Prov. VII, 18</span> ed. Ven. (oth. ed. <a href=\"#\" data-headword=\"רִגְאֲגָתָא\">רִגְאֲגָתָא</a>; ed. Lag. <a href=\"#\" data-headword=\"רִגְאֲגָתָא\">רגאתא</a>, corr. acc.; h. text <span dir=\"rtl\">אהבים</span>).</div>","alt":[]},"28231":{"h":"רָאדוּ","r":"T00006","html":"<div class=\"sense\">, v. <span dir=\"rtl\">רְדי III</span></div>","alt":[]},"28232":{"h":"רָאדַיָּא","r":"T00007","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַדְיָא\">רַדְוָא</a></div>","alt":[]},"28233":{"h":"רָאָה I","r":"T00008","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"ראי\">ראי</a></div>","alt":[]},"28234":{"h":"רָאָה II","r":"T00009","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>raah</i>, name of an unclean bird. <span class=\"citation\">Ḥull. 63ᵇ</span> <span dir=\"rtl\">דאה ור׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"דָּאָה II\"><span dir=\"rtl\">דָּאָה</span> II</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ זו איה … ר׳ שרואה ביותר</span> <i>raah</i> is the same as <i>ayah</i>, and it is called <i>raah</i>, because its sight is exceedingly acute (ref. to <span class=\"citation\">Job XXVIII, 7</span>).</div>","alt":[]},"28235":{"h":"רֶאוְמָטִיקוֹס","r":"T00010","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ῥευματικός) <i>subject to, afflicted with flux</i> or <i>rheumatism</i>. <span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">נעשה ר׳</span> (not <a href=\"#\" data-headword=\"ד׳\">ד׳</a>; Ar. <span dir=\"rtl\">רמתיקוס</span>, ed. Koh. <span dir=\"rtl\">אירומתקוס</span>), v. <a href=\"#\" data-headword=\"עָצַל\">עָצַל</a>.</div>","alt":[]},"28236":{"h":"ראי","r":"T00011","html":"<div class=\"sense\"> (b. h.) [<i>to meet with</i>,] </div><div class=\"sense\"><b>1)</b> <i>to see</i>. <span class=\"citation\">Ber. IX, 1</span> <span dir=\"rtl\">הרואֶה מקום וכ׳</span> he who sees (comes to) a place &amp;c. <span class=\"citation\">Ib. 56ᵇ</span> <span dir=\"rtl\">הרואה נהר בחלום</span> he who sees a river in his dream. <span class=\"citation\">B. Bath. 82ᵃ</span> <span dir=\"rtl\">כל שרואה פני חמה</span>, v. <a href=\"#\" data-headword=\"גֶּזַע\">גֶּזַע</a>. <span class=\"citation\">Gen. R. s. 56</span> <span dir=\"rtl\">רוֹאִים אתם … רואה</span> do you see what I see? <span class=\"citation\">Ex. R. s. 3</span> <span dir=\"rtl\">אתה רואה ראייה אחת וכ׳</span> thou seest only one vision, but I see two; <span dir=\"rtl\">אתה רואה אותן באין וכ׳</span> thou seest them come to Sinai and receive my Law, but I see &amp;c. <span class=\"citation\">B. Mets. 73ᵇ</span> <span dir=\"rtl\">רָאִיתָ שאינו וכ׳</span> if thou observest that he does not conduct himself properly; a. v. fr.—<span class=\"citation\">Snh. 52ᵃ</span> <span dir=\"rtl\">הֵנִרְאֶה מי וכ׳</span> (Ms. M. <span dir=\"rtl\">הֵא נראה</span>) well, we shall see which &amp;c., v. <a href=\"#\" data-headword=\"קָבַר\">קָבַר</a>. <span class=\"citation\">Sabb. 150ᵃ</span> <span dir=\"rtl\">לא יאמר … הנראה שתעמור וכ׳</span> one must not say to one’s neighbor (on the Sabbath), well, we shall see (I am confident) that you will be with me in the evening (for business); <span class=\"citation\">Ab. Zar. 7ᵃ</span> (Tosaf. = <span dir=\"rtl\">הֲנִרְאֶה בעיניך</span>, <i>Nif.</i> is it pleasing to thee?); <span class=\"citation\">Tosef. Sabb. XVII</span> (<span class=\"citation\">XVIII), 11</span> <a href=\"#\" data-headword=\"ראי\">נראה</a> ed. Zuck. (Var. <span dir=\"rtl\">הנ׳</span>). <span class=\"citation\">Sifré Num. 84</span> <span dir=\"rtl\">הנראה שתגיע עמנו וכ׳</span> be sure to arrive with (meet) us at &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הנ׳ שתעמידני וכ׳</span> be sure to wake me up, for I &amp;c.—<span dir=\"rtl\">ר׳ דם</span>, <span dir=\"rtl\">ר׳ קרי</span> &amp;c. <i>to have an attack, be affected with</i>. <span class=\"citation\">Yeb. 76ᵃ</span> <span dir=\"rtl\">לא ר׳ קרי מימיו</span> he never had a nightly pollution. <span class=\"citation\">Zab. I, 1</span> <span dir=\"rtl\">ר׳ אחת … ובשלישי ר׳ שתים</span> (sub. <a href=\"#\" data-headword=\"זִיבָה II\">זיבה</a>) if he felt one attack of gonorrhœa …, and on the third day he had two attacks. <span class=\"citation\">Ber. III, 6</span> <span dir=\"rtl\">רָאֲתָה נדה</span> (sub. <a href=\"#\" data-headword=\"דָּם\">דם</a>) felt menstruation. <span class=\"citation\">Ib. 26ᵃ</span> <span dir=\"rtl\">ר׳ זיבה</span> felt a flux; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to reflect; to reason; to consider</i>. <span class=\"citation\">B. Bath. 83ᵃ</span> <span dir=\"rtl\">רוֹאִין … כאילו וכ׳</span> we consider the central vine-trees as if not existing. <span class=\"citation\">Erub. I, 5</span> <span dir=\"rtl\">רואין אותה … מתכת</span> we consider it (the cross-piece of straw or reeds) as if it were of metal; <span dir=\"rtl\">עקומה רואין וכ׳</span> if it is curved, we consider it as if it were straight. Gen. R. l. c. <span dir=\"rtl\">הוי רואה דמיו וכ׳</span> look upon the blood of this ram, as if it were the blood of &amp;c.; a. v. fr.—<span dir=\"rtl\">מה ר׳</span> what did he see?, <i>what was the reason</i>; in gen. <i>why</i>? <span class=\"citation\">B. Bath. 123ᵃ</span> <span dir=\"rtl\">מה ר׳ יעקב שנטל וכ׳</span> what reason had Jacob to take the birthright from Reuben? <span class=\"citation\">Pes. 53ᵇ</span> <span dir=\"rtl\">מה רָאוּ … שמסרו וכ׳</span> what did Hananiah, Mishael and Azariah have in mind (how did they reason) when they were ready to give up their lives &amp;c.? <span class=\"citation\">Sifré Deut. 307</span> <span dir=\"rtl\">מה ראו … שנשטפו וכ׳</span> why were the men of the flood drowned &amp;c.?; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to see the reason of, to like, choose, prefer, approve of</i>. <span class=\"citation\">Keth. XIII, 3</span>, sq. <span dir=\"rtl\">רואה אני את רברי וכ׳</span> I like the opinion of Admon. <span class=\"citation\">Ib. 109ᵃ</span> <span dir=\"rtl\">כל מקום שאמר … רואח אני וכ׳</span> wherever R. G. said, I like &amp;c., that opinion is the adopted rule. <span class=\"citation\">Ab. II, 7</span> רואה אני … מדבריכם I prefer what El. … said to what you said; a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">רָאוּי</span>; <i>f</i>. <span dir=\"rtl\">רְאוּיָה</span>; pl. <span dir=\"rtl\">רְאוּיִים</span>, <span dir=\"rtl\">רְאוּיִין</span>; <span dir=\"rtl\">רְאוּיוֹת</span> <i>chosen, selected; designated, predestined; fit, worthy, adapted</i> (v. <a href=\"#\" data-headword=\"חֲזִי\">חֲזִי</a>). <span class=\"citation\">Bekh. 59ᵇ</span>, a. e. <span dir=\"rtl\">מנין הר׳</span>, v. <a href=\"#\" data-headword=\"מִנְיָן\">מִנְיָן</a>. <span class=\"citation\">Ḥull. 83ᵇ</span>, a. fr. <span dir=\"rtl\">כל הר׳ לבילה</span> whatever is capable of being mixed, v. <a href=\"#\" data-headword=\"בִּילָה\">בִּילָה</a>. <span class=\"citation\">Nidd. VI, 4</span> <span dir=\"rtl\">כל הר׳ לדון וכ׳</span> whoever is fit (authorized) to give judgment in a criminal court, is fit &amp;c. <span class=\"citation\">Sabb. 89ᵇ</span> ר׳ היה יעקב וכ׳ Jacob was destined to go down to Egypt in iron chains, but his merits were the cause (that no such force was used). <span class=\"citation\">Snh. 107ᵃ</span> ר׳ היתה וכ׳ Bathsheba … was predestined (as wife) for David, only he anticipated fate, v. <a href=\"#\" data-headword=\"פַּגָּה\">פַּגָּה</a>. <span class=\"citation\">Ber. 4ᵃ</span> <span dir=\"rtl\">ר׳ היו ישראל ליעשות וכ׳</span> it had been intended that a miracle be performed for the Israelites in Ezra’s days, as it has been in Joshua’s time, but sin was the cause (that it was not done). <span class=\"citation\">Nidd. 60ᵃ</span> <span dir=\"rtl\">ר׳ לראות</span> fit (old enough) to have menstruation; a. v. fr.</div><div class=\"sense\"><b>Nif. נִרְאָה</b> <div class=\"sense\"><b>1)</b> <i>to be seen, be visible; to appear; to seem</i>. <span class=\"citation\">Gen. R. s. 48</span> <span dir=\"rtl\">נִרְאִין כאוכלין וכ׳</span> they had the appearance of eating, one course after the other being removed. <span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">בפנים הרבה נ׳ להם וכ׳</span> the Lord appeared to them at Sinai with various expressions of countenance. Pesik. Vayhi, p. 5ᵃ <span dir=\"rtl\">קרסי זהב נראין … הנראין וכ׳</span>, v. <a href=\"#\" data-headword=\"קֶרֶס\">קֶרֶס</a>. <span class=\"citation\">Ḥag. 2ᵃ</span>; <span class=\"citation\">Snh. 4ᵇ</span>, a. e. (ref. to <a href=\"#\" data-headword=\"יִרְאָה\">יראה</a>, <span class=\"citation\">Ex. XXIII, 17</span>) <span dir=\"rtl\">יִרְאֶה יֵרָאֶה … לִרְאוֹת … לֵירָאוֹת</span> you may read it <i>yireh</i> (he shall see, the Lord) or <i>yeraëh</i> (he shall be seen): as He comes to see, so does He come to be seen (i.e. he that is blind in one eye is exempt from visiting the Temple. <span class=\"citation\">Ḥag. 5ᵇ</span> <span dir=\"rtl\">הנראין ואינן רואין … הרואים יאינן נראין</span>, v. <a href=\"#\" data-headword=\"קָבַל I\"><span dir=\"rtl\">קָבַל</span> I</a>, <i>Hif.</i>—<span class=\"citation\">Pes. 53ᵃ</span> <span dir=\"rtl\">שנ׳ כמקדיש וכ׳</span> it looks as if he dedicated his animal as a sacrifice, and were to eat sacred meat outside of the Temple. <span class=\"citation\">Ab. II, 3</span> <span dir=\"rtl\">נראין כאוהבין וכ׳</span> they appear to be friends as long as it profits them; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to become fit, be fit</i>. <span class=\"citation\">Yoma 64ᵃ</span>, v. <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>. <span class=\"citation\">Succ. 33ᵇ</span> <span dir=\"rtl\">נ׳ ונדחה חוזר ונ׳</span> what had been fit at one time of the Holy Day, and was discarded (on account of a temporary unfitness), may again become fit (for use on the same day); a. e.</div><div class=\"sense\"><b>—3)</b> <i>to be liked, approved of; to appear reasonable</i>. <span class=\"citation\">Ḥull. 108ᵇ</span> נ׳ דברי וכ׳ R. Judah’s opinion is acceptable in the event that no stirring has taken place. <span class=\"citation\">Ib. 109ᵃ</span> נ׳ דברי ר׳ י׳ בהא … בהא R. Judah’s opinion is acceptable in such a case, and that of the scholars in such a case. <span class=\"citation\">Ber. 33ᵇ</span> ר׳ חייא … נראין R. Ḥ. bar Abba reported Rabbi to have said <i>nirin</i> (it seems acceptable), contrad. to <span dir=\"rtl\">מטין</span> a. <a href=\"#\" data-headword=\"מוֹדִים\">מודים</a>; <span class=\"citation\">Erub. 46ᵇ</span>; a. fr.</div></div><div class=\"sense\"><b>Hif. הֶרְאָה</b> <div class=\"sense\"><i>to cause to see; to show</i>. Pesik. Shek., p. 19ᵃ (ref. to <span class=\"citation\">Ex. XXX, 13</span>) <span dir=\"rtl\">כמין מטבע … והֶרְאֵהוּ למשה וכ׳</span> the Lord took a sort of a coin of fire from under his throne of glory and showed it to Moses, saying, ‘this they shall give’, like this &amp;c. Ib. p. 18ᵇ <span dir=\"rtl\">הקטנה ה׳ לדוד וכ׳</span> he (Joab) produced before David the smaller census, the larger he did not. <span class=\"citation\">Kidd. 48ᵇ</span>; <span class=\"citation\">B. Bath. 165ᵃ</span>, a. e. <span dir=\"rtl\">מרְאֶה מקום הוא לו</span> he merely indicated the place to him, v. <a href=\"#\" data-headword=\"קְפֵידָא\">קְפֵידָא</a>. <span class=\"citation\">Ber. 55ᵇ</span> <span dir=\"rtl\">מראין לו חלום טוב</span> is shown a good dream (vision). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הֶרְאוּהוּ חלומו וכ׳</span> was shown his own dream and the interpretation of his fellow prisoner’s dream. <span class=\"citation\">Ab. Zar. 5ᵃ</span> <span dir=\"rtl\">ה׳ לו הקב&quot;ה לאדם דור וכ׳</span> the Lord allowed Adam to see each coming generation and its preachers &amp;c. <span class=\"citation\">Taan. 10ᵇ</span> <span dir=\"rtl\">אל תַּרְאוּ עצמכם וכ׳</span>, v. <a href=\"#\" data-headword=\"שָׂבֵעַ I\"><span dir=\"rtl\">שָׂבֵעַ</span> I</a>; a. v. fr.—ה׳ פנים <i>a</i>) [<i>to show a</i> (<i>friendly</i>) <i>face</i>,] <i>to visit</i> the mourner. Y. M. Kat. III, 82ᵇ <span dir=\"rtl\">מפני … להַרְאוֹת וכ׳</span> why is it recommended to visit the mourner (on the Sabbath, when no other mourning ceremonies are otherwise observed)? Ib. 83ᵃ bot. <span dir=\"rtl\">אין מראין וכ׳</span> a mourner is not visited on New Year’s Day &amp;c. <span class=\"citation\">Gen. R. s. 100</span>; a. e.—<i>b</i>) <i>to enlighten, convince by clear argument</i>. <span class=\"citation\">Snh. 93ᵇ</span> (ref. to <span dir=\"rtl\">איש תאר</span>, <span class=\"citation\">I Sam. XVI, 18</span>) <span dir=\"rtl\">שמראה פנים בהלכה</span> he makes faces shine when he argues; <span class=\"citation\">Num. R. s. 13</span>; (<span class=\"citation\">Ruth R. to II, 1</span>; <span class=\"citation\">Yalk. Sam. 125</span> <span dir=\"rtl\">שמאיר</span>); a. e.</div></div><div class=\"sense\"><b>Hof. הוּרְאָה</b> <div class=\"sense\"><i>to be shown</i>. Y. M. Kat. III, 82ᶜ top <span dir=\"rtl\">אם הוּרְאוּ לו רוב פנים</span> if most of the faces have been shown him, i.e. if the majority of comforters have been to see him (v. supra).</div></div><div class=\"sense\"><b>Hithpa. הִתְרָאֶה</b> <div class=\"sense\"><i>to show one’s self</i>. <span class=\"citation\">Taan. 10ᵇ</span> <span dir=\"rtl\">שכח … אל יִתְרָאֶה בפני הצבור</span> if he forgot and ate and drank (in a place where a fast is held), he must not show himself before the people.</div></div>","alt":["רָאָה"]},"28237":{"h":"רֳאִי I","r":"T00012","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"ראי\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>sight</i>. <span class=\"citation\">Tosef. Hor. II, 5</span>; <span class=\"citation\">Gitt. 58ᵃ</span> <span dir=\"rtl\">תינוק … יפה עינים וטוב ר׳</span> there is a boy in prison … ‘fair of eyes and goodly to look upon’ (<span class=\"citation\">I Sam. XVI, 12</span>). <span class=\"citation\">Lev. R. s. 20</span>, beg. (ref. to I Sam. l. c.) <span dir=\"rtl\">טוב ר׳ בהלכה וכ׳</span> ‘goodly to look upon’ in legal decision; whoever looked up to him recalled what he had learned.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"הֲרֵי I\"><span dir=\"rtl\">הֲרֵי</span> I</a>) <i>aspect, nature of a case</i>. <span class=\"citation\">B. Kam. 3ᵇ</span> sq. <span dir=\"rtl\">לא ר׳ הקרן … כר׳ השן וכ׳</span> the case of goring, when nobody is benefited by the damage done, is not analogous to the case of damage by the tooth &amp;c. <span class=\"citation\">Zeb. 5ᵃ</span> <span dir=\"rtl\">לא ר׳ זה כר׳ זה … הצד השוה וכ׳</span> the nature of this (the burnt-offering) is not analogous to the nature of that (the guilt-offering): what is common to both is that &amp;c.; <span class=\"citation\">Kidd. 21ᵃ</span>; a. fr.</div>","alt":["רוֹאִי"]},"28238":{"h":"רֳאִי II","r":"T00013","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. Rashi to <span class=\"citation\">Nah. III, 6</span>) = <a href=\"#\" data-headword=\"רְעִי III\"><span dir=\"rtl\">רְעִי</span> II</a>, <i>excrement, discharge from the bowels</i>. Sifra M’tsorʿa, Zabim, Par. 1; <span class=\"citation\">Makhsh. VI, 7</span>.—[<span class=\"citation\">Sabb. XX, 4</span> (<span class=\"citation\">140ᵇ</span>) <span dir=\"rtl\">מפני הר׳</span>, Mish. Nap. a. Pes., v. Rabb. D. S. a. l. note 90, v. <a href=\"#\" data-headword=\"רְעִי ²\"><span dir=\"rtl\">רְעִי</span> I</a>.]—בית ר׳ <i>digestive organ, crop, maw</i>. Sifra Vayikra, N’dab., Par. 7, ch. IX <span dir=\"rtl\">מה אם … את בית הר׳ וכ׳</span> where the Scripture permits the use of the digestive organ (the maw of ruminants) &amp;c.; <span dir=\"rtl\">כאן שפסל בית הר׳ וכ׳</span> here (in the case of fowls) where the Scripture rejects the digestive organ (the crop) &amp;c.—[<span class=\"citation\">Kel. XVII, 2</span> <span dir=\"rtl\">בית הר׳</span> ed. Dehr., v. <a href=\"#\" data-headword=\"רְעִי III\"><span dir=\"rtl\">רְעִי</span> II</a>.]</div>","alt":[]},"28239":{"h":"רָאֵיג","r":"T00014","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָאֵג\">רָאֵג</a></div>","alt":[]},"28240":{"h":"רְאִיָּה","r":"T00015","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ראי\">רָאָה</a>) </div><div class=\"sense\"><b>1)</b> <i>seeing, look, glance</i>. <span class=\"citation\">B. Bath. 2ᵇ</span> <span dir=\"rtl\">היזק ר׳ לאו וכ׳</span> the discomfort of being exposed to (a neighbor’s) sight is no claimable damage; <span class=\"citation\">ib. 3ᵃ</span>; <span class=\"citation\">59ᵇ</span>. <span class=\"citation\">Nidd. 31ᵃ</span> <span dir=\"rtl\">רְאִיַּית העיין</span> the faculty of sight. <span class=\"citation\">Gen. R. s. 9</span> (ref. to <span class=\"citation\">Gen. I, 31</span>) <span dir=\"rtl\">מלך … ר׳ אחת וכ׳</span> when a human king builds a palace, he casts one (examining) glance at the upper stories and another at the lower; <span dir=\"rtl\">אבל … ר׳ אחת</span> but the Lord casts one look at both; <span dir=\"rtl\">העוה&quot;ז … ר׳ אחת</span> with one glance the Lord surveyed this world and the world to come; Yalk. ib. 15 <span dir=\"rtl\">בר׳</span>. <span class=\"citation\">Lam. R. to V, 1</span> ר׳ מרחוק <i>raah</i> is used for looking from a distance, v. <a href=\"#\" data-headword=\"הַבָּטָה\">הַבָּטָה</a>; a. fr.—Pl. <span dir=\"rtl\">רְאִיּוֹת</span>, <span dir=\"rtl\">רְאִיּיוֹת</span>. <span class=\"citation\">Ex. R. s. 3</span> (ref. to <span dir=\"rtl\">ראה ראיתי</span>, <span class=\"citation\">Ex. III, 7</span>) <span dir=\"rtl\">ואני רואה שתי ר׳</span>, v. <a href=\"#\" data-headword=\"ראי\">רָאָה</a>; Tanḥ. Sh’moth 20; <span class=\"citation\">Ex. R. s. 42</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (sub. <a href=\"#\" data-headword=\"קרי\">קרי</a>, <a href=\"#\" data-headword=\"דָּם\">דם</a>, <a href=\"#\" data-headword=\"זִיבָה II\">זיבה</a> &amp;c.) <i>feeling, affection, attack</i>. <span class=\"citation\">Zab. I, 1</span> <span dir=\"rtl\">הרואה ר׳ אחת של זוב</span> he who has had one attack of gonorrhœa. <span class=\"citation\">Ib. 6</span> <span dir=\"rtl\">מקצת הר׳ מהיום וכ׳</span> one of the attacks on one day, and another on the day after; a. fr.—<i>Pl.</i> as ab. <span class=\"citation\">Nidd. 37ᵇ</span> <span dir=\"rtl\">מטמיא בר׳ כבימים</span> becomes unclean by a certain number of attacks (even if they all be on one day) as well as by a certain number of days. <span class=\"citation\">B. Kam. 24ᵃ</span> <span dir=\"rtl\">קירבה רְאִיּוֹתֶיהָ</span> if she had her attacks at short intervals; <span dir=\"rtl\">ריחקה ר׳</span> at long intervals; a. e.</div><div class=\"sense\"><b>—3)</b>  (with ref. to <span class=\"citation\">Ex. XXIII, 17</span>) <i>appearance in the Temple, pilgrimage</i>. <span class=\"citation\">Ḥag. I, 1</span> <span dir=\"rtl\">הכל חייבים בר׳ וכ׳</span> all (males) are under obligation to appear in the Temple, except &amp;c. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">הר׳ מעה כסף</span> the pilgrim’s burnt-offering must be worth a m’ʿah of silver (v. <a href=\"#\" data-headword=\"רֵאָיוֹן\">רֵאָיוֹן</a>). <span class=\"citation\">Ib. 7ᵃ</span> (ref. to <a href=\"#\" data-headword=\"רֵאָיוֹן\">ראיון</a>, <span class=\"citation\">Peah I, 1</span>) <span dir=\"rtl\">רְאִיַּית פנים בעזרה</span> it means the appearance in the Temple (has no limits, you may visit the Temple during the festive season as often as you desire); (another opinion) <span dir=\"rtl\">ראיית פנים בקרבן</span> it means the visit connected with a sacrifice (and you must offer a sacrifice as often as you appear); <span class=\"citation\">Y. Peah I, 15ᵃ</span> bot. [read:] <span dir=\"rtl\">מתניתן בר׳ פנים אבל ר׳ קרבן יש לה שיעור</span> the Mishnah in saying that <i>reayon</i> has no limits refers to the number of appearances, but as regards the visit attended with sacrifice, it has a limit (as to the minimum value of the sacrifice). <span class=\"citation\">Ḥag. 6ᵃ</span> <span dir=\"rtl\">עולה … עולת ר׳ הואי</span> the burnt-offering which the Israelites brought in the desert (<span class=\"citation\">Ex. XXIV, 15</span>) was the offering of appearance before God; a. fr.</div>","alt":["רְאִיָּיה"]},"28241":{"h":"רַאֲיָה","r":"T00016","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְאִיָּה\">preced.</a> wds.) <i>evidence, proof</i>. <span class=\"citation\">Eduy. II, 2</span> <span dir=\"rtl\">לא ראינו אין ר׳</span> (Bab. ed. <span dir=\"rtl\">אין לא ראינו ר׳</span>) ‘we have not seen’ is no evidence (that an act did not take place); <span class=\"citation\">Zeb. XII, 4</span>; <span class=\"citation\">Keth. 23ᵃ</span>. <span class=\"citation\">Ib. 15ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">אייתי ר׳ דישראל את</span> produce evidence that thou art an Israelite. <span class=\"citation\">Snh. III, 8</span> <span dir=\"rtl\">כל זמן שמביא ר׳</span>, v. <a href=\"#\" data-headword=\"סָתַר II\"><span dir=\"rtl\">סָתַר</span> II</a>. <span class=\"citation\">B. Kam. III, 11</span>, a. fr. <span dir=\"rtl\">עליו הר׳</span> it rests on him to produce evidence, v. <a href=\"#\" data-headword=\"יָצָא\">יָצָא</a>. <span class=\"citation\">B. Bath. 154ᵃ</span> top <span dir=\"rtl\">ר׳ במאי</span> wherein must his evidence consist? <span dir=\"rtl\">ר׳ בעדים</span> evidence by producing witnesses; <span dir=\"rtl\">ר׳ בקיום השטר</span> evidence by which the document is identified. <span class=\"citation\">Pes. 15ᵃ</span>, a. e. <span dir=\"rtl\">אין הנדון דומה לר׳</span> the case under discussion is not parallel to the evidence (the case which you cite is not analogous). <span class=\"citation\">Ber. 2ᵇ</span>, a. fr. <span dir=\"rtl\">אע&quot;פ שאין ר׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"זֵכֶר\">זֵכֶר</a>; a. v. fr.—Pl. <span dir=\"rtl\">רַאֲיוֹת</span>. Snh. l. c. <span dir=\"rtl\">כל ר׳ שיש לך וכ׳</span> whatever new evidences you may have, you must produce within thirty days. <span class=\"citation\">Y. Shebu. VI, 37ᵃ</span> top <span dir=\"rtl\">בכופר ברַאֲיוֹתָיו̇</span> when the opponent contests his evidence. <span class=\"citation\">Gen. R. s. 36</span>, end, v. <a href=\"#\" data-headword=\"הַכְרָעָה\">הַכְרָעָה</a>; a. e.</div>","alt":["רַאֲיָיה"]},"28242":{"h":"רְאָיָה","r":"T00017","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Reaiah</i>. Tanḥ. Ki Thissa 13 (ref. to <span class=\"citation\">I Chr. IV, 2</span>) <span dir=\"rtl\">ר׳ שהראה וכ׳</span> Bezalel was surnamed Reaiah (v. <a href=\"#\" data-headword=\"רַאֲיָה\">preced.</a></div>","alt":[]},"28243":{"h":"רֵאָיוֹן","r":"T00018","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ראי\">רָאָה</a>, v. <a href=\"#\" data-headword=\"רְאִיָּה\">רְאִיָּה</a>) <i>the appearance in the Temple, pilgrim’s visit</i>; (sub. <span dir=\"rtl\">עולת</span>) <i>the pilgrim’s burnt-offering</i>. <span class=\"citation\">Peah I, 1</span>; Y. ib. 15ᵃ bot.; <span class=\"citation\">Ḥag. 7ᵃ</span>, v. <a href=\"#\" data-headword=\"רְאִיָּה\">רְאִיָּה</a>; a. e.</div>","alt":["רֵיאָיוֹן"]},"28244":{"h":"רְאִיָּיה","r":"T00019","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְאִיָּה\">רְאִיָּה</a>, <a href=\"#\" data-headword=\"רַאֲיָה\"><a href=\"#\" data-headword=\"רַאֲיָה\">רַאֲיָה</a>.</a></div>","alt":["רַאֲיָיה"]},"28245":{"h":"רָאֵים","r":"T00020","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָאִם\">רָאִם</a></div>","alt":[]},"28246":{"h":"רְאֵימָא","r":"T00021","html":"<div class=\"sense\"> ch. = <a href=\"#\" data-headword=\"רְאֵם\">next w.</a> <span class=\"citation\">Targ. Y. Deut. XXXIII, 17</span>. <span class=\"citation\">Targ. O. ib. XIV, 5</span> <span dir=\"rtl\">רימא</span> (Y. <span dir=\"rtl\">רימנין</span>; h. text <a href=\"#\" data-headword=\"דִּישָׁן\">דישן</a>). <span class=\"citation\">Targ. Ps. XXIX, 6</span> בן ר׳ Ms. (ed. <span dir=\"rtl\">בר רֵמַיָּא</span>; ed. Wil. <span dir=\"rtl\">בר רָ׳</span>).—<span class=\"citation\">B. Bath. 73ᵇ</span>; <span class=\"citation\">Zeb. 113ᵇ</span>, v. <a href=\"#\" data-headword=\"אוּרְזִילָא\">אוּרְזִילָא</a></div>","alt":["רֵימָא"]},"28247":{"h":"רְאֵם","r":"T00022","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>r’em, wild-ox</i> (v. Schr. KAT<sup>2</sup>, p. 584). <span class=\"citation\">Gen. R. s. 31</span> <span dir=\"rtl\">ר׳ לא … אבל וכ׳</span> the <i>r’em</i> did not enter (the ark) with him (Noah), but his whelps did; <span class=\"citation\">Yalk. Job 926</span>, v. <a href=\"#\" data-headword=\"גּוּר III\"><span dir=\"rtl\">גּוּר</span> III</a>. <span class=\"citation\">Midr. Till. to Ps. XCII, 11</span> <span dir=\"rtl\">מה ר׳ הזה וכ׳</span> as the <i>r’em</i> has high horns and gores in all directions &amp;c. <span class=\"citation\">Midr. Till. to Ps. XXII</span> <span dir=\"rtl\">מצא את הר׳ ישן וכ׳</span> he (David) found a <i>r.</i> asleep in the desert and thought it was a mountain; <span class=\"citation\">ib.</span> <span dir=\"rtl\">אני … כקרני הר׳ הזה</span> I will build thee a Temple of one hundred cubits, as the horn of this <i>r.</i>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">כיון שראה הר׳ וכ׳</span> when the <i>r.</i> saw the lion, he was afraid and crouched &amp;c.; <span class=\"citation\">Yalk. ib. 688</span>; a. e.—Pl. <span dir=\"rtl\">רְאֵמִים</span>. Ib.</div>","alt":[]},"28248":{"h":"רָאִם","r":"T00023","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"רוּם\">רוּם</a>, <i>to be high</i>. <span class=\"citation\">Targ. Ez. XXXI, 10</span> <span dir=\"rtl\">רָאִימְתָּא</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"רָמָתָא\">רָמְתָּא</a>). Ib. <span dir=\"rtl\">ראים</span>. <span class=\"citation\">Targ. Is. XLIX, 11</span> <span dir=\"rtl\">יראמון</span> ed. Lag. (oth. ed. <span dir=\"rtl\">ירומון</span>). <span class=\"citation\">Ib. LII, 13</span> <span dir=\"rtl\">יראם</span> ed. Lag. (oth. ed. <span dir=\"rtl\">ירום</span>); a. e.—Part. <a href=\"#\" data-headword=\"רָאֵים\">רָאִים</a>. <span class=\"citation\">Targ. Hos. XIII, 6</span>; a. e.</div>","alt":["רָאֵים"]},"28249":{"h":"רָאמָא","r":"T00024","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָאִם\">preced.</a>) <i>height</i>.—Pl. <span dir=\"rtl\">רָאמָן</span>. <span class=\"citation\">Targ. O. Deut. XXXIII, 15</span> ed. Berl. (oth. ed. <span dir=\"rtl\">רָמָן</span>).</div>","alt":[]},"28250":{"h":"רֵאמָנָא","r":"T00025","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵימָנָא\">רֵימָנָא</a></div>","alt":[]},"28251":{"h":"רָאנֵי","r":"T00026","html":"<div class=\"sense\">, part. of <a href=\"#\" data-headword=\"רְנֵי\">רְני</a>.</div>","alt":[]},"28252":{"h":"ראנניות","r":"T00027","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹטְנָנִית\">רוֹטְנָנִית</a></div>","alt":[]},"28253":{"h":"רָאסָן","r":"T00028","html":"<div class=\"sense\"> part. pl. of <a href=\"#\" data-headword=\"רְסֵי\">רְסֵי</a>.</div>","alt":[]},"28254":{"h":"רָאָעָתָא","r":"T00029","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (רוּעַ I) <i>sounding the trumpets</i> at public fasts. Targ. II Esth. IX, 31 ed. Ven., a. Var. ed. Lag. (ed. Lag. <a href=\"#\" data-headword=\"תַּעֲנִיתָא\">תעניתא</a>, oth. ed. <span dir=\"rtl\">צלותהון</span>).</div>","alt":[]},"28255":{"h":"רָאשׁ","r":"T00030","html":"<div class=\"sense\"><i>poor</i>, v. <a href=\"#\" data-headword=\"רָשׁ\">רָשׁ</a>.</div>","alt":[]},"28256":{"h":"רֹאשׁ","r":"T00031","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>head, point; beginning, heading; main thing, principal</i>. <span class=\"citation\">Ḥull. IV, 1</span> <span dir=\"rtl\">הוציא את רֹאשׁוֹ וכ׳</span> if the embryo put forth its head, although it withdrew it again. <span class=\"citation\">Gen. R. s. 71</span>, beg., v. <a href=\"#\" data-headword=\"סוֹף\">סוֹף</a>. <span class=\"citation\">Midr. Prov. to I, 7</span> <span dir=\"rtl\">ר׳ הפרק ר׳ המסכתא ר׳ הפרשה</span> the heading of a chapter, of a treatise, of a section.—<span dir=\"rtl\">ר׳ החדש</span>, <span dir=\"rtl\">ר׳ השנה</span> &amp;c., v. respective determinants.—<span class=\"citation\">Meg. 12ᵇ</span> <span dir=\"rtl\">קופץ בר׳</span>, v. <a href=\"#\" data-headword=\"הֶדְיוֹט\">הֶדְיוֹט</a>.—<span dir=\"rtl\">בת ר׳</span>, v. <a href=\"#\" data-headword=\"בַּת II\"><span dir=\"rtl\">בַּת</span> II</a>.—Sifra B’ḥuck., Par. 2, ch. VIII (ref. to <span dir=\"rtl\">יען וביען</span>, <span class=\"citation\">Lev. XXVI, 43</span>) <span dir=\"rtl\">וכי ר׳ בר׳ פרעתי מהם וכ׳</span> did I collect from them full amount for full amount? did I not collect only one hundredth of their sins before me? <span class=\"citation\">Snh. 3ᵃ</span> sq. <span dir=\"rtl\">ממון שאינו משתלם בר׳ הוא</span> an indemnity not for the exact amount (more or less). <span class=\"citation\">B. Kam. 65ᵇ</span> (ref. to <span class=\"citation\">Lev. V, 24</span>) <span dir=\"rtl\">ממון … בר׳ מוסיף חומש וכ׳</span> where the indemnity is for the full amount (and no more), the fine of a fifth is added, but where it is not for the exact amount (but more) &amp;c.; a. v. fr.—<span dir=\"rtl\">מֵר׳</span> from the beginning, <i>over again</i>. <span class=\"citation\">Ab. Zar. 3ᵃ</span> <span dir=\"rtl\">תנה לנו מר׳ וכ׳</span> give us it (the Law) over again, and we will observe it.—Pl. <span dir=\"rtl\">רָאשִׁים</span>, <span dir=\"rtl\">רָאשִׁין</span>. <span class=\"citation\">Ḥull. II, 2</span> <span dir=\"rtl\">השוחט שני ר׳ כאחד</span> if one cuts two heads at one time. <span class=\"citation\">Ḥag. 13ᵃ</span> <span dir=\"rtl\">רָאשֵׁי פרקים</span>, v. <a href=\"#\" data-headword=\"פֶּרֶק\">פֶּרֶק</a>; a. fr.—Trnsf. <i>a</i>) <i>chief, magistrate, leader, president</i>. <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span> bot. <span dir=\"rtl\">ר׳ גדר היה וכ׳</span> it was the chief magistrate of Gadara &amp;c., v. <a href=\"#\" data-headword=\"רֵאשִׁית\">רֵאשִׁית</a>; Bab. <span class=\"citation\">R. Hash. 22ᵃ</span> שזפר ראשָׁהּ וכ׳ Sh. the chief &amp;c. <span class=\"citation\">Sabb. 33ᵇ</span>; <span class=\"citation\">Ber. 63ᵇ</span>, v. <a href=\"#\" data-headword=\"מְדַבֵּר\">מְדַבֵּר</a>. <span class=\"citation\">Ib. 57ᵇ</span>, v. <a href=\"#\" data-headword=\"יְשִׁיבָה\">יְשִׁיבָה</a>. <span class=\"citation\">Y. Hor. III, 48ᵇ</span> bot. <span dir=\"rtl\">ר׳ משמר</span> the chief of the Temple guard; <span dir=\"rtl\">ר׳ בית אב</span> the chief of a priestly family. Ib. [read:] <span dir=\"rtl\">ר׳ וזקן ר׳ קודם שאינו ר׳ וכ׳</span> as between the chief (the Nasi, of the academy) and an elder (scholar), the chief has the precedence, for none can be chief unless he has been an elder; a. v. fr.—Pl. as ab. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">משה הקדים ר׳ לזקנים</span> Moses placed the chiefs before the elders (<span class=\"citation\">Deut. XXIX, 9</span>). <span class=\"citation\">Gen. R. s. 61</span> <span dir=\"rtl\">כולהון ראשי אומות הן</span> they are all (names derived from) tribal chiefs (v. <a href=\"#\" data-headword=\"לוּפָר\">לוּפָר</a>, a. correct citation acc.); a. fr.—<i>b</i>) <i>crossbeam</i>. <span class=\"citation\">Neg. XIII, 2</span>, v. <a href=\"#\" data-headword=\"פָּתִין\">פָּתִין</a>.—<i>Pl.</i> as ab. Ib. <span dir=\"rtl\">נראה בר׳</span> Bab. ed. (Mish. ed. <i>sing.</i>) if the leprous spot appeared on the crossbeams.—<i>c</i>) <span dir=\"rtl\">ר׳ תּוֹר</span> (Chaldaism) [<i>ox-head</i>,] <i>triangle, wedge</i>. <span class=\"citation\">Kel. XVIII, 2</span> <span dir=\"rtl\">כיצד … ר׳ ת׳</span> how is a piece of furniture with an arched top-piece measured? By drawing an equilateral triangle circumscribing the curve. <span class=\"citation\">Kil. II, 7</span> <span dir=\"rtl\">היה ר׳ ת׳ חטים וכ׳</span> if a triangular point of a wheat field is wedged in a barley field. <span class=\"citation\">Ib. III, 3</span>. <span class=\"citation\">B. Bath. 62ᵃ</span> (if the seller defined the limits of his field by describing one long side and one short side) <span dir=\"rtl\">ויקנה כנגד ר׳ ת׳</span> why not let the buyer have possession of an ‘ox-head’, i.e. draw a trapezoid with the two unequal sides?—<i>Pl.</i> <span dir=\"rtl\">רָאשֵׁי תוֹרִין</span>. <span class=\"citation\">Y. Erub. I, 19ᶜ</span> bot.</div>","alt":[]},"28257":{"h":"רֹאשׁ ²","r":"T00032","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"רֵישׁ II\"><span dir=\"rtl\">רֵישׁ</span> II</a></div>","alt":["רֵאשָׁא","רֵאשָׁה"]},"28258":{"h":"רִאשׁוֹן","r":"T00033","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רֹאשׁ ²\">preced.</a>) <i>first</i>. <span dir=\"rtl\">ר׳ ר׳</span> <i>one after the other</i>. <span class=\"citation\">R. Hash. 17ᵃ</span>, v. <a href=\"#\" data-headword=\"עָבַר\">עָבַר</a>; a. fr.—<span class=\"citation\">Gitt. V, 8</span> <span dir=\"rtl\">כהן קורא ר׳ וכ׳</span> a priest reads (from the Torah) the first, and after him &amp;c. <span class=\"citation\">Ib. 59ᵇ</span> <span dir=\"rtl\">לפתוח ר׳ ולברך ר׳ וליטול … ר׳</span> to be the first in opening a meeting, the first in saying the blessing &amp;c., v. <a href=\"#\" data-headword=\"מָנָה I\"><span dir=\"rtl\">מָנָה</span> I</a>; a. v. fr.—Esp. <i>a</i>) <a href=\"#\" data-headword=\"ר׳\">ר׳</a> (or <span dir=\"rtl\">ר׳ לטומאה</span>) <i>first degree of uncleanness, original cause of uncleanness</i>. <span class=\"citation\">Toh. II, 2</span> <span dir=\"rtl\">האוכל אוכל ר׳ ר׳</span> he who eats food of the first degree of uncleanness becomes himself unclean in the first degree. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">הר׳ שבחולין טמא ומטמא</span> secular food of the first degree of uncleanness is unclean and makes unclean. <span class=\"citation\">Ib. 4</span>; a. v. fr.—<i>b</i>) <a href=\"#\" data-headword=\"ר׳\">ר׳</a> <i>the person with whom a relationship begins, direct relative</i> (brothers with reference to their respective issues). <span class=\"citation\">Snh. 28ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"שֵׁנִי\">שֵׁנִי</a>.—<i>c</i>) <a href=\"#\" data-headword=\"ר׳\">ר׳</a> (<a href=\"#\" data-headword=\"כלי\">כלי</a>) <i>a vessel direct from the fire</i>. <span class=\"citation\">Ḥull. 104ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"רִאשׁוֹנִי\">רִאשׁוֹנִים</a>. <span class=\"citation\">Yoma III, 11</span> <span dir=\"rtl\">על הר׳ נאמר וכ׳</span> to the former was applied the verse &amp;c. <span class=\"citation\">Sabb. 112ᵇ</span> <span dir=\"rtl\">אם ר׳ בני וכ׳</span> if those before us were sons of angels, we are sons of men, and if those before us were sons of men, we are &amp;c. <span class=\"citation\">Ib. 56ᵇ</span> <span dir=\"rtl\">מקיש ר׳ לאחרונים</span> the Scriptural text compares the predecessors to the successors. <span class=\"citation\">Erub. 64ᵇ</span> <span dir=\"rtl\">דורות הר׳</span> the earlier generations; a. fr.—<i>Fem</i>. <span dir=\"rtl\">רִאשׁוֹנָה</span>. <span class=\"citation\">Ned. 91ᵃ</span>, v. <a href=\"#\" data-headword=\"מִשְׁנָה\">מִשְׁנָה</a>. <span class=\"citation\">Keth. 82ᵇ</span> <span dir=\"rtl\">בר׳</span> in former days, originally. <span class=\"citation\">Ned. XI, 12</span> <span dir=\"rtl\">בר׳ היו אומרים וכ׳</span> originally the law was that &amp;c.; a. fr.—[Y. Taan. II, 65ᵃ top <span dir=\"rtl\">בדִאשׁוֹנָהּ</span> on its (the year’s) first day (<span class=\"citation\">R. Hash. 16ᵇ</span> <span dir=\"rtl\">בתחילתה</span>).]—Pl. <a href=\"#\" data-headword=\"רִאשׁוֹנִי\">רִאשׁוֹנוֹת</a>. <span class=\"citation\">Ber. 13ᵃ</span> <span dir=\"rtl\">משכחות את הר׳</span>, v. <a href=\"#\" data-headword=\"צָרָה II\"><span dir=\"rtl\">צָרָה</span> II</a>. <span class=\"citation\">Ib. 34ᵃ</span> <a href=\"#\" data-headword=\"ר׳\">ר׳</a> (<a href=\"#\" data-headword=\"שָׁלַשׁ\">שלש</a>) the first three sections of the Prayer of Benedictions. <span class=\"citation\">B. Kam. 54ᵇ</span>, v. <a href=\"#\" data-headword=\"דִּיבֵּר\">דִּיבַּר</a>; a. v. fr.</div>","alt":[]},"28259":{"h":"רִאשׁוֹנִי","r":"T00034","html":"<div class=\"sense\"> f. (b. h. <span dir=\"rtl\">רִאשֹׁנִ׳</span>) same. <span class=\"citation\">Pesik. R. s. 44</span> <span dir=\"rtl\">עשה את האחרונית ר׳</span> (not <span dir=\"rtl\">האחרונים</span>) make what thou hast threatened as the last punishment the first; (<span class=\"citation\">Yalk. Hos. 531</span> <span dir=\"rtl\">אחרונה ראשונה</span>).</div>","alt":["רִאשׁוֹנִית"]},"28260":{"h":"רַאֲשׁוֹת","r":"T00035","html":"<div class=\"sense\"> f. pl. = <a href=\"#\" data-headword=\"מְרַאֲשׁוֹת\">מְרַאֲשׁוֹת</a>. Tanḥ. B’midb. 9 <span dir=\"rtl\">כדי … ממרגלותיו ויתנה ברַאֲשׁוֹתָיו</span> the distance covered in taking a thing from the bottom of a bed to its top-side; (Tanḥ. ed. Bub. <span dir=\"rtl\">ויתננה במראשותיו</span>).</div>","alt":[]},"28261":{"h":"רֵאשִׁית","r":"T00036","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>beginning; firstling, first gift</i>.—<span dir=\"rtl\">בר׳</span>, v. <a href=\"#\" data-headword=\"בְּרֵאשִׁית\">בְּרֵאשִׁית</a>.—<span class=\"citation\">Ḥull. XI, 1</span>, a. e., v. <a href=\"#\" data-headword=\"גֵּז\">גֵּז</a>. <span class=\"citation\">Ib. 136ᵇ</span> <span dir=\"rtl\">ר׳ ששיריה ניכרין</span> a first gift the remainder of which is distinguishable (not the entire mass); <span class=\"citation\">ib.</span> <span dir=\"rtl\">כל גזיי ר׳</span> all my shorn wool be dedicated as priest’s gift; a. e.</div><div class=\"sense\"><b>—2)</b> <i>magistracy, office</i>. Y. R. Hash. I, 57ᵇ bot. <span dir=\"rtl\">והעכירו מרֵאשִׁיתוֹ</span> he removed him (the chief magistrate of Gadara) from his office; (Bab. <span class=\"citation\">ib. 22ᵃ</span> <span dir=\"rtl\">מגדולתו</span>).</div>","alt":[]},"28262":{"h":"רֵאשִׁיתָא","r":"T00037","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵישִׁיתָא\">רֵישִׁיתָא</a></div>","alt":[]},"28263":{"h":"רֵאשָׁנָא","r":"T00038","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָשָׁאנָא\">רָשָׁאנָא</a></div>","alt":[]},"28264":{"h":"רַאֲתָן","r":"T00039","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ראת</span> = <span dir=\"rtl\">רתת</span>) [<i>nervous trembling</i>,] <i>a certain skin disease attended with extreme weakness</i>. <span class=\"citation\">Gen. R. s. 41</span>, beg. (ref. to <span class=\"citation\">Gen. XII, 17</span>) <span dir=\"rtl\">פרעה בר׳ לקה</span> Pharaoh was smitten with <i>raăthan</i>. Ib. <span dir=\"rtl\">כ&quot;ד מיני … אלא ר׳ בלבד</span> there are twenty-four kinds of skin diseases, but there is none for which connection with woman is bad, except <i>raăthan</i>; <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span>.—בעל ר׳ <i>one afflicted with raăthan</i>. Bab. <span class=\"citation\">Keth. 77ᵇ</span>; <span class=\"citation\">Tosef. ib. VII, 11</span>; a. fr.</div>","alt":[]},"28265":{"h":"רַב I","r":"T00040","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>large, great; much</i>. <span class=\"citation\">Y. Yeb. XII, 12ᶜ</span> bot. (in Chald. dict.) <span dir=\"rtl\">לא הוה לבן רב וכ׳</span> they would not have dared to do so. <span class=\"citation\">Ber. 62ᵇ</span> (ref. to <span class=\"citation\">II Sam. XXIV, 16</span>) the Lord said to the angel, <span dir=\"rtl\">טול לי רב שבהם וכ׳</span> take me the greatest of them in whom there is (merit enough) with which to pay their debts (sins); a. e.—Pl. <a href=\"#\" data-headword=\"רַבִּי\">רַבִּים</a>, <a href=\"#\" data-headword=\"רַבִּין\">רַבִּין</a>. <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">ר׳ שתו ר׳ ישתו</span> many have drunk (the cup of mourning), many shall drink. <span class=\"citation\">Yeb. 63ᵇ</span> (from Ben Sira) <span dir=\"rtl\">מנע ר׳ מתיך וכ׳</span> keep the many off thy house, nor bring every body to thy house. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ יהיו דורשי וכ׳</span> let thy well-wishers be many, but reveal a secret to one out of a thousand. <span class=\"citation\">Ab. Zar. 43ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">ר׳ שאני</span> where several people meet to pray, it is different. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שכיחי ר׳ גביה</span> many people are usually with him. <span class=\"citation\">Ber. 9ᵃ</span>, a. fr. <span dir=\"rtl\">יחיד ור׳</span>, v. <a href=\"#\" data-headword=\"יָחִיד\">יָחִיד</a>; a. fr.—Esp. <a href=\"#\" data-headword=\"רַבִּי\">רַבִּים</a> <i>community, public</i>. <span class=\"citation\">Y. Meg. III, 73ᵈ</span> <span dir=\"rtl\">בה&quot;כ של ר׳</span> a synagogue belonging to a community, opp. <span dir=\"rtl\">של יחיד</span>. Bab. <span class=\"citation\">Meg. 28ᵇ</span> <span dir=\"rtl\">הספד של ר׳</span> funeral ceremonies in a case of public mourning (for a public man), opp. <span dir=\"rtl\">של יחיד</span>. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">צריך … לר׳ ור׳ וכ׳</span> should make his trouble known to the people, and the people will pray for him. <span class=\"citation\">Ab. V, 18</span>. <span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">תפלתן של ר׳</span> congregational prayer; a. v. fr.—בָּרַ׳ <i>in public</i>. <span class=\"citation\">Ib. 61ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"קָהַל\">קָהַל</a>. <span class=\"citation\">B. Mets. 58ᵇ</span>, v. <a href=\"#\" data-headword=\"לָבָן II\"><span dir=\"rtl\">לָבָן</span> II</a>; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"רַבָּה I\">רַבָּה</a>. <span class=\"citation\">Gen. R. s. 33</span> (ref. to <span class=\"citation\">Ps. XXXVI, 7</span>) <span dir=\"rtl\">את מדקדק … עד תהום ר׳</span> thou dealest strictly with them (the wicked) (searching their doings) ‘to the great deep’; a. fr.—[Ib. s. 27, v. <a href=\"#\" data-headword=\"רָבַב\">רָבַב</a>.]—Pl. <span dir=\"rtl\">רַבּוֹת</span>. <span class=\"citation\">Ḥag. 5ᵃ</span> (ref. to <span class=\"citation\">Deut. XXXI, 21</span>) <span dir=\"rtl\">צרות ר׳ ורעות</span> Ms. M. many troubles and evils, v. <a href=\"#\" data-headword=\"מָצָא\">מָצָא</a>; a. e.—[<span dir=\"rtl\">מדרש רַבּיֹת</span>, v. <a href=\"#\" data-headword=\"מִדְרָשׁ\">מִדְרָשׁ</a>.]</div>","alt":[]},"28266":{"h":"רַב II","r":"T00041","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַב I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>superior, master</i>. <span class=\"citation\">Gitt. 23ᵇ</span> <span dir=\"rtl\">העבד … רַבּוֹ של חבירו אבל לא מיד רַבּוֹ שלו</span> a slave may receive a deed of manumission in behalf of a fellow slave at the hand of his fellow’s master, but not at the hands of his own master (if both slaves belong to the same master). <span class=\"citation\">Ab. I, 3</span>, v. <a href=\"#\" data-headword=\"עֶבֶד\">עֶבֶד</a>. <span class=\"citation\">Ḥag. 5ᵃ</span>, v. <a href=\"#\" data-headword=\"מָצָא\">מָצָא</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>teacher</i>. <span class=\"citation\">Ber. 63ᵇ</span> <span dir=\"rtl\">יאמרו הרב בכעס וכ׳</span> they will say, the teacher (the Lord) is angry, and the disciple (Moses) is angry, what is to become of Israel? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל תלמיד … רבו וכ׳</span> a student with whom his teacher is angry for the first time, and who keeps silence. <span class=\"citation\">Eduy. I, 3</span>, v. <a href=\"#\" data-headword=\"לָשׁוֹן\">לָשׁוֹן</a>. <span class=\"citation\">Ab. I, 16</span> <span dir=\"rtl\">עשה לך רב וכ׳</span> get thyself a teacher, and be relieved of doubt. <span class=\"citation\">R. Hash. II, 9</span> <span dir=\"rtl\">רַבִּי ותלמידי רבי וכ׳</span> my teacher and my pupil; my teacher in wisdom &amp;c.; v. <a href=\"#\" data-headword=\"רַבִּי\">רַבִּי</a>.—<span class=\"citation\">M. Kat. 9ᵃ</span>, a. fr. <span dir=\"rtl\">למדתנו רַבֵּינוּ</span> thou, our teacher, hast taught us; v. <a href=\"#\" data-headword=\"רַבֵּנוּ\">רַבֵּנוּ</a>; a. v. fr.—Esp. <a href=\"#\" data-headword=\"רַב\">רַב</a> <i>Rab, a</i>) title of the Babylonian Amoraim. <span class=\"citation\">Pes. 52ᵇ</span>; a. v. fr.—<span dir=\"rtl\">בי רב</span> the school of, v. <a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>.—<i>b</i>) surname of Abba Arekha, the founder of the academy of Sura in Babylonia (v. Graetz, Gesch. d. Jud.<sup>1</sup> IV, p. 312, sq.; Fr. M’bo, p. 122ᵇ). <span class=\"citation\">Ḥull. 95ᵇ</span> <span dir=\"rtl\">כולהו שני דרב וכ׳</span> as long as Rab lived, R. Joḥ. addressed his letters to Babylonia, ‘to our teacher in Babylonia.’ <span class=\"citation\">Ab. Zar. 10ᵇ</span> אדרכן שמשיה לרב A. (a Parthian ruler) attended (associated with) Rab. <span class=\"citation\">Y. Peah VI, 19ᶜ</span> <span dir=\"rtl\">רב כד נחת לתמן</span> when Rab came down to Babylonia. <span class=\"citation\">Erub. 50ᵇ</span>, a. fr. <span dir=\"rtl\">רב תנא הוא ופליג</span> Rab is a Tannai and has a right to differ (with other Tannaim). <span class=\"citation\">Nidd. 24ᵇ</span>, a. fr. <span dir=\"rtl\">הלכתא כרב וכ׳</span>, v. <a href=\"#\" data-headword=\"אִיסּוּרָא\">אִיסּוּרָא</a>; a. v. fr.—<span dir=\"rtl\">ספרא דבי רב</span>, <span dir=\"rtl\">ספרי דבי רב</span>, v. <a href=\"#\" data-headword=\"סִפְרָא\">סִפְרָא</a>.—Pl. <span dir=\"rtl\">רַבּוֹת</span> (only with suffix). <span class=\"citation\">Taan. 7ᵃ</span>, a. e. <span dir=\"rtl\">מרַבּוֹתַי</span>, v. <a href=\"#\" data-headword=\"לָמֵד I\">לָמַד</a>. <span class=\"citation\">Shebu. 47ᵃ</span> רַבּוֹתֵינוּ שבבבל וכ׳ ‘our teachers in Babylonia’ means Rab and Samuel. <span class=\"citation\">Y. Gitt. VII, 48ᵈ</span> top <span dir=\"rtl\">ורבותינו אמרו</span> and our teachers said; <span dir=\"rtl\">מנו רבותינו וכ׳</span> who are meant by ‘our teachers’? Ib., a. e. <span dir=\"rtl\">בשלשה … רבותיני</span> on three occasions R. Judah (with his court) is quoted as ‘our teachers.’ <span class=\"citation\">Y. Sabb. V, end, 7ᶜ</span> <span dir=\"rtl\">רבותינו שבגולה</span> our teachers in the diaspora (Babylonia, v. supra); <span class=\"citation\">Y. Bets. II, 61ᶜ</span> bot. <span class=\"citation\">Y. Meg. I, 70ᵈ</span> <span dir=\"rtl\">כתבו אגרת ושלחו לרבותינו שהן וכ׳</span> they (Mordecai and Esther) wrote a letter addressed ‘to our teachers (in Palestine) that be’, saying to them &amp;c.; a. fr.—<i>Fem.</i> רַבָּה <i>mistress</i>. <span class=\"citation\">Ruth R. to II, 5</span> <span dir=\"rtl\">רַבָּתָהּ וכ׳</span> her mistress (Naomi) &amp;c., v. <a href=\"#\" data-headword=\"רָפָה\">רָפָה</a>.</div>","alt":[]},"28267":{"h":"רַב","r":"T00042","html":"<div class=\"sense\"><b>1)</b> <i>large, great, numerous; senior</i>. <span class=\"citation\">Targ. Josh. XXII, 10</span>. <span class=\"citation\">Targ. Y. Deut. I, 28</span>. <span class=\"citation\">Targ. Gen. I, 16</span>. <span class=\"citation\">Ib. X, 21</span> (Y. ed. Vien. <a href=\"#\" data-headword=\"רַבָּה I\">רַבָּה</a>); a. fr.—[In Talmudic literature mostly <a href=\"#\" data-headword=\"רַבָּה I\">רַבָּה</a>, q. v.]</div><div class=\"sense\"><b>—2)</b> <i>chief, master, teacher</i>. <span class=\"citation\">Targ. I Sam. XXII, 14</span> (h. text <a href=\"#\" data-headword=\"סָר\">סָר</a>). <span class=\"citation\">Targ. Gen. XXXVII, 36</span> (Y. II <a href=\"#\" data-headword=\"שַׁלִּיט ²\">שליטא</a>; h. text <a href=\"#\" data-headword=\"סָרִיס\">סריס</a>). Ib. (h. text <a href=\"#\" data-headword=\"שַׂר\">שַׂר</a>). Ib. IV, 20, sq. <span class=\"citation\">Targ. Job III, 18</span> <span dir=\"rtl\">ינקי בית ר׳</span> school children; a. fr.—<span class=\"citation\">Targ. I Chr. XI, 22</span>, v. <a href=\"#\" data-headword=\"סִפְרָא\">סִפְרָא</a>.—<span class=\"citation\">R. Hash. 31ᵇ</span> <span dir=\"rtl\">לאו אירח … לרַבֵּיה רַבָּךְ</span> it is not customary to say to one’s own teacher, ‘thy teacher’ (has said &amp;c.). <span class=\"citation\">Ab. Zar. 17ᵇ</span> <span dir=\"rtl\">רַבָּן של וכ׳</span>, v. <a href=\"#\" data-headword=\"רַבִּי\">רַבִּי</a>; a. fr.—בֵּי רַב <i>school, academy</i>. <span class=\"citation\">Snh. 33ᵇ</span>, a. e. <span dir=\"rtl\">זיל קרי בי רב הוא</span> this is a case when you may say, ‘go and learn it (in the Bible) at school’, i.e. an erroneous judgment of such a nature must be reversed. <span class=\"citation\">Erub. 22ᵃ</span> <span dir=\"rtl\">הוה קאזיל לבי רב</span> left home in order to study; a. fr.—V. <a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>.—<i>Fem.</i> <a href=\"#\" data-headword=\"רַב\">רַבָּא</a>, <a href=\"#\" data-headword=\"רַבְּתָא\">רַבְּתָא</a>, <a href=\"#\" data-headword=\"רַבְּתָא\">רַבְּתָה</a>. <span class=\"citation\">Targ. Jer. XLVIII, 34</span>. <span class=\"citation\">Targ. Gen. XXVII, 34</span>. <span class=\"citation\">Ib. XIX, 31</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"רַבְּתָא\">רַבָּתָא</a>, <a href=\"#\" data-headword=\"רַבְּתָא\">רַבָּתָה</a>. <span class=\"citation\">Y. Snh. X, 29ᵃ</span> top <span dir=\"rtl\">אתה עבדת ר׳ וכ׳</span> (not <span dir=\"rtl\">עברת</span>) thou (Doeg) hast done great things, turn thou around &amp;c.—V. <a href=\"#\" data-headword=\"רַבְּתָא\">רַבְּתָא</a>.</div>","alt":["רַבָּא"]},"28268":{"h":"רְבָא","r":"T00043","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*רְבֵי\">רְבֵי</a></div>","alt":[]},"28269":{"h":"רָבָא","r":"T00044","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (= <span dir=\"rtl\">רב בא</span>) <i>Raba</i> (bar Joseph), a Babylonian Amora, chief of the academy of Maḥoza (v. Graetz, Gesch. d. Jud.<sup>1</sup> IV, p. 414 sq.). <span class=\"citation\">Keth. 105ᵇ</span>. <span class=\"citation\">B. Bath. 159ᵇ</span>, v. <a href=\"#\" data-headword=\"אַדְּ־\">אַדְּ־</a>; a. v. fr.—[<span class=\"citation\">Y. Bets. I, 60ᵇ</span> <span dir=\"rtl\">ר׳ אבא בר יוסף</span>.]—[<span class=\"citation\">Y. Yeb. IV, 6ᵃ</span> <span dir=\"rtl\">אמר רבא</span>, read: <span dir=\"rtl\">ר׳ בא</span>.]</div>","alt":["(רַבָּא)"]},"28270":{"h":"רִבָא","r":"T00045","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"רַבְּתָא\">רִבָתָא</a>, v. <a href=\"#\" data-headword=\"רִיבָא\">רִיבָא</a>.</div>","alt":[]},"28271":{"h":"רָבַב","r":"T00046","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to be great, numerous</i>. <span class=\"citation\">M. Kat. 28ᵇ</span> <span dir=\"rtl\">רַבּוּ עונותיו</span> many are his sins. <span class=\"citation\">Gen. R. s. 27</span> (expl. <a href=\"#\" data-headword=\"רַבָּה I\">רבה</a>, <span class=\"citation\">Gen. VI, 5</span>) <span dir=\"rtl\">רַבָּה והולכת</span> was growing more and more; a. e.—Denom. <a href=\"#\" data-headword=\"רַב\">רַב</a>.</div><div class=\"sense\"><b>—2)</b> <i>to line</i>, v. infra.</div><div class=\"sense\"><b>Pi. רִיבֵּב</b> <div class=\"sense\"> [<i>to make strong, thick</i>,] <i>to line</i>. Pesik. Zuṭr. Haăz., ed. Bub. p. 110 <span dir=\"rtl\">שמְרַבֶּבֶת</span>, v. <a href=\"#\" data-headword=\"רָבִיב\">רָבִיב</a>.—Esp. <i>to line a skin with pitch</i> (v. <a href=\"#\" data-headword=\"חֵמֶת\">חֵמֶת</a>). <span class=\"citation\">Ab. Zar. 33ᵃ</span> <span dir=\"rtl\">נכרי רִיבְּבָן … וישראל נותן וכ׳</span> if a gentile pitched them and tanned them, and an Israelite puts wine into them; <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">V), 10</span> <span dir=\"rtl\">גוי עובדו וזופתו</span> ed. Zuck. (Var. <span dir=\"rtl\">ורוֹבְבוֹ</span>, <span dir=\"rtl\">ורובבין</span>, <span dir=\"rtl\">ורובדו</span>, v. ed. Zuck. note); Y. ib. II, 41ᵇ bot. <span dir=\"rtl\">עובדן ודיבבן</span>, v. <a href=\"#\" data-headword=\"דָּבַב I\"><span dir=\"rtl\">דָּבַב</span> I</a>.—[<span class=\"citation\">Yalk. Cant. 988</span> <span dir=\"rtl\">צפונית מרבבת</span>, some ed. <span dir=\"rtl\">מרכבת</span>, read: <span dir=\"rtl\">מְכַבֶּדֶת</span>, as <span class=\"citation\">Num. R. s. 13</span>.]</div></div>","alt":[]},"28272":{"h":"רְבַב","r":"T00047","html":"<div class=\"sense\">, <i>to be great</i>, esp. <i>to be a teacher, be in office</i>. <span class=\"citation\">Y. M. Kat. III, 83ᵇ</span> top <span dir=\"rtl\">כגון אנן דרַבְבִינָן משגחין וכ׳</span> such as we, who are teachers: people look up to us to answer their questions; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ואנן אפי׳ רבבינן וכ׳</span></div>","alt":[]},"28273":{"h":"רָבָב","r":"T00048","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָבַב\">רָבַב</a><i>Pi.</i>) <i>a thick, viscid mass, fat; grease, pitch</i> &amp;c. <span class=\"citation\">Sot. 49ᵃ</span> <span dir=\"rtl\">אילמלא … מוכרי ר׳</span> but for David’s prayer, all Israelites would be sellers of grease. <span class=\"citation\">Zeb. 98ᵇ</span> <span dir=\"rtl\">ר׳ על בגדו וכ׳</span> grease on a garment is an unlawful interposition (at its immersion), but if he is a seller of grease &amp;c. <span class=\"citation\">Sabb. 20ᵇ</span> <span dir=\"rtl\">של ר׳</span> (<a href=\"#\" data-headword=\"מְדוּרָה\">מדורה</a>) a fire made with fatty substances. <span class=\"citation\">Ib. 78ᵇ</span> <span dir=\"rtl\">ר׳ כדי לסוך וכ׳</span> fat, as much as is required to smear under a small cake. <span class=\"citation\">Ib. 114ᵃ</span> <span dir=\"rtl\">כל ת&quot;ח שנמצא ר׳ וכ׳</span> a scholar on whose garment there is a greasy stain &amp;c.; Rabina said, <span dir=\"rtl\">רבד איתמר</span> the word <i>rabad</i> was used (by R. Joḥanan), v. <a href=\"#\" data-headword=\"רָבָד\">רָבָד</a>.</div>","alt":[]},"28274":{"h":"רַבְבָּא","r":"T00049","html":"<div class=\"sense\"> = <span dir=\"rtl\">רַבִּי אַבָּא</span>. <span class=\"citation\">Ḥull. 93ᵃ</span> Ms. R. 2 (v. Rabb. D. S. a. l. notes 4, 6, 7); a. e.—Cmp. <a href=\"#\" data-headword=\"רָבָא\">רָבָא</a>.</div>","alt":[]},"28275":{"h":"רְבָבָה","r":"T00050","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>large quantity, myriad</i>. <span class=\"citation\">Gen. R. s. 60</span> (ref. to <span class=\"citation\">Gen. XXIV, 60</span>) <span dir=\"rtl\">ועמדו … ור׳ מיעקב</span> from her (Rebekah) arose chiefs (<i>allufim</i>) of Esau, and myriads of Jacob; a. e.—Pl. <span dir=\"rtl\">רְבָבוֹת</span>, constr. <a href=\"#\" data-headword=\"רִבֵּי\">רִבֵּי</a>, <a href=\"#\" data-headword=\"רִבֵּי\">רִיבֵּי</a>. <span class=\"citation\">Gen. R. s. 89</span> (play on <span dir=\"rtl\">ר̇ה̇ב̇ים</span>, <span class=\"citation\">Ps. XL, 5</span>) <span dir=\"rtl\">ה̇מון ר̇יב̇י רַבְרְבַיָּא שהם וכ׳</span> (he regarded not) the noise of the myriads of great (boastful) men, for they turn after lies (v., however, <a href=\"#\" data-headword=\"רַבְרְבָא\">רַבְרְבָא</a>).—V. <a href=\"#\" data-headword=\"רִבּוֹא\">רִבּוֹא</a>.</div>","alt":[]},"28276":{"h":"רַבְבָּהוּ","r":"T00051","html":"<div class=\"sense\"> = <span dir=\"rtl\"><span dir=\"rtl\">רַב אַבָּהוּ</span> (רַבִּי</span>). <span class=\"citation\">Snh. 22ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">ר׳ א׳</span>). <span class=\"citation\">Pes. 56ᵃ</span> רב בהו Ms. M. (v. Rabb. D. S. a. l. note 1; ed. <span dir=\"rtl\">ר׳ א׳</span>).</div>","alt":[]},"28277":{"h":"רִבְבוּתָא","r":"T00052","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבְבַת\">next w.</a></div>","alt":[]},"28278":{"h":"רִבְבַת","r":"T00053","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רְבָבָה\">רְבָבָה</a>. <span class=\"citation\">Targ. Ez. XVI, 7</span> (ed. Lag. <span dir=\"rtl\">רבוות</span>). <span class=\"citation\">Targ. I Chr. XXIX, 7</span> (ed. Rahm. <span dir=\"rtl\">ריבב׳</span>); a. e.—Pl. <a href=\"#\" data-headword=\"רִבְבַת\">רִבְבָתָא</a>, <a href=\"#\" data-headword=\"רִבְוָון\">רִבְוָו׳</a>, <span dir=\"rtl\">רִבְוָ׳</span>, <span dir=\"rtl\">רִבְבָן</span>, <a href=\"#\" data-headword=\"רִבְוָן\">רִבְוָן</a>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Targ. Ps. XCI, 7</span> (ed. Wil. <a href=\"#\" data-headword=\"רִבְבוּתָא\">רִבְבוּתָא</a>; ed. Lag. <span dir=\"rtl\">ריבבותא</span>). II. CXLIV, 13. <span class=\"citation\">Targ. I Sam. XVIII, 7</span>, sq.; a. e.</div>","alt":["רִבַבְתָּא","רִבְוָות","רְבַוְותָּא","רִי׳"]},"28279":{"h":"רָבַג","r":"T00054","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">רָבַךְ</span>) <i>to pile up promiscuously</i>, opp. to <span dir=\"rtl\">ערך</span> to arrange. Sifra Vayikra, N’dab, ch. IV, Par. 4 <span dir=\"rtl\">יכול … ורוֹבֵג</span> lest you think that he may cast (the pieces of flesh on the altar) and pile them up; <span class=\"citation\">Tosef. Zeb. IV, 2</span> <span dir=\"rtl\">ודובק</span> (read: <span dir=\"rtl\">ורוֹבֵק</span>; Var. <span dir=\"rtl\">ורובץ</span>).</div>","alt":[]},"28280":{"h":"*רָבַד","r":"T00055","html":"<div class=\"sense\"> (b. h.) [<i>to strengthen</i>,] <i>to line, join, patch</i>. <span class=\"citation\">Tosef. Ab. Zar. IV</span> (<span class=\"citation\">V), 10</span> Var. <span dir=\"rtl\">ורוֹבְדוֹ</span> and patches it; v. <a href=\"#\" data-headword=\"רָבַב\">רָבַב</a>.</div>","alt":[]},"28281":{"h":"רָבָד","r":"T00056","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*רָבַד\">preced.</a>) <i>a thick patch</i>. <span class=\"citation\">Sabb. 114ᵃ</span>, v. <a href=\"#\" data-headword=\"רָבָב\">רָבָב</a>; (cmp. ib. <span dir=\"rtl\">טלאי ע&quot;ג טלאי</span>); [Rashi: <i>a stain of semen</i> (?)]</div>","alt":[]},"28282":{"h":"רִבְדָּא","r":"T00057","html":"<div class=\"sense\">, <i>patch</i>; trnsf. (cmp. <a href=\"#\" data-headword=\"נָאָתָא\">נָאָתָא</a>) <i>cicatrix, scab</i>; <span dir=\"rtl\">ר׳ דכוסילתא</span> the scab or scar over the puncture made by bleeding, v. <a href=\"#\" data-headword=\"כּוֹסֵילְתָּא\">כּוֹסִילְתָּא</a>; also <i>the puncture</i>. <span class=\"citation\">Snh. 93ᵇ</span> <span dir=\"rtl\">אפי׳ כר׳ דכ׳ וכ׳</span> no imperfection, even so much as the mark of bleeding, was on their bodies. <span class=\"citation\">Keth. 39ᵇ</span> (Var. in Rashi a. Ar. <span dir=\"rtl\">תרפתא דסיבורי</span> or <span dir=\"rtl\">דסיכורי</span>), v. <a href=\"#\" data-headword=\"כּוֹסֵילְתָּא\">כּוֹסִילְתָּא</a>.</div>","alt":["רִי׳"]},"28283":{"h":"רָבָה","r":"T00058","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רבי\">רבי</a></div>","alt":[]},"28284":{"h":"רָבֶה","r":"T00059","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  (= <a href=\"#\" data-headword=\"רָוָה\">רָוָה</a>) <i>moist, saturated with liquid</i>, opp. <a href=\"#\" data-headword=\"עָבָה I\">עבה</a> thick and pulpy. <span class=\"citation\">Y. Pes. X, 37ᵈ</span> top <span dir=\"rtl\">צריכה שתהא ר׳ וכ׳</span> (not <span dir=\"rtl\">צבריה</span>) it (the <a href=\"#\" data-headword=\"חֲרוֹסֶת\">חֲרוֹסֶת</a>) must be saturated (with wine), which means that it is to remind of blood.—V. <a href=\"#\" data-headword=\"רוֹבֶה II\"><span dir=\"rtl\">רוֹבֶה</span> II</a>.</div><div class=\"sense\"><b>—2)</b>  pers. of <a href=\"#\" data-headword=\"רָבָה\">רָבָה</a>, v. <a href=\"#\" data-headword=\"רבי\">רבי</a></div>","alt":["רָבָה"]},"28285":{"h":"רַבָּה I","r":"T00060","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"רַב\">רַבָּא</a> </div><div class=\"sense\"><b>1)</b> <i>large, great; senior</i>. <span dir=\"rtl\">בִּדְרַ׳ מיניה</span>, v. <a href=\"#\" data-headword=\"קִים\">קִים</a>.—<span dir=\"rtl\">אַדְּרַ׳</span>, v. <a href=\"#\" data-headword=\"אַדְּרַבָּא\">אַדְּרַבָּא</a>.—<span class=\"citation\">Y. Shebi. VII, end. 37ᶜ</span> <span dir=\"rtl\">ודמיא היא כל ר׳</span> is this case altogether the same?; <span class=\"citation\">Y. Orl. I, 61ᵇ</span> bot. <span dir=\"rtl\">ורמיה היא לכל רביה</span> (corr. acc.).—<span dir=\"rtl\">דְּרַבָּה</span>, v. <a href=\"#\" data-headword=\"רוּבָּה II\"><span dir=\"rtl\">רוּבָּה</span> II</a>.—<span class=\"citation\">Midr. Till. to Ps. XVII</span> (ref. to <a href=\"#\" data-headword=\"רַב\">רב</a>, <span class=\"citation\">II Sam. XXIV, 16</span>) <span dir=\"rtl\">ר׳ הוא משכונא גבך</span> ed. Bub. (oth. ed. <span dir=\"rtl\">ר׳ היא משכונתך</span>, corr. acc.) the pledge thou hast taken (with the death of Abishai) is large enough. <span class=\"citation\">Ber. 19ᵇ</span> <span dir=\"rtl\">גברא ר׳ אמר וכ׳</span> a great man (scholar) has said something, laugh not at it; <span class=\"citation\">Gitt. 55ᵇ</span>; <span class=\"citation\">Nidd. 50ᵇ</span>. <span class=\"citation\">Sabb. 59ᵇ</span> <span dir=\"rtl\">גברא ר׳ וכ׳</span> (some ed. <a href=\"#\" data-headword=\"רְבֵי\">רבא</a>), v. <a href=\"#\" data-headword=\"אָרֵיכָא\">אָרֵיכָא</a>; <span class=\"citation\">Keth. 103ᵇ</span>. <span class=\"citation\">Yeb. 21ᵇ</span> הא … מגברא ר׳ וכ׳ I have heard this from a great scholar. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אבא ר׳</span> grandfather. <span class=\"citation\">Gen. R. s. 1</span>, beg. <span dir=\"rtl\">ר׳ הושעיה ר׳</span> R. Ḥ. senior (contrad. to <a href=\"#\" data-headword=\"זְעֵיר II\">זעירא</a>). <span class=\"citation\">Y. Yeb. IV, 6ᵃ</span> ר׳ חייא ר׳ R. Ḥ. senior; a. v. fr.—<span dir=\"rtl\">מדרש ר׳</span> (pl. <span dir=\"rtl\">רַבּוֹת</span>), v. <a href=\"#\" data-headword=\"מִדְרָשׁ\">מִדְרָשׁ</a>.</div><div class=\"sense\"><b>—2)</b> <i>teacher</i>. Y. l. c. 6ᵇ top <span dir=\"rtl\">הידינו ר׳ ר׳ דמתניתא ר׳ דאולפנא</span> what teacher do you mean? a teacher of the Mishnah (a Tannai), or a teacher of tradition? <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">ואיפשר כן ר׳ שאל וכ׳</span> can that be? did the teacher ask his pupil? <span class=\"citation\">B. Mets. 101ᵃ</span> <span dir=\"rtl\">כגון דא צריכה ר׳</span> a thing like this requires a teacher (to say it)!; a. fr.—Pl. <span dir=\"rtl\">רַבְוָותָא</span>. <span class=\"citation\">Snh. 102ᵇ</span> <span dir=\"rtl\">נפתח בר׳</span> (Ms. F. <span dir=\"rtl\">ברברבתא</span>) let us open our meeting with (speaking of our) teachers (opp. to <span dir=\"rtl\">חברין</span>).—<i>Fem.</i> <a href=\"#\" data-headword=\"רַבְּתָא\">רַבְּתָא</a>, q. v.; <a href=\"#\" data-headword=\"רַבָּתִי\">רַבָּתִי</a>. <span class=\"citation\">Yeb. 21ᵇ</span> <span dir=\"rtl\">אימא ר׳</span> grandmother.—<span dir=\"rtl\"><span dir=\"rtl\">אבל ר׳</span> (מסכת</span>), v. <a href=\"#\" data-headword=\"אֵבֶל\">אֵבֶל</a>.</div>","alt":[]},"28286":{"h":"רַבָּה II","r":"T00061","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (= <span dir=\"rtl\">רַב אַבָּה</span>) <i>Rabbah</i>, name of several Amoraim, esp. <i>a</i>) R. bar Naḥmani, chief of the college of Pumb’ditha (v. Grætz, Gesch. d. Jud.<sup>1</sup> IV, p. 400 sq.) <span class=\"citation\">Gitt. 3ᵃ</span>. <span class=\"citation\">Hor. 14ᵃ</span> ר׳ עוקר הרים R. uproots mountains (is ingenious, v. <a href=\"#\" data-headword=\"הַר\">הַר</a>). <span class=\"citation\">B. Mets. 86ᵃ</span>; a. v. fr.—<i>b</i>) R. Zuṭi (Junior). <span class=\"citation\">B. Bath. 120ᵃ</span>. <span class=\"citation\">Men. 31ᵇ</span>; a. e.—<i>c</i>) R. bar Ḥanah. <span class=\"citation\">Snh. 5ᵃ</span>.—<i>d</i>) R. bar bar Ḥanah, known for his fables. <span class=\"citation\">B. Bath. 73ᵇ</span>; a. fr. [<span class=\"citation\">Y. Ber. II, 4ᵇ</span> <span dir=\"rtl\">אבא בר בר ח׳</span>.]—<i>e</i>) R. bar Abbuha (Abbahu, v. Fr. M’bo, p. 60ᵃ). <span class=\"citation\">Bekh. 34ᵃ</span>. <span class=\"citation\">B. Kam. 46ᵇ</span>; a. e.—<i>f</i>) R. bar Matt’nah. Hor. l. c.; a. e.; a. others.</div>","alt":[]},"28287":{"h":"רַבָּה III","r":"T00062","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"רַב I\"><span dir=\"rtl\">רַב</span> I</a>, II.</div>","alt":[]},"28288":{"h":"רְבוּ","r":"T00063","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְבוּתָא\">רְבוּתָא</a></div>","alt":[]},"28289":{"h":"רִבּוֹא","r":"T00064","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>large amount</i>,] <i>myriad, ten thousand</i>. <span class=\"citation\">Peah III, 8</span> אחד בר׳ שבהן Ms. M. (ed. <span dir=\"rtl\">מר׳</span>) one ten thousandth portion of my property; <span class=\"citation\">Tosef. ib. I, 13</span>, a. e. <span class=\"citation\">Y. Maas. Sh. I, 52ᵈ</span> top <span dir=\"rtl\">מאה ר׳</span> one hundred myriads (of Denars). <span class=\"citation\">Succ. 51ᵇ</span> <span dir=\"rtl\">ששים ר׳ על ששים ר׳ וכ׳</span> twice sixty myriads, double the number &amp;c., v. <a href=\"#\" data-headword=\"כֶּפֶל\">כֵּפֶל</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אינה … וחמשה ר׳ דינרי זהב</span> Ms. M. (ed. <span dir=\"rtl\">ואחד</span>, v. Rabb. D. S. a. l. note) worth no less than twenty-five myriads of gold Denars; <span class=\"citation\">Tosef. ib. IV, 6</span>; <span class=\"citation\">Yalk. Deut. 913</span>. <span class=\"citation\">Shek. VIII, 5</span> <span dir=\"rtl\">משמונים ושתי ר׳ נעשית</span> it (the curtain) was made of material worth eighty-two myriads; (oth. opin.: of eighty-two myriads of threads; Var. <span dir=\"rtl\">ריבות</span> made by eighty-two girls); <span class=\"citation\">Ḥull. 90ᵇ</span> (v. Rabb. D. S. a. l. note 6); a. fr.—Pl. <span dir=\"rtl\">רבּוֹאוֹת</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Arakh. IV, 3</span> (<span class=\"citation\">17ᵇ</span>) <span dir=\"rtl\">אפי׳ מת … ריבוא או ובאה לו בר׳ וכ׳</span> even if his father died (was dying at the time of his vow), and left him a myriad, or he has a ship at sea (at the time of his vow), and it comes in with myriads, the sanctuary has no claim on it.—<span class=\"citation\">Yalk. Deut. 942</span> <span dir=\"rtl\">שתי רִיבּוֹת</span> two myriads (Zuzin); Sifré <span class=\"citation\">ib. 306</span> <span dir=\"rtl\">שתי ריבוא</span>.</div>","alt":["רִיבּ׳"]},"28290":{"h":"רִבּוֹא ²","r":"T00065","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings VIII, 63</span>. <span class=\"citation\">Targ. Deut. XXXII, 30</span> <a href=\"#\" data-headword=\"רִבּוֹתָא\">רִבּוֹתָא</a> (<a href=\"#\" data-headword=\"רִבּוּי\">רִבּוּ׳</a>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>).—Pl. <a href=\"#\" data-headword=\"רִבְוָון\">רִבְוָון</a>, <a href=\"#\" data-headword=\"רִדְוָותָא\">רִבְוָותָא</a>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>, v. <a href=\"#\" data-headword=\"רִבְבַת\">רִבְבַת</a>.—<span class=\"citation\">Targ. Ps. LXVIII, 18</span> רִיבּוֹתָן Ms. (ed. <span dir=\"rtl\">רִבְבָן</span>).</div>","alt":["רִי׳"]},"28291":{"h":"*רְבוּבָה I","r":"T00066","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַב\">רָבַב</a>) [<i>pile, deposit</i>,] <i>cavity</i> in the ascent to the altar for the deposit of fowls ritually disqualified. <span class=\"citation\">Midd. III, 3</span>; v., however, <a href=\"#\" data-headword=\"רְבוּכָה\">רְבוּכָה</a>.</div>","alt":[]},"28292":{"h":"*רְבוּבָה II","r":"T00067","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> name of <i>a musical instrument</i>, a sort of <i>tambourine</i>. <span class=\"citation\">Sot. 49ᵇ</span> quot. in Ar. s. v. (ed. <a href=\"#\" data-headword=\"טַנְבּוּרָא\">טנבורא</a>; Mus. quotes <a href=\"#\" data-headword=\"רְכוּבָה\">רכובה</a>; Ar. s. v. <span dir=\"rtl\">אלית</span> quotes fr. Sot. l. c.: <a href=\"#\" data-headword=\"כּוּבָּא I\">כובא</a> as explan. of <a href=\"#\" data-headword=\"אֵירוּס I\">אירוס</a>; Hai Gaon to <span class=\"citation\">Kel. XV, 6</span>: <span dir=\"rtl\">דכובא</span> or <span dir=\"rtl\">דכוכא</span>).</div>","alt":[]},"28293":{"h":"רִבְוָון","r":"T00068","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבְבַת\">רִבְבַת</a></div>","alt":["רִבְוָות","רְבַוְותָּא"]},"28294":{"h":"רִבּוּי","r":"T00069","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִבּוֹא\">רִיבּ׳</a>.</div>","alt":["רִבּוּיָא"]},"28295":{"h":"רְבוּכָה","r":"T00070","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רבך</span>, cmp. <a href=\"#\" data-headword=\"רָבַג\">רָבַג</a>) </div><div class=\"sense\"><b>1)</b> <i>irregular pile, deposit</i>. <span class=\"citation\">Tosef. Zeb. VII, 6</span> <span dir=\"rtl\">חלון … ור׳ היתה וכ׳</span> (ed. Zuck. <span dir=\"rtl\">ורְבִיכָה</span>) there was an opening on the western side of the ascent to the altar, called <i>r’bukhah</i>, whither they cast &amp;c., v. <a href=\"#\" data-headword=\"*רְבוּבָה I\"><span dir=\"rtl\">רְבוּבָה</span> I</a>.</div><div class=\"sense\"><b>—2)</b> <i>pulp of flour mixed with hot water and oil</i>, v. <a href=\"#\" data-headword=\"רְבִיכָה\">רְבִיכָה</a>.</div>","alt":[]},"28296":{"h":"רִבְוָן","r":"T00071","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבְבַת\">רִבְבַת</a></div>","alt":[]},"28297":{"h":"רִבּוֹן","r":"T00072","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַב\">רָבַב</a>) <i>lord, master</i>. <span class=\"citation\">Gen. R. s. 93</span> (expl. <span dir=\"rtl\">לאדון</span>, <span class=\"citation\">Gen. XLV, 8</span>) <span dir=\"rtl\">לר׳</span> chief, contrad. to <a href=\"#\" data-headword=\"שַׁלִּיט\">שליט</a>. <span class=\"citation\">Yoma 87ᵇ</span> ר׳ העולמים Master of the worlds (opening words of a well-known prayer <span dir=\"rtl\">ר׳ הע׳ לא על צדקותינו וכ׳</span>).—<span dir=\"rtl\">רִבּוֹנוֹ של עולם</span> (abbrev. <span dir=\"rtl\">רש&quot;ע</span>) Master of the world! <span class=\"citation\">Ber. 9ᵇ</span>; a. v. fr.</div>","alt":[]},"28298":{"h":"רִבּוֹן ²","r":"T00073","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. XII, 5</span>. <span class=\"citation\">Targ. Ex. XXI, 4</span>; <span class=\"citation\">6</span>; <span class=\"citation\">8</span>. <span class=\"citation\">Targ. I Sam. XV, 32</span> <span dir=\"rtl\">רִבּוֹנִי</span> (h. text <a href=\"#\" data-headword=\"סָר\">סָר</a>); a. fr.—<i>Pl.</i> <span dir=\"rtl\">רִבּוֹנִין</span>, <span dir=\"rtl\">רִבּוֹנַיָּא</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a> (also <i>pl.</i> excellentiæ). <span class=\"citation\">Targ. I Kings XXII, 17</span>. <span class=\"citation\">Targ. Gen. XIX, 2</span>. <span class=\"citation\">Targ. Y. ib. XLII, 33</span>. <span class=\"citation\">Targ. Ps. CXXXVI, 3</span> Ms. (ed. <span dir=\"rtl\">מרי מריא</span>); a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"רִבּוֹנְתָּא\">רִבּוֹנְתָּא</a>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Targ. Gen. XVI, 8</span> (ed. Vien. O. <span dir=\"rtl\">רִבָּנְתִּי</span>), sq. <span class=\"citation\">Targ. Prov. XXX, 23</span>; a. e.</div>","alt":["רִבּוֹנָא","רִי׳"]},"28299":{"h":"רִבּוּנָא","r":"T00074","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיכּוּנָא\">רִיכּוּנָא</a></div>","alt":["רִיבּ׳"]},"28300":{"h":"רִבּוֹנְתָּא","r":"T00075","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבּוֹן\">רִבּוֹן</a> ch.</div>","alt":[]},"28301":{"h":"רִבּוּעַ","r":"T00076","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִבּוֹא\">רִיבּ׳</a>.</div>","alt":["רִבּוּעָא"]},"28302":{"h":"רִבּוֹתָא","r":"T00077","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבּוֹא\">רִבּוֹא</a> ch.</div>","alt":["רִבּוּתָא"]},"28303":{"h":"רְבוּתָא","r":"T00078","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (רְבֵי I) </div><div class=\"sense\"><b>1)</b> <i>greatness, dignity, office; anointment</i>. Targ. II Esth. VI, 10. <span class=\"citation\">Targ. Is. IX, 6</span>. <span class=\"citation\">Targ. Deut. XXXII, 3</span> (Y. II <span dir=\"rtl\">רַבּוּ</span>). <span class=\"citation\">Targ. Zech. IX, 6</span> (h. text <a href=\"#\" data-headword=\"גָּאוֹן\">גאון</a>). <span class=\"citation\">Targ. Num. XVIII, 8</span> (h. text <a href=\"#\" data-headword=\"מָשְׁחָה\">מָשְׁחָה</a>). <span class=\"citation\">Targ. Ps. CXLV, 3</span> (some ed. <span dir=\"rtl\">רַבּוּ׳</span>). <span class=\"citation\">Ib. CL, 2</span>, v. <a href=\"#\" data-headword=\"רַבָּנוּתָא\">רַבָּנוּתָא</a>; a. fr.—<span class=\"citation\">Targ. Esth. II, 9</span>, v. <a href=\"#\" data-headword=\"סַמְתּוֹרָא\">סַמְתּוֹרָא</a>.—<span class=\"citation\">Gitt. 68ᵇ</span> <span dir=\"rtl\">מאי רְבוּתַיְיכוּ מינן</span> wherein are you our superiors?; <span dir=\"rtl\">אחוי לך רְבוּתָאִי</span> I shall show thee my superiority. <span class=\"citation\">Y. Ber. I, 2ᵈ</span> bot. <span dir=\"rtl\">רבו היא</span> it was an honor (to be brought into the king’s palace); a. e.</div><div class=\"sense\"><b>—2)</b> <i>a great thing, something remarkable</i>. <span class=\"citation\">Targ. Esth. II, 21</span>.—<span class=\"citation\">Snh. 106ᵇ</span>, v. <a href=\"#\" data-headword=\"בַּעְיָא\">בַּעְיָא</a>. <span class=\"citation\">Ḥag. 24ᵃ</span> <span dir=\"rtl\">היינו רְבוּתֵיה דנגובה</span> (Rashi <span dir=\"rtl\">רבותא</span>) this is the remarkable thing about ‘the dry hand’ (that is the reason for the insertion of the word <a href=\"#\" data-headword=\"נְגוּבָה\">נגובה</a>, to show that even the touch of a dry hand makes unclean); <span dir=\"rtl\">מאי ר׳ דנגובה</span> what it there remarkable in ‘the dry hand’? <span class=\"citation\">B. Bath. 36ᵇ</span>; <span class=\"citation\">Yeb. 45ᵃ</span> <span dir=\"rtl\">ר׳ למחשב גברי וכ׳</span> is it a great thing to quote authorities? (I can do the same:) here are Rab &amp;c.; a. e.—V. <a href=\"#\" data-headword=\"רְבִיתָא II\"><span dir=\"rtl\">רְבִיתָא</span> II</a>, III, a. <a href=\"#\" data-headword=\"רֵיבוּתָא\">רֵיבוּתָא</a>.</div>","alt":["רְבוּ"]},"28304":{"h":"רַבּוּתָא","r":"T00079","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"רַב\">רַבָּא</a>) </div><div class=\"sense\"><b>1)</b> <i>seniority</i>. <span class=\"citation\">Targ. O. Gen. XLIII, 33</span> <span dir=\"rtl\">כרַבּוּתֵיה</span> ed. Berl. (ed. <span dir=\"rtl\">כרביותיה</span>, corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>superiority</i>, v. <a href=\"#\" data-headword=\"רְבוּתָא\">preced.</a></div>","alt":[]},"28305":{"h":"רִבֵּי","r":"T00080","html":"<div class=\"sense\">, pl. constr. of <a href=\"#\" data-headword=\"רְבָבָה\">רְבָבָה</a>.</div>","alt":[]},"28306":{"h":"רבי","r":"T00081","html":"<div class=\"sense\"> (b. h.) <i>to be much, many; to grow, increase</i>. <span class=\"citation\">Yoma 87ᵇ</span> <span dir=\"rtl\">עונותינו רָבוּ וכ׳</span> our sins are too many to be counted. <span class=\"citation\">Gen. R. s. 34</span> אצא ואהי פרה ורָבֶה וכ׳ I may go out (of the ark) and be multiplying and increasing for curse. <span class=\"citation\">Bekh. 44ᵇ</span> <span dir=\"rtl\">דם ר׳ שחין ר׳</span> if the blood is allowed to increase (if bleeding is neglected), skin disease will develop; <span dir=\"rtl\">מי רגלים רָּבִין וכ׳</span> if one allows the urine to increase (through neglect) &amp;c. <span class=\"citation\">Sabb. 33ᵇ</span> <span dir=\"rtl\">בעון … צרות רָבוֹת וכ׳</span> for the sin of obscene talk troubles increase, and new evil decrees come &amp;c. <span class=\"citation\">Num. R. s. 11</span>, v. <a href=\"#\" data-headword=\"פָּרָה II\"><span dir=\"rtl\">פָּרָה</span> II</a>. <span class=\"citation\">Gen. R. s. 48</span> <span dir=\"rtl\">הכתב ר׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"כְּתָב\">כְּתָב</a>. <span class=\"citation\">Sot. 47ᵇ</span> <span dir=\"rtl\">משרבו … בדין ר׳ וכ׳</span> when the whisperers in court (secret influences) increased, the anger (of God) against Israel increased. <span class=\"citation\">Snh. 97ᵃ</span> <span dir=\"rtl\">העזות תִּרְבֶּה</span> impudence shall be large. <span class=\"citation\">Y. Yeb. IV, 6ᵃ</span> bot., v. <a href=\"#\" data-headword=\"אל\">אל&quot;ף</a>; a. fr.—<span class=\"citation\">Gen. R. s. 98</span> (play on <span dir=\"rtl\">בן פרת</span>, <span class=\"citation\">Gen. XLIX, 22</span>) <span dir=\"rtl\">בן פירות רָבִיתָה</span> ‘a child of fruits’ (through interpreting Pharaoh’s dream about the ears of corn) thou didst grow (to high office); <span dir=\"rtl\">בן פרות רביתה יוסף</span> ‘a child of cows’ (through interpreting the dream about cows) thou didst grow; <span dir=\"rtl\">בן פורת</span> (<a href=\"#\" data-headword=\"יוֹסֵף\">יוסף</a>) <span dir=\"rtl\">רָבִיתָ יוסף</span> ‘a child of growth’, thou didst grow tall (so as to protect Rachel from Esau’s sight; v. <span class=\"citation\">Gen. R. s. 78</span>); Yalk. ib. 133 [read:] <span dir=\"rtl\">בן פורת יוסף פָּרִיתָ רבית יוסף</span>.</div><div class=\"sense\"><b>Pi. רִיבָּה</b> <div class=\"sense\"><b>1)</b> <i>to increase, do much, do more</i>. <span class=\"citation\">Gen. R. s. 34</span> <span dir=\"rtl\">ר׳ בטהורים יותר וכ׳</span> ordered a larger number of the clean animals to be taken into the ark than of the unclean. <span class=\"citation\">Tosef. Dem. IV, 12</span> <span dir=\"rtl\">ר׳ בעיר ולא ר׳ במדינה</span> if one offers a large quantity for sale, while none is offered in the country. <span class=\"citation\">Ib. 13</span> <span dir=\"rtl\">כל שר׳ לו מותר</span> wherever one has a large quantity for sale, it is permitted (to buy of him); a. fr.—<span class=\"citation\">Men. 89ᵃ</span> <span dir=\"rtl\">ר׳ שמן וכ׳</span>, v. <a href=\"#\" data-headword=\"רְבִיכָה\">רְבִיכָה</a>.</div><div class=\"sense\"><b>—2)</b>  (hermeneutics) <i>to use an additional word for the purpose of intimating something not otherwise included; to argue from an additional word</i> or <i>from a generalization</i> in the Biblical text; <i>to widen the scope of a law; to include</i>. Ib. <span dir=\"rtl\">אם אתה מְרַבֶּה וכ׳</span> if thou wert to argue an entire day on the intimation of an increase lying in the words <i>bashshemen</i> (<span class=\"citation\">Lev. VI, 14</span>; <span class=\"citation\">VII, 12</span>), I should not listen to thee; <span class=\"citation\">Zeb. 82ᵃ</span>; <span class=\"citation\">Nidd. 72ᵇ</span>. <span class=\"citation\">Shebu. 26ᵃ</span>, v. <a href=\"#\" data-headword=\"מָעַט\">מָעַט</a>. <span class=\"citation\">Ib. 27ᵃ</span> <span dir=\"rtl\">מדאצטריך או לְרַבּוֹת וכ׳</span> as the word <a href=\"#\" data-headword=\"אוֹ\">אוֹ</a> (<span class=\"citation\">Lev. V, 4</span>) is needed for the inclusion of vows for the benefit of others. <span class=\"citation\">Pes. 22ᵇ</span>, v. <a href=\"#\" data-headword=\"אֵת\">אֵת</a>. <span class=\"citation\">Snh. 60ᵇ</span> <span dir=\"rtl\">יכול שאני מְרַבֶּה וכ׳</span> you might think that I must include &amp;c.; a. v. fr.—[<span class=\"citation\">Yalk. Ex. 348</span> <span dir=\"rtl\">ר׳ כל וכ׳</span>, v. <a href=\"#\" data-headword=\"רִיקֵן I\">רִיקֵן</a>.]—<span class=\"citation\">Gen. R. s. 85</span> (ref. to <span class=\"citation\">Gen. XXXVIII, 29</span>) <span dir=\"rtl\">זה רִבָּה על כל הפריצים ממך יעמודו</span> (not <span dir=\"rtl\">יעמוד</span>) this event implies (the prophecy) that all conquerors shall rise from thee (Perez); Yalk. ib. 145.</div><div class=\"sense\"><b>—3)</b> <i>to lend</i> or <i>borrow on usury</i> <a href=\"#\" data-headword=\"רִבִּית\">(רִבִּית</a>); <i>to make a profit</i>. Sifra B’har, ch. VI, Par. 5; <span class=\"citation\">B. Mets. V, 1</span> (expl. <a href=\"#\" data-headword=\"תַּרְבִּית\">תַּרְבִּית</a>) <span dir=\"rtl\">המְרַבֶּה בפירות</span> he who makes a profit on lending provisions. <span class=\"citation\">Tosef. ib. IV, 2</span> <span dir=\"rtl\">מְרַבִּין על השכר ואין מרבין וכ׳</span> you may make a profit on renting (lending money to the money-changer merely for exhibition), but you dare not make a profit on a sale (of land as security for a loan). <span class=\"citation\">B. Mets. V, 2</span> <span dir=\"rtl\">מרבין … ואין מרבין וכ׳</span> you may make a profit by a reduction of rent on account of payment in advance, but you dare not make a profit by increasing the price of an object sold on account of postponed payment; a. e.</div></div><div class=\"sense\"><b>Hif. הִרְבָּה</b> <div class=\"sense\"><i>to cause increase; to strengthen; to do much</i>. <span class=\"citation\">Ber. 17ᵃ</span>, v. <a href=\"#\" data-headword=\"מָעַט\">מָעַט</a>. <span class=\"citation\">Ab. I, 17</span> <span dir=\"rtl\">וכל המַרְבֶּה דברים וכ׳</span> he that talks much brings about sin. <span class=\"citation\">Ib. II, 7</span> <span dir=\"rtl\">מרבה בשר וכ׳</span> making much flesh (indulging in eating) makes much food for worms; <span dir=\"rtl\">מרבה צדקה וכ׳</span> he that does much charity, does much for peace. <span class=\"citation\">Ber. 40ᵃ</span> <span dir=\"rtl\">מפרין ומרבין</span>, v. <a href=\"#\" data-headword=\"פָּרָה II\"><span dir=\"rtl\">פָּרָה</span> II</a>. <span class=\"citation\">Ib. 64ᵃ</span> <span dir=\"rtl\">ת&quot;ח מַרְבִּים וכ׳</span> scholars advance peace in the world; a. fr.—<span class=\"citation\">B. Bath. 11ᵇ</span> <span dir=\"rtl\">בני מבוי … שמרבה עליהן את הדרך</span> the neighbors may prevent him, because he increases the use of the way too much for them (causes many people to step upon their ground); <span class=\"citation\">Tosef. ib. I, 4</span>; Y. ib. II, 13ᵇ bot. <span dir=\"rtl\">דו יכיל מימר … והן מרבין עלינו וכ׳</span> he may say to him, they go and come, ask for thee and cannot find thee, and thus they use the way too frequently for us.</div></div><div class=\"sense\"><b>Nithpa. נִתְרַבָּה</b> <div class=\"sense\"><i>to be increased</i>; with <span dir=\"rtl\">בגדים</span>, <i>to be clothed with the larger number of garments</i> designated for the high priest, v. <a href=\"#\" data-headword=\"מְרוּבֶּה\">מְרוּבֶּה</a>. <span class=\"citation\">Yoma 5ᵃ</span> <span dir=\"rtl\">נ׳ שבעה</span> if he wore the high priestly garments during the entire week of inauguration; <span dir=\"rtl\">נ׳ יום אחד</span> if he wore them only one day.</div></div>","alt":["רָבָה","רָבֶה"]},"28307":{"h":"רְבֵי","r":"T00082","html":"<div class=\"sense\"><b>1)</b> <i>to grow, increase; to become great</i>. <span class=\"citation\">Targ. Gen. XXI, 8</span>. <span class=\"citation\">Targ. Hos. VIII, 4</span> <span dir=\"rtl\">רְבִיאוּ</span> ed. Ven. (oth. ed. <a href=\"#\" data-headword=\"רַבִּי\">רַבִּי׳</a> Pa.). <span class=\"citation\">Targ. Job V, 6</span> (some ed. <span dir=\"rtl\">יְרַבֵּי</span> <i>Pa.</i>); a. fr.—Part. <a href=\"#\" data-headword=\"רָבֵי\">רָבֵי</a>; pl. <a href=\"#\" data-headword=\"רִבְיָין\">רַבְיָין</a>. <span class=\"citation\">Targ. O. Gen. XXVI, 13</span> (Y. <a href=\"#\" data-headword=\"*רְבֵי\">רְבֵי</a>). <span class=\"citation\">Targ. Ps. CXLIV, 12</span> (h. text <span dir=\"rtl\">מגדלים</span>); a. fr.—<span class=\"citation\">Gen. R. s. 78</span> (ref. to <span class=\"citation\">Gen. XLIX, 22</span>, <span dir=\"rtl\">בן פרת</span>) <span dir=\"rtl\">רַבְיַית יוסף</span> thou didst grow, O Joseph; <span dir=\"rtl\">רביית עלי עין</span> thou didst grow over (Esau’s) sight (so as to protect Rachel from Esau’s voluptuous looks); v. <a href=\"#\" data-headword=\"רבי\">preced.</a> <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">דרָבוּן עמיה</span> (<span dir=\"rtl\">דרַבְיָן</span>) they grow up with him; a. fr.</div><div class=\"sense\"><b>Pa. רַבֵּי</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רבי\">same</a>, v. supra.—2) </div><div class=\"sense\"><i>to raise, rear, produce</i>. <span class=\"citation\">Targ. Y. Gen. II, 9</span>. <span class=\"citation\">Targ. Koh. II, 6</span>. <span class=\"citation\">Targ. Ps. CXLVII, 8</span>. <span class=\"citation\">Targ. Job XXXVIII, 27</span> מְרַבְּיָא Ms. (ed. <a href=\"#\" data-headword=\"מַרְדְּיָא\">מַרְבְּיָא</a> <i>Af.</i>; ed. Wil. <span dir=\"rtl\">מִרְבְּ׳</span>, incorr.). <span class=\"citation\">Targ. Is. XVII, 6</span> מְרַבָּה Levita (ed. <a href=\"#\" data-headword=\"מַרְדָּא I\">מרדא</a>); a. fr.—<span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">לא תְרַבֵּי</span>, v. <a href=\"#\" data-headword=\"גּוּרָא\">גּוּרָא</a>. <span class=\"citation\">Ab. Zar. 22ᵇ</span> <span dir=\"rtl\">ארמלתא לא תְרַבֵּי וכ׳</span> a widow should not raise a dog. <span class=\"citation\">Cant. R. to I, 1</span> <span dir=\"rtl\">מְרַבְּיָין ולא וכ׳</span> raise children that are not like them; <span class=\"citation\">Yalk. Sam. 113</span> <span dir=\"rtl\">מְרַבְּיָאן</span>, v. <a href=\"#\" data-headword=\"דִּכְוָת־\">דִּכְוָת־</a>; a. e.—Part. pass. <a href=\"#\" data-headword=\"מְרַוֵּי\">מְרַבֵּי</a>. <span class=\"citation\">Targ. O. Gen. XXXVII, 2</span> (ed. Berl. <a href=\"#\" data-headword=\"רָבֵי\">רָבֵי</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to raise to dignity, advance, elevate, anoint</i> (priest, king &amp;c.), <i>appoint</i>. <span class=\"citation\">Targ. O. Ex. XXXI, 2</span> (h. text <span dir=\"rtl\">קרא</span>). <span class=\"citation\">Targ. Is. XLII, 6</span>. <span class=\"citation\">Targ. Esth. X, 2</span>. <span class=\"citation\">Targ. Ps. II, 6</span> (h. text <span dir=\"rtl\">נסך</span>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"מְרַוָּא\">מְרַבָּא</a>, <a href=\"#\" data-headword=\"מְרַוֵּי\">מְרַבֵּי</a>. <span class=\"citation\">Targ. II Sam. III, 39</span> (h. text <span dir=\"rtl\">משוח</span>). <span class=\"citation\">Targ. Ez. XXVIII, 14</span> (h. text <span dir=\"rtl\">ממשח</span>).—Trnsf. (of inanimate things) <i>to consecrate</i> (by anointing). <span class=\"citation\">Targ. Ex. XXX, 26</span>. <span class=\"citation\">Targ. Y. Gen. XXXI, 13</span> (ed. Vien. <a href=\"#\" data-headword=\"רִיבִּית\">רִיבִיתָ</a>, incorr.); a. e.</div><div class=\"sense\"><b>—3)</b> <i>to lend or borrow on usury</i>. <span class=\"citation\">Targ. O. Deut. XXIII, 20</span> (Y. ed. Vien. <span dir=\"rtl\">לא תַרְבֵּי וכ׳</span> add not from what is thine to thy neighbor’s, i.e. <i>borrow</i> not on usury, v. Rashi a. l.).</div><div class=\"sense\"><b>—4)</b> <i>to extend the scope, to include</i>. <span class=\"citation\">Snh. 46ᵃ</span> <span dir=\"rtl\">לרַבּוּיֵי עכו&quot;ם</span> to include the worshippers of idols; <span dir=\"rtl\">לרבויי שאר וכ׳</span> to include other convicts doomed to be stoned. Ib. <span dir=\"rtl\">לא הוה מְרַבִּינָן וכ׳</span> we should have included only &amp;c. <span class=\"citation\">B. Kam. 64ᵇ</span> <span dir=\"rtl\">מאי ר׳ וכ׳</span> what does the text imply? It implies all things (animate or inanimate, marked or unmarked). <span class=\"citation\">Zeb. 8ᵇ</span> <span dir=\"rtl\">כללא קמא מְרַבֵּי וכ׳</span> the first generalization serves to include sacrifices and no more; a. fr.</div></div><div class=\"sense\"><b>Af. אַרְבֵּי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רבי\">same</a>, <i>to increase, add.</i> <span class=\"citation\">Targ. Y. Deut. XXIII, 20</span>, v. supra.</div></div><div class=\"sense\"><b>Ithpa. אִתְרַבָּא  אִתְרַבֵּי</b> <div class=\"sense\"><b>1)</b> <i>to be reared, grow up</i>. <span class=\"citation\">Targ. Y. Gen. XXXVII, 2</span>. <span class=\"citation\">Targ. I Chr. XIV, 4</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be raised; to be installed, anointed</i>. <span class=\"citation\">Targ. Is. LXI, 9</span>. <span class=\"citation\">Targ. O. Lev. XXI, 10</span>. <span class=\"citation\">Targ. Y. ib. IV, 3</span>. <span class=\"citation\">Targ. Num. III, 3</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to be proud, vaunt</i>. Y. Sabb. VI, 7ᵈ bot. <span dir=\"rtl\">טליין … מִתְרַבְּיָין וכ׳</span> young children were boasting (showing off their silver ornaments) in the court of &amp;c.; Y. Bets. II, end, 61ᵃ <span dir=\"rtl\">מתריביין</span> (corr. acc.).</div><div class=\"sense\"><b>—4)</b> <i>to be lent</i> or <i>borrowed on usury</i>. <span class=\"citation\">Targ. Deut. XXIII, 20</span>.</div><div class=\"sense\"><b>—5)</b> <i>to be derived by implication, be included</i>. <span class=\"citation\">Zeb. 82ᵃ</span> <span dir=\"rtl\">מכדי אִיתְרַבּוּ כל וכ׳</span> since all sacrifices … were included in the law with regard to &amp;c.; a. e.</div></div>","alt":["רְבָא I"]},"28308":{"h":"*רְבֵי","r":"T00083","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"רְבֵי\">preced.</a>) = b. h. <a href=\"#\" data-headword=\"רַבָּה I\">רבה</a> [<i>to stretch</i> the bow string, cmp. Lat. intendo arcum,] <i>to shoot</i>. <span class=\"citation\">Targ. O. Gen. XXI, 20</span> <span dir=\"rtl\">והוה רָבֵי קַשְׁתָּא</span> and he became an archer; [ed. Berl. <span dir=\"rtl\">רָבְיָא קַשָּׁתָא</span> an archer-boy].</div><div class=\"sense\"><b>Pa. רַבֵּי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רְבֵי\">same</a>. Targ. Y. ib. <span dir=\"rtl\">והוה יליף רַבֵּי קַשְׁוָותָא</span> and he learned how to shoot with bows.</div></div>","alt":["רְבָא II"]},"28309":{"h":"רְבֵי ²","r":"T00084","html":"<div class=\"sense\"> (= <span dir=\"rtl\">רבע</span>) <i>to lie down, die</i>. <span class=\"citation\">Y. Yeb. IV, 6ᵃ</span>, v. <a href=\"#\" data-headword=\"אל\">אל&quot;ף</a>.</div><div class=\"sense\"><b>*. רַבֵּי</b> <div class=\"sense\"><i>to crouch, flee to a hiding place</i>. <span class=\"citation\">Bets. 24ᵃ</span> <span dir=\"rtl\">עבידי לרַבּוּיִי</span> are in the habit of hiding; <span dir=\"rtl\">לא עבידי לרבויי</span> make no attempt to flee; <span class=\"citation\">Sabb. 106ᵇ</span>; v. <a href=\"#\" data-headword=\"דְּבָא\">דְּבָא</a>.</div></div>","alt":["רְבָא III"]},"28310":{"h":"רַבִּי","r":"T00085","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רַב II\"><span dir=\"rtl\">רַב</span> II</a>) [<i>my teacher, my master</i>,] <i>Rabbi</i>, title of scholars, esp. of the Tannaim, and of the Palestinian Amoraim. <span class=\"citation\">B. Mets. 85ᵃ</span> חכים … ור׳ קרו לך וכ׳ I shall make thee a <i>ḥackim</i>, and a gold-embroidered cloak they shall spread over thee, and Rabbi they shall call thee &amp;c. <span class=\"citation\">Ib. 84ᵃ</span> <span dir=\"rtl\">מאי … ר׳ קרו לי והכא ר׳ וכ׳</span> what good hast thou done me, there (among the Roman gladiators) they called me Rabbi (master), and here (as a scholar) they call me Rabbi. <span class=\"citation\">Ab. Zar. 17ᵇ</span> <span dir=\"rtl\">ומ&quot;ט קרו לך ר׳ רַבָּן וכ׳</span> and why do they call thee Rabbi? I am the chief master of weavers. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ אלעזר</span>; a. v. fr.—Esp. <i>Rabbi</i>, surname of R. Judah han-Nasi. <span class=\"citation\">Gitt. 59ᵃ</span> <span dir=\"rtl\">מימות משה ועד ר׳ וכ׳</span> from the days of Moses to those of Rabbi we do not meet with learning and high office in one place (combined in one person). <span class=\"citation\">Ber. 13ᵃ</span>; <span class=\"citation\">Sot. 32ᵇ</span>. <span class=\"citation\">B. Mets. 85ᵃ</span>; a. v. fr.</div>","alt":[]},"28311":{"h":"רָבֵי","r":"T00086","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רְבֵי I) [<i>growing</i>,] <i>boy; apprentice</i>. <span class=\"citation\">Targ. O. Gen. XXXVII, 2</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"מְרַוֵּי\">מְרַבֵּי</a>). Ib. XXI, 20, v. <span dir=\"rtl\">רְבֵי II</span>. Ib. 8; a. fr.—<span class=\"citation\">Succ. 5ᵇ</span> (expl. <a href=\"#\" data-headword=\"כְּרוּב I\">כרוב</a>), v. <a href=\"#\" data-headword=\"כְּרוּב I\"><span dir=\"rtl\">כְּרוּב</span> I</a>; a. e.—<i>Fem.</i> רְבִיתָא <i>girl</i>. <span class=\"citation\">Targ. Y. Gen. XXIV, 14</span> Ar. (ed. <a href=\"#\" data-headword=\"רִיבָא\">ריבא</a>). Targ. II Esth. II, 12, sq.; a. e.—<span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">הויא ההיא ר׳ וכ׳</span> there was a girl (in Sodom) that carried bread for the poor in a pitcher. <span class=\"citation\">Ib. 58ᵇ</span> <span dir=\"rtl\">ר׳ דפלניא</span> that slave’s girl (assigned to him as wife by his master). <span class=\"citation\">Kidd. 70ᵇ</span> <span dir=\"rtl\">דלא אשתייר … ר׳ וכ׳</span> for none of them (the Asmonean family) survived except a certain girl &amp;c.; a. e.—V. <a href=\"#\" data-headword=\"רִיבָא\">רִיבָא</a>.</div>","alt":["רָבְיָא","רַ׳"]},"28312":{"h":"רָבִיב","r":"T00087","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַב\">רָבַב</a>) </div><div class=\"sense\"><b>1)</b> <i>lining, thick cloth</i>. <span class=\"citation\">Sifré Deut. 306</span> (ref. to <span dir=\"rtl\">רביבים</span>, <span class=\"citation\">Deut. XXXII, 2</span>) <span dir=\"rtl\">זה … שמארגת את הרקיע כר׳</span> (Pesik. Zuṭr. Haăz., ed. Bub. p. 110 <span dir=\"rtl\">שמרבבת</span>) that is the south wind which overweaves (which lines) the sky as with a thick lining; Yalk. ib. 942.—2) pl. <span dir=\"rtl\">רְבִיבִים</span> (b. h.; <a href=\"#\" data-headword=\"רָבַב\">רָבַב</a>, cmp. <a href=\"#\" data-headword=\"רְבִיעָה\">רְבִיעָה</a>) [<i>growth-advancing</i>,] <i>rains</i>. Sifré l. c. (ref. to Deut. l. c.) <span dir=\"rtl\">מה ר׳ הללו יורדים וכ׳</span> as the rains come down on plants &amp;c.; Yalk. l. c. <span class=\"citation\">B. Bath. 25ᵃ</span> (ref. to Deut. l. c.) <span dir=\"rtl\">זו רוח … ר׳ וכ׳</span> that is the south wind which brings rains and makes the plants grow; ib.ᵇ; a. e.</div>","alt":[]},"28313":{"h":"רִבְיָה","r":"T00088","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבָה\">רָבָה</a>) <i>increase, plenty</i>. <span class=\"citation\">Num. R. s. 2</span><sup>12</sup> (ref. to <span dir=\"rtl\">הרבה ארבה</span>, <span class=\"citation\">Gen. XXII, 17</span>) <span dir=\"rtl\">ר׳ לאב ר׳ לבן</span> increase promised to the father, increase to the son.—פריה ור׳ <i>propagation, v.</i> <a href=\"#\" data-headword=\"פִּרְיָה\">פִּרְיָה</a>. <span class=\"citation\">Yeb. 62ᵃ</span>. <span class=\"citation\">Y. Taan. I, 64ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">רִבְיוֹת</span> (or <span dir=\"rtl\">רְבִיֹּות</span>) <i>plentiful discharges</i>. <span class=\"citation\">Ab. d’R. N. ch. I</span> (ref. to <span dir=\"rtl\">הרבה ארבה</span>, <span class=\"citation\">Gen. III, 16</span>) <span dir=\"rtl\">אלו שתי ר׳ דם וכ׳</span> ed. Schechter (Var. <a href=\"#\" data-headword=\"*רִבְעִיּוֹת\">רבעיות</a></div>","alt":["רִבְיָיה"]},"28314":{"h":"רַבְיוּתָא","r":"T00089","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָבֵי\">רָבֵי</a>) <i>youth</i>. <span class=\"citation\">Targ. O. Lev. XXII, 13</span> <span dir=\"rtl\">כרַבְיוּתָהּ</span> (not <span dir=\"rtl\">תָא …</span>, <span dir=\"rtl\">תָה …</span>). <span class=\"citation\">Targ. O. Num. XXX, 4</span> (some ed. <a href=\"#\" data-headword=\"רַבְיוּתָא\">רַבְיוּתָהָא</a>). <span class=\"citation\">Targ. Koh. XI, 9</span>; a. e.—[<span class=\"citation\">Targ. O. Gen. XLIII, 33</span> <span dir=\"rtl\">כרביותיה</span>, v. <a href=\"#\" data-headword=\"רַבּוּתָא\">רַבּוּתָא</a>.—<span class=\"citation\">Targ. Ps. LXXI, 21</span>, v. <a href=\"#\" data-headword=\"רַבָּנוּתָא\">רַבָּנוּתָא</a>.]</div>","alt":[]},"28315":{"h":"רַבְיָיא","r":"T00090","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. II, Ex. XXII, 24</span>, v. <a href=\"#\" data-headword=\"רִבִּית ²\">רִבִּיתָא</a></div>","alt":[]},"28316":{"h":"רִבְיָיה","r":"T00091","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבְיָה\">רִבְיָה</a></div>","alt":[]},"28317":{"h":"רִבְיָין","r":"T00092","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִבִּית ²\">רִבִּיתָא</a></div>","alt":[]},"28318":{"h":"רְבִיכָא","r":"T00093","html":"<div class=\"sense\">, f. ch. = <a href=\"#\" data-headword=\"רְבִיכָה\">next w.</a> <span class=\"citation\">Targ. O. Lev. VI, 14</span>. <span class=\"citation\">Targ. I Chr. XXIII, 29</span>; a. e.</div>","alt":[]},"28319":{"h":"רְבִיכָה","r":"T00094","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רבך</span>, cmp. <a href=\"#\" data-headword=\"רָבַג\">רבג</a>) </div><div class=\"sense\"><b>1)</b> <i>a pulp of flour mixed with hot water and oil</i> (v. <span class=\"citation\">Lev. VII, 12</span>). <span class=\"citation\">Men. 89ᵃ</span> (ref. to Lev. l. c.) <span dir=\"rtl\">יכול יהא חצי … ולר׳</span> lest you think that the half Log of oil is to be equally distributed among the cakes, the wafers, and the pulp; <span dir=\"rtl\">כשהוא אומר בשמן בר׳ ריבה שמן לר׳</span> (Rashi <span dir=\"rtl\">ברְבוּכָה</span>) as the text repeats ‘with oil’ in connection with the pulp, it intimates by the repetition that more oil is required for the pulp. <span class=\"citation\">Y. Snh. XI, 30ᵇ</span>. <span class=\"citation\">Tam. 28ᵇ</span> <span dir=\"rtl\">להחם חמין לר׳</span> (Ar. <span dir=\"rtl\">לרבוכה</span>) to make hot water for the pulp. <span class=\"citation\">Y. Pes. II, 29ᵇ</span> bot.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"רְבוּכָה\">רְבוּכָה</a></div>","alt":[]},"28320":{"h":"*קלידיקוס","r":"S01330","html":"<div class=\"sense\">, prob. to be read: <span dir=\"rtl\">קְלִירַרְכוֹס</span> m. (κλήραρχος) <i>president of a district</i> (higher than the <i>epitropos</i>, and subordinate to the <i>decurio</i>, a member of the senate in provincial municipalities). Mekh. B’shall., Amalek, s. 2; <span class=\"citation\">Yalk. Deut. 813</span> <a href=\"#\" data-headword=\"פליריכוס\">פליריכוס</a>, <a href=\"#\" data-headword=\"פליריכוס\">פלירכוס</a>, prob. <a href=\"#\" data-headword=\"פּוֹלִימַרְכוֹס\">פּוֹלְיַרְכוֹס</a> (πολίαρχος = prefectus urbi).</div>","alt":[]},"28321":{"h":"קָלִיט","r":"S01331","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָלַט\">קָלַט</a>) <i>suction</i>, (with <a href=\"#\" data-headword=\"יָם\">יַם</a> or <a href=\"#\" data-headword=\"יַמָּא\">יַמָּא</a>) <i>gorge</i>. <span class=\"citation\">Y. B. Mets. V, 10ᶜ</span> bot. <span dir=\"rtl\">קָלִיטוֹ של ים</span> (not <span dir=\"rtl\">שלים</span>) the gorge (resorbing the rivers flowing into the sea); trnsf. <i>a certain form of usury</i> (τόκος ναυτικός, fenus nauticum, v. Sm. Ant. 3ʳᵈ ed. London 1890, s. v. Fenus, a. Lübker Reallex. s. v. Ἔμπορος, a. Zinsen), <i>the creditor advancing money on a ship load at his own risk in case of shipwreck</i>, expl. <span class=\"citation\">ib.</span> <span dir=\"rtl\">בר נש דיהיב לחבריה מהו דינרין כגון אילין דיהבין וכ׳</span> if one advances a certain number of Denars to his neighbor in the same manner as those who give goods &amp;c., v. <a href=\"#\" data-headword=\"קסוסטבן\">קסוסטבן</a>.—<i>Pl.</i> (ch.) <span dir=\"rtl\">קְלִיטִין</span>. <span class=\"citation\">Gen. R. s. 5</span> (expl. <span dir=\"rtl\">עד נבכי ים</span>, <span class=\"citation\">Job XXXVIII, 16</span>) <span dir=\"rtl\">עד ק׳ דימא</span> (some ed. <span dir=\"rtl\">קְלוּטִין</span>) to the gorges of the sea; <span class=\"citation\">Yalk. Ps. 848</span> <a href=\"#\" data-headword=\"קטלא\">קטלא</a> (read: <span dir=\"rtl\">קָלִיטָא</span> or <a href=\"#\" data-headword=\"קָלְטָא\">קָלְטָא</a>).</div>","alt":[]},"28322":{"h":"קְלִיטָה","r":"S01332","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָלַט\">קָלַט</a>) </div><div class=\"sense\"><b>1)</b> <i>receiving, offering an asylum</i>. <span class=\"citation\">Macc. 13ᵃ</span> <span dir=\"rtl\">מר סבר לכם לק׳ וכ׳</span> one scholar is of the opinion, ‘unto you’ (<span class=\"citation\">Num. XXXV, 12</span>) means yours merely as an asylum (<a href=\"#\" data-headword=\"מִקְלָט\">מקלט</a>, where the refugees have to support themselves), the other is of the opinion, ‘yours’ for all your needs.—2) (of a graft) <i>taking root</i>. <span class=\"citation\">R. Hash. 10ᵇ</span></div>","alt":[]},"28323":{"h":"קליטה","r":"S01333","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 14</span>, v. <a href=\"#\" data-headword=\"קִלְטָא\">קִלְטָא</a></div>","alt":["קליטי"]},"28324":{"h":"קָלִיל","r":"S01334","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קוֹלָא I\">קוֹלָא</a>) [<i>something hollow</i>,] <i>receptacle</i>. <span class=\"citation\">Men. 66ᵇ</span>, v. <a href=\"#\" data-headword=\"קָלִי\">קָלִי</a>.—Pl. (of <a href=\"#\" data-headword=\"קְעִילִית\">קְלִילִית</a>) <span dir=\"rtl\">קְלִילִיּוֹת</span>. <span class=\"citation\">Tosef. Par. III</span> (<span class=\"citation\">II), 4</span>, v. <a href=\"#\" data-headword=\"קָלָל\">קָלָל</a>.</div>","alt":[]},"28325":{"h":"קַלִּיל I","r":"S01335","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קַלִּיל II\">next w.</a>) <i>a little, a short while</i>. <span class=\"citation\">Targ. Y. Gen. XXIV, 17</span> (ed. Amst. <a href=\"#\" data-headword=\"קְלַל\">קַלֵּיל</a>). <span class=\"citation\">Targ. Prov. VI, 10</span>. <span class=\"citation\">Ib. XV, 16</span> (ed. Wil. <a href=\"#\" data-headword=\"קַרְתָּא\">קָ׳</a>). <span class=\"citation\">Ib. XVI, 8</span> (ed. Wil. <a href=\"#\" data-headword=\"קַלִּיל I\">קָלֵיל</a>). <span class=\"citation\">Ib. V, 14</span> (not <a href=\"#\" data-headword=\"כ׳\">כ׳</a>). <span class=\"citation\">Targ. Y. Ex. XVII, 4</span>; a. fr.—<span class=\"citation\">Koh. R. to III, 9</span> <span dir=\"rtl\">עביד עימיה אויר ק׳</span> he spent with him a short moment of rest.</div>","alt":[]},"28326":{"h":"קַלִּיל II","r":"S01336","html":"<div class=\"sense\"> c. = h. <a href=\"#\" data-headword=\"קַל I\">קַל</a>, </div><div class=\"sense\"><b>1)</b> <i>light of weight; quick</i>. <span class=\"citation\">Targ. II Sam. II, 18</span>. <span class=\"citation\">Targ. Prov. XIX, 2</span> (ed. Wil. <a href=\"#\" data-headword=\"קַלִּיל I\">קָלֵיל</a>). <span class=\"citation\">Targ. Jer. II, 23</span>; a. fr.—<span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">חייא ק׳ ממיתא</span> a live body is lighter than a dead one. <span class=\"citation\">Ḥull. 16ᵇ</span> <span dir=\"rtl\">בעופא דק׳</span> in the case of a bird, which is of light weight. <span class=\"citation\">Snh. 46ᵇ</span> כמאן דאמר ק׳ לי עלמא Ms. M. (ed. <a href=\"#\" data-headword=\"קִיל I\">קִיל</a>) as one says, the world is light to me (meaning to say, I feel heavy); Y. ib. VI, 23ᵈ bot., v. <a href=\"#\" data-headword=\"קָלַל\">קָלַל</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>slight, of little esteem; little, small</i> (in numbers); <i>easy</i>. <span class=\"citation\">Targ. Y. Ex. XVIII, 22</span> (ed. Amst. <a href=\"#\" data-headword=\"קוֹלְבּוֹן\">קָלִ׳</a>). <span class=\"citation\">Targ. Lam. III, 28</span>. <span class=\"citation\">Targ. Jer. III, 9</span> (h. text <span dir=\"rtl\">קֹל</span>!). <span class=\"citation\">Targ. II Kings III, 18</span>. <span class=\"citation\">Targ. Y. Gen. XXIV, 15</span>; a. fr.—<span class=\"citation\">B. Kam. 6ᵇ</span>, v. <a href=\"#\" data-headword=\"לִישָׁן\">לִישָׁן</a>. Y. Nidd. I, 49ᶜ top <span dir=\"rtl\">הדא … ק׳ וכ׳</span> the opinion of R. M. is more lenient than that of R. J.; a. e.—Pl. <span dir=\"rtl\">קַלִּילִין</span>, <span dir=\"rtl\">קַלִּילַיָּא</span>; <a href=\"#\" data-headword=\"קַלִּיל II\">קַלִּילָן</a>, <a href=\"#\" data-headword=\"כְּרִיסְפָּא\">קְ׳</a>. <span class=\"citation\">Targ. Is. XVIII, 2</span>. <span class=\"citation\">Targ. Lam. IV, 19</span>. <span class=\"citation\">Targ. II Chr. XXIX, 34</span>. <span class=\"citation\">Targ. Y. Lev. XIV, 32</span>; a. fr.—<span class=\"citation\">Koh. R. to I, 18</span> <span dir=\"rtl\">אכל מלין ק׳</span> he ate light things (easy to digest), opp. <span dir=\"rtl\">בורין</span> coarse things.</div>","alt":["קַלִּילָא","קְלִ׳"]},"28327":{"h":"קַלִּילוּ","r":"S01337","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַלִּיל II\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>lightness, rapidity</i>. <span class=\"citation\">Targ. Zech. V, 7</span>; <span class=\"citation\">9</span>. <span class=\"citation\">Targ. Y. Gen. XXIX, 1</span>.</div><div class=\"sense\"><b>—2)</b> <i>a little</i>. Ib. XLIII, 2, v. <a href=\"#\" data-headword=\"קַלִּיל I\"><span dir=\"rtl\">קַלִּיל</span> I</a>.</div>","alt":["קַלִּילוּתָא"]},"28328":{"h":"קלינטרין","r":"S01338","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*קְלִיבִּינִטִירִין\">קְלִבִּינְטִירִין</a></div>","alt":[]},"28329":{"h":"קְלִיסְטַנְרִ־","r":"S01339","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corrupt. of questionarius) <i>executioner</i>. <span class=\"citation\">Ab. Zar. 18ᵃ</span> Ms. M., v. <a href=\"#\" data-headword=\"קָלַסְטוֹר\">קָלַסְטוֹר</a>.</div>","alt":[]},"28330":{"h":"קליסטרא","r":"S01340","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 123ᵇ</span> Ar., v. <a href=\"#\" data-headword=\"קְלוֹסְטְרָא\">קְלוֹסְטְרָא</a></div>","alt":[]},"28331":{"h":"קְלִיסְטְרִין","r":"S01341","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*קְלוּסַנְטְרִין\">קְלוּסַנְטְרִין</a></div>","alt":[]},"28332":{"h":"קְלִיסְיָיא","r":"S01342","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḳ’lisia</i> (?). <span class=\"citation\">Y. Gitt. IV, 46ᵃ</span></div>","alt":[]},"28333":{"h":"קְלִיעָא","r":"S01343","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִיעֲתָא\">קְלִיעֲתָא</a>.—[<span class=\"citation\">Erub. 63ᵇ</span> ed. Cost., v. <span dir=\"rtl\">קִלְעָא I</span>.]</div>","alt":[]},"28334":{"h":"קְלִיעָה","r":"S01344","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (קָלַע II) <i>twist, network; screen</i>. <span class=\"citation\">Y. Shek. VIII, 51ᵇ</span> top <span dir=\"rtl\">אילו אמר חוט … ק׳ שלשה וכ׳</span> if the text (<span class=\"citation\">Ex. XXVI, 31</span>) had the word <i>ḥuṭ</i>, it would mean a double thread, if <i>ḳ’liʿah</i>, a triple thread &amp;c. <span class=\"citation\">Y. Succ. III, 53ᶜ</span> bot.; Sifra Emor Par. 12, ch. XVI, v. <a href=\"#\" data-headword=\"עָבוֹת\">עָבוֹת</a>. <span class=\"citation\">Yoma 67ᵇ</span> (expl. <span dir=\"rtl\">קלען במקלעות</span>, Mish. <span class=\"citation\">ib. VI, 7</span>) <span dir=\"rtl\">כמין ק׳</span> he intertwined the limbs of the animals so as to form a network. <span class=\"citation\">Y. Taan. II, 65ᵇ</span> top (in Chald. dict.), v. <a href=\"#\" data-headword=\"*עַבְיָא\">עַבְיָא</a>.—Trnsf. <i>band, league</i>. <span class=\"citation\">Pesik. R. s. 33</span> (ref. to <span dir=\"rtl\">עבתים</span>, <span class=\"citation\">Ez. XXXI, 3</span>) <span dir=\"rtl\">משעה … ק׳ אחת להכעיס וכ׳</span> as soon as the whole world became one league to provoke the Lord, he (Ashur) left their council &amp;c.—Pl. <span dir=\"rtl\">קְלִיעוֹת</span>. <span class=\"citation\">Eduy. III, 4</span> <span dir=\"rtl\">כל הק׳ וכ׳</span> all networks (woven sheets) are clean &amp;c. <span class=\"citation\">Yalk. Num. 713</span>, v. <a href=\"#\" data-headword=\"קוֹלְיָינִין\">קוֹלְיָינִין</a>.</div>","alt":[]},"28335":{"h":"קְלִיעֲתָא","r":"S01345","html":"<div class=\"sense\">, <i>network, plait</i>; also <i>carved relief work</i>. <span class=\"citation\">Targ. Y. Ex. XXVIII, 14</span>; <span class=\"citation\">22</span> (h. text <a href=\"#\" data-headword=\"עֲבוֹת\">עֲבֹת</a>).—Y. Sot. IX, end, 24ᶜ, v. <a href=\"#\" data-headword=\"מַקְלִיעֲתָא\">מַקְלִיעֲתָא</a>. <span class=\"citation\">Y. Snh. VII, end, 25ᵈ</span> <span dir=\"rtl\">בקַלְעִיתָא דשערה</span> by the plait of her hair; a. e.—Pl. <a href=\"#\" data-headword=\"קְלִיעָא\">קְלִיעָן</a>, <a href=\"#\" data-headword=\"קְלִיעֲתָא\">קְלִיעָתָא</a>, <a href=\"#\" data-headword=\"קַלְעִיתָא\">קַלְעֲיָתָא</a>. <span class=\"citation\">Targ. Y. Ex. XXVIII, 24</span>, sq. <span class=\"citation\">Targ. I Kings VI, 29</span>; <span class=\"citation\">32</span>. <span class=\"citation\">Ib. VII, 31</span> <span dir=\"rtl\">קְלִיעִין</span>.—<span class=\"citation\">Sabb. 95ᵃ</span>; <span class=\"citation\">Ber. 61ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"בִּנְיָיתָא\">בִּנְיָיתָא</a>; <span class=\"citation\">Gen. R. s. 18</span>, beg. <a href=\"#\" data-headword=\"קַלְעִיתָא\">קִלְעָתָא</a>; a. e.</div>","alt":["קְלִיעָא","קִלְעֲתָא"]},"28336":{"h":"קְלֵיף","r":"S01346","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלַף\">קְלַף</a></div>","alt":[]},"28337":{"h":"קְלִיפָא","r":"S01347","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַלְפָא\">קלְפָא</a>, <a href=\"#\" data-headword=\"קְלוּפִיתָא\">קְלוּפִיתָא</a>, a. <a href=\"#\" data-headword=\"קְלִיפָה\">next w.</a></div>","alt":["קַלִּי׳"]},"28338":{"h":"קְלִיפָה","r":"S01348","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָלַף\">קָלַף</a>) </div><div class=\"sense\"><b>1)</b> <i>peeling, scaling</i>. <span class=\"citation\">Pes. 76ᵃ</span> <span dir=\"rtl\">סגי ליה בק׳</span> it is sufficiently remedied by paring the surface. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ מיהא ניבעי</span> let it at least be pared; a. e.</div><div class=\"sense\"><b>—2)</b> <i>scale, husk, skin</i>. <span class=\"citation\">Snh. 95ᵇ</span> <span dir=\"rtl\">שריון ק׳</span> (= <span dir=\"rtl\">ש׳ קשקשים</span>, <span class=\"citation\">I Sam. XVII, 5</span>) a scaly coat of mail. <span class=\"citation\">Nidd. III, 2</span>; <span class=\"citation\">Tosef. ib. IV, 2</span> <span dir=\"rtl\">המפלת מין ק׳</span> an abortion that has the appearance of a mass of membranes. Ohol. VI, 5, sq. <span dir=\"rtl\">כקְלִיפַת השום</span> as thin as the husk of garlic. <span class=\"citation\">Ab. Zar. 76ᵃ</span> <span dir=\"rtl\">עד שתשיר קְלִיפָתָן</span> until the crusty accretion of the vessels falls off (by exposure to heat); a. fr.—<span class=\"citation\">Bekh. 58ᵃ</span> <span dir=\"rtl\">כל … כק׳ השום וכ׳</span> all Jewish scholars appear to me (as paltry) as the husk of garlic, except &amp;c.—[<span class=\"citation\">Gen. R. s. 82</span> <span dir=\"rtl\">קליפת בצלים</span>, v. <a href=\"#\" data-headword=\"קְלַף\">קְלַף</a>.]—Pl. <span dir=\"rtl\">קְלִיפוֹת</span>, <span dir=\"rtl\">קְלִיפִים</span>, <span dir=\"rtl\">קְלִיפין</span>. <span class=\"citation\">Tosef. Nidd. IV, 3</span> <span dir=\"rtl\">כמין קליפין אדומין</span> (masc.); <span dir=\"rtl\">כמין קליפות אדומות</span> the appearance of red membranes. <span class=\"citation\">Cant. R. to VI, 11</span> <span dir=\"rtl\">מה אגוז … שתי ק׳ וכ׳</span> as the nut has two shells &amp;c. <span class=\"citation\">Sabb. IX, 5</span> <span dir=\"rtl\">קְלִיפֵי רמונים</span> shells of pomegranates. <span class=\"citation\">Y. Ter. V, end, 43ᵈ</span> <span dir=\"rtl\">קילפי איסור</span> (read: <span dir=\"rtl\">קליפי</span>) shells of forbidden fruits. <span class=\"citation\">Num. R. s. 12</span>, v. <a href=\"#\" data-headword=\"קֶטֶב\">קֶטֶב</a>; a. e.—<span class=\"citation\">Pes. 112ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">מאן דמדרך אקליפים</span> (some ed. <span dir=\"rtl\">אקְלִיפַיָּא</span>; Ms. M. <span dir=\"rtl\">אקליפי דבצים</span>) he that treads on egg-shells.—[In later mystic literature <a href=\"#\" data-headword=\"קְלִיפָה\">קליפה</a>, pronounced <a href=\"#\" data-headword=\"קְלִיפָה\">קְלִיפָּה</a>, a certain <i>class of demons</i>, cmp. Num. R. l. c.]</div>","alt":[]},"28339":{"h":"קליקין","r":"S01349","html":"<div class=\"sense\">, <span class=\"citation\">Y. Naz. VI, 55ᵇ</span> top, v. <a href=\"#\" data-headword=\"קִילְקִי\">קִילְקִי</a></div>","alt":[]},"28340":{"h":"*קְלִירוֹס","r":"S01350","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κλῆρος) <i>lot, destiny</i>. <span class=\"citation\">Midr. Till. to Ps. X, 10</span> אין הרשע מפיל בק׳ שלו וכ׳ Rashi to Ps. l. c. (ed. <span dir=\"rtl\">בקולרים</span>, ed. Bub. <span dir=\"rtl\">בקילורין</span>, corr. acc.) the wicked man involves in his own evil destiny none but wicked strong men like himself (ref. to <span class=\"citation\">Dan. III, 20</span>).—Pl. <span dir=\"rtl\">קְלִירוֹסִין</span>, <span dir=\"rtl\">קְלִירְסִין</span>. <span class=\"citation\">Gen. R. s. 58</span> (ref. to <a href=\"#\" data-headword=\"חֶבְרוֹן\">חברון</a> and <span dir=\"rtl\">קרית ארבע</span>) <span dir=\"rtl\">שהוא עולה בקרסין של וכ׳</span> (some ed. a. Matt. K. <span dir=\"rtl\">בקרנסין</span>, Ar. <span dir=\"rtl\">בקורנס׳</span>, ‘Rashi’ <span dir=\"rtl\">בקינסרין</span>; corr. acc.) for Hebron came up in the lot of (was in turn assigned to) four owners, first to Judah &amp;c. Lam. R. introd. (R. Abbahu 2) <span dir=\"rtl\">בשעה שהפלתי קלבסים וכ׳</span> Ar. (ed. <span dir=\"rtl\">קלסים</span>, read <span dir=\"rtl\">קלירסים</span>) when I cast lots upon the nations to exile them &amp;c. (ref. to <span class=\"citation\">Ez. XXIV, 6</span> <a href=\"#\" data-headword=\"גּוֹרָל\">גורל</a>); <span class=\"citation\">Yalk. Ez. 363</span> <span dir=\"rtl\">קלווסי׳</span> (corr. acc.).</div>","alt":[]},"28341":{"h":"קלירוס","r":"S01351","html":"<div class=\"sense\">, a word in an incantation. <span class=\"citation\">Yoma 84ᵃ</span>, v. <a href=\"#\" data-headword=\"כנתי\">כנתי</a></div>","alt":["קלו׳","קליריס"]},"28342":{"h":"קָלִישׁ","r":"S01352","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלַשׁ\">קְלַשׁ</a></div>","alt":["קְלִישָׁא","קַלִּ׳"]},"28343":{"h":"קָלָל","r":"S01353","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קָלִיל\">קָלִיל</a>) <i>a vessel</i>, esp. <i>the pitcher containing the ashes of the red cow</i>. <span class=\"citation\">Par. III, 3</span>; <span class=\"citation\">X, 3</span> <span dir=\"rtl\">ק׳ של חטאת</span> the vessel containing the ashes for lustration; <span class=\"citation\">Tosef. ib. IX</span> (<span class=\"citation\">X), 5</span>; a. e.—Pl. <span dir=\"rtl\">קְלָלוֹת</span>. <span class=\"citation\">Par. X, 4</span>. <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">II), 4</span> <span dir=\"rtl\">קְלִילִיּוֹת</span> (Var. <a href=\"#\" data-headword=\"קלולי\">קלולי</a>; R. S. to <span class=\"citation\">Par. III, 3</span> <a href=\"#\" data-headword=\"קילולות\">קילולות</a>, corr. acc.).</div>","alt":[]},"28344":{"h":"קָלָל ²","r":"S01354","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Num. XIX, 9</span>.</div>","alt":[]},"28345":{"h":"קָלַל","r":"S01355","html":"<div class=\"sense\"> (b. h.) [<i>to swing</i>] <i>to be light, slender, unimportant</i>.—Part. <a href=\"#\" data-headword=\"קַל I\">קַל</a>. <span class=\"citation\">Snh. VI, 5</span> (ref. to <span dir=\"rtl\">קללת</span>, <span class=\"citation\">Deut. XXI, 23</span>) <span dir=\"rtl\">בזמן … קַלַּנִי מראשי וכ׳</span> when man suffers punishment, what does the Shekhinah say? ‘I am lighter than my head, than my arm’ (euphem. for, I feel my head heavy &amp;c.); Y. ib. 23ᵈ bot. <span dir=\"rtl\">אנן תנינן קַלֵּינִי</span> (= <span dir=\"rtl\">קל איני</span>) we read <i>ḳalleni</i>, I am not lighter; <span dir=\"rtl\">אית תניי תני קל אני</span> some Tannai reads <i>ḳal ăni</i>; <span dir=\"rtl\">מאן דאמר קליני לית הוא אלא קליל</span> according to him that reads <i>ḳalleni</i>, it is a euphemistic expression for ‘light’ (i.e. my head is light, I feel giddy; my arm is light, I feel weak); <span dir=\"rtl\">מאן דאמר קלני … נטיל</span> according to the version <i>ḳallani</i>, it is a euphemistic expression for ‘heavy’ (i.e. my head, my arm is heavy); Bab. ib. 46ᵇ Abbayi says <span dir=\"rtl\">כמאן דאמר קל לית</span> (read <i>ḳalleni</i>) as one says, ‘light (I am) not’ (i.e. I feel heavy, without euphemism)—(which is refuted by Raba, who explains the word in question) <span dir=\"rtl\">קליל לי עלמא</span>, v. <a href=\"#\" data-headword=\"קַלִּיל II\"><span dir=\"rtl\">קַלִּיל</span> II</a>.</div><div class=\"sense\"><b>Hif. הֵיקַל  הֵקַל</b> <div class=\"sense\">, <span dir=\"rtl\">הֵקיל I</span>) <i>to lighten</i>. <span class=\"citation\">M. Kat. 17ᵇ</span> <span dir=\"rtl\">הכביד … מֵיקַל וכ׳</span> if the mourner’s hair is too heavy, he may make it lighter with a razor; Y. ib. III, 82ᵃ top. <span class=\"citation\">Erub. IV, 9</span> <span dir=\"rtl\">להָקֵל על העשיר</span> to make it easy for the rich man; a. fr.—Trnsf. <span dir=\"rtl\">ה׳ ראשו</span> <i>to be irreverent, talk frivolously</i> (v. <a href=\"#\" data-headword=\"קַלּוּת\">קַלּוּת</a>). <span class=\"citation\">Ber. IX, 5</span> <span dir=\"rtl\">לא יָקֵל אדם את ראשו כנגד וכ׳</span> man (a pilgrim coming to Jerusalem) must not behave irreverently in sight of the eastern gate &amp;c. <span class=\"citation\">Yalk. Gen. 24</span> <span dir=\"rtl\">מֵיקֶלֶת ראשה</span> she is frivolous (light-minded); <span class=\"citation\">Yalk. Is. 265</span> <span dir=\"rtl\">מֵקֶילֶת ראש</span>; (<span class=\"citation\">Gen. R. s. 18</span> <span dir=\"rtl\">מיקרת</span>, v. <a href=\"#\" data-headword=\"יָקַר\">יָקַר</a>).—2) <i>to be lenient; to incline towards the less restrictive practice</i>, opp. <a href=\"#\" data-headword=\"חָמַר I\">החמיר</a>, v. <a href=\"#\" data-headword=\"חָמַר I\"><span dir=\"rtl\">חָמַר</span> I</a>. Y. M. Kat. l. c. <span dir=\"rtl\">הלכה כדברי מי שהוא מיקל</span> the adopted practice follows the opinion of him who is more lenient; <span class=\"citation\">Erub. 46ᵃ</span>, a. fr. <span dir=\"rtl\">כדברי המיקל וכ׳</span>. <span class=\"citation\">Yeb. 88ᵃ</span> <span dir=\"rtl\">הֵיקַלְתָּ עליה</span>, v. <a href=\"#\" data-headword=\"חָמַר I\"><span dir=\"rtl\">חָמַר</span> I</a>. <span class=\"citation\">Pes. 52ᵇ</span>, v. <a href=\"#\" data-headword=\"מַגִּיד\">מַגִּיד</a>. Erub. l. c. wherever you find <span dir=\"rtl\">יחיד מיקל ורבים וכ׳</span> an individual scholar favoring the more lenient practice against several in favor of restriction. <span class=\"citation\">Sabb. 129ᵃ</span>, a. fr. <span dir=\"rtl\">ספק נפשות להָקל</span> where there is a doubt involving the endangering of human life, the more lenient rule is applied; a. fr.—3) <i>to be sparing, beggarly</i>. Ib. <span dir=\"rtl\">כל המיקל … מְקִילִין לו מזוניתיו וכ׳</span> he that stints himself at the meal taken after blood-letting, to him they in heaven will give his sustenance stintingly; a. e.</div></div><div class=\"sense\"><b>Pi. קִלֵּל</b> <div class=\"sense\"> [<i>to diminish</i>,] <i>to curse</i>. <span class=\"citation\">Keth. VII, 6</span> <span dir=\"rtl\">מְקַלֶּלֶת</span>, v. <a href=\"#\" data-headword=\"יוֹלֵד\">יִוֹלֵד</a>. <span class=\"citation\">Sabb. 62ᵇ</span> <span dir=\"rtl\">שאשתו מְקַלַּלְתּוֹ בפניו</span> whom his wife curses in his presence. <span class=\"citation\">Pes. 87ᵇ</span> (ref. to <span class=\"citation\">Prov. XXX, 10</span> sq.) <span dir=\"rtl\">אפו׳ דור שאביו יְקַלֵּל וכ׳</span> even if it be a generation of men that curse their father …, do not denounce &amp;c. <span class=\"citation\">Yoma 75ᵃ</span> ק׳ את הנחש וכ׳ God cursed the serpent, yet it climbs up the roof and finds its food. <span class=\"citation\">Sot. 11ᵃ</span> (expl. <span dir=\"rtl\">ועלה</span>, <span class=\"citation\">Ex. I, 10</span>, as euphem. for <span dir=\"rtl\">ועלינו</span>) <span dir=\"rtl\">כאדם שמְקַלֵּל את עצמו וכ׳</span> like a man that wants to curse himself (express an ill omen about himself), and hangs his curse on others. <span class=\"citation\">B. Bath. 88ᵇ</span> <span dir=\"rtl\">הקב&quot;ה בירך … וקִלְּלָן וכ׳</span> the Lord blessed Israel with the twenty-two letters of the alphabet (from <a href=\"#\" data-headword=\"א\">א</a> of <span dir=\"rtl\">אם</span>, <span class=\"citation\">Lev. XXVI, 3</span>, to <a href=\"#\" data-headword=\"ת\">ת</a> of <span dir=\"rtl\">קוממיות</span>, <span class=\"citation\">ib. 13</span>), and cursed them with eight letters (from <a href=\"#\" data-headword=\"ו\">ו</a> of <span dir=\"rtl\">ואם</span>, ib. 14, to <span dir=\"rtl\">ם</span> of <span dir=\"rtl\">נפשם</span>, ib. 43). <span class=\"citation\">Snh. 70ᵃ</span> <span dir=\"rtl\">מתוך שקלקלו … קִלְּלוֹ ברביעי</span> because Ham injured him by (preventing his begetting) a fourth son, he (Noah) cursed him by his fourth son (Canaan). <span class=\"citation\">Ib. 91ᵇ</span> <span dir=\"rtl\">כל המונע … שבמעי אמן מְקַלְּלִין אותו</span> (not <span dir=\"rtl\">אמו</span>) he that withholds a tradition from his pupil, even the embryos in their mother’s womb will curse him; <span class=\"citation\">Yalk. Prov. 947</span>; a. fr.</div></div><div class=\"sense\"><b>Nithpa. נִתְקַלֵּל</b> <div class=\"sense\"><i>to be cursed</i>. <span class=\"citation\">Ber. 61ᵃ</span> <span dir=\"rtl\">בתחלה נ׳ … נִתְקַלְּלָה וכ׳</span> the serpent was cursed first, and then Eve &amp;c.; <span class=\"citation\">Gen. R. s. 20</span>; <span class=\"citation\">Erub. 18ᵃ</span>. <span class=\"citation\">Ib. 18ᵇ</span> <span dir=\"rtl\">נתקללה בבל נִתְקַלְּלוּ וכ׳</span> when Babylon was cursed, her neighbors were cursed. <span class=\"citation\">Bekh. 8ᵃ</span> <span dir=\"rtl\">אם מבהמה נתקללה וכ׳</span> if she (Eve) was cursed (with prolonged pregnancy) more than cattle &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ הוא … אחת לשבע</span> it (the serpent) was cursed seven times more than certain cattle. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ הוא מחיה</span> (not <a href=\"#\" data-headword=\"קִלְקֵל\">נתקלקל</a>); a. fr.—[<span class=\"citation\">Tosef. Sot. II, 3</span> <span dir=\"rtl\">ניקללה ניוולה</span>, Var. <span dir=\"rtl\">ניקל</span>, read: <span dir=\"rtl\">ניקתה בניוולה</span>, v. <a href=\"#\" data-headword=\"נקי\">נָקָה</a> <i>Nif.</i>]</div></div>","alt":[]},"28346":{"h":"קְלַל","r":"S01356","html":"<div class=\"sense\"><b>1)</b> <i>to be light; to be of light esteem</i>. <span class=\"citation\">Targ. O. Gen. XVI, 4</span>, sq.</div><div class=\"sense\"><b>—2)</b> <i>to be reduced</i>. Ib. VIII, 8; 11 <span dir=\"rtl\">קַלּוּ</span> ed. Berl. (ed. Vien. <a href=\"#\" data-headword=\"קַלִּילוּ\">קַלִּיאוּ</a>).</div><div class=\"sense\"><b>Ithpol. אִתְקוֹלָל</b> <div class=\"sense\"><i>to be reduced</i>. Targ. Y. ib.</div></div><div class=\"sense\"><b>Pa. קַלֵּיל</b> <div class=\"sense\"><b>1)</b>  (denom. of (denom. of <a href=\"#\" data-headword=\"קַלִּיל I\">קַלִּיל</a>) <i>to be quick, to pass swiftly</i>. <span class=\"citation\">Targ. Job VII, 6</span>; <span class=\"citation\">IX, 25</span>.</div><div class=\"sense\"><b>—2)</b> <i>to make light</i>; trnsf. <i>to ease, relieve</i>. Pesik. B’shall., p. 93ᵃ <span dir=\"rtl\">קַלֵּיל גרמך וכ׳</span> make thyself light of weight, or I will throw thee off.—Y. Kidd. II, 62ᵈ bot. <span dir=\"rtl\">הוון מחמרין וק׳ עליהון</span> they were strict in their practice, and he lightened their burden (allowed them what they considered forbidden). Y. M. Kat. III, 82ᵃ <span dir=\"rtl\">הן דהוינן סברין דו מְקַלְּלָה חמר</span> he whom we thought to be lenient made it stricter; a. e.—[<span class=\"citation\">Yalk. Gen. 133</span> <span dir=\"rtl\">ומקללה בשוק</span>, v. <a href=\"#\" data-headword=\"קְלַק\">קְלַק</a>.]</div></div><div class=\"sense\"><b>Af. אַקֵּיל  אָקֵיל</b> <div class=\"sense\"><b>1)</b> <i>to disregard, dishonor</i>; also <i>to curse</i>. <span class=\"citation\">Targ. Ex. XXII, 27</span> (v. <a href=\"#\" data-headword=\"קִיל II\"><span dir=\"rtl\">קִיל</span> II</a>). <span class=\"citation\">Targ. Ps. LV, 13</span> (h. text <span dir=\"rtl\">חרף</span>); a. e.—Y. Bicc. III, 65ᵈ top <span dir=\"rtl\">ר׳ מני מֵיקיל לאילין וכ׳</span> R. M. spoke with disrespect of those that get appointments to office for money; Midr. Sam. ch. VII <span dir=\"rtl\">ר׳ אמי הוה מֵקֵיל</span> (or <a href=\"#\" data-headword=\"מַקֵּל\">מַקֵּיל</a>). Y. Dem. I, 22ᵃ top, v. <a href=\"#\" data-headword=\"קִיל II\"><span dir=\"rtl\">קִיל</span> II</a>. Y. Peah VIII, 21ᵃ <span dir=\"rtl\">אַקְלוּנָךְ</span> they cursed thee; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to relieve, to favor the more lenient rule</i>. <span class=\"citation\">Targ. Ex. XVIII, 22</span> (some ed. O. <span dir=\"rtl\">וְיִקְלוּן</span>, read <span dir=\"rtl\">וְיַ׳</span>). <span class=\"citation\">Targ. I Kings XII, 4</span>; <span class=\"citation\">9</span>.—<span class=\"citation\">Erub. 46ᵃ</span> <span dir=\"rtl\">באבילות הוא דאַקִּילוּ וכ׳</span> (or <span dir=\"rtl\">דַּאֲקִילוּ</span>) only as to mourning ceremonies the Rabbis adopt the more lenient rules. <span class=\"citation\">Yeb. 88ᵃ</span> <span dir=\"rtl\">ולא לֵיקֵיל</span>, or <a href=\"#\" data-headword=\"חַמָּר I\"><span dir=\"rtl\">חֲמַר</span> I</a>; a. fr.—V. <a href=\"#\" data-headword=\"קַלְקֵל\">קַלְקֵל</a>.</div></div>","alt":[]},"28347":{"h":"קְלָלָה","r":"S01357","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קְלַל\">preced.</a>) <i>dishonor; curse</i>. <span class=\"citation\">B. Mets. 75ᵇ</span> <span dir=\"rtl\">גורם ק׳ לעצמו</span> brings dishonor upon himself (people believing him to be dishonest). <span class=\"citation\">Meg. 15ᵃ</span>, a. e. <span dir=\"rtl\">אל תהי קִלְלַת הדיוט וכ׳</span> let not the curse of a common man be a slight thing in thy eyes. <span class=\"citation\">Ib. 28ᵃ</span> <span dir=\"rtl\">לא עלתה … קללת חבירי</span> the thought of my neighbor’s curse never went to bed with me (v. <a href=\"#\" data-headword=\"צַעַר ²\">צְעַר</a>). <span class=\"citation\">Sot. 11ᵃ</span> <span dir=\"rtl\">תולה קִלְלָתוֹ וכ׳</span>, v. <a href=\"#\" data-headword=\"קָלַל\">קָלַל</a>. <span class=\"citation\">Yoma 54ᵇ</span> <span dir=\"rtl\">חללו … וקִלְלָתָן ק׳ וכ׳</span> those whose blessing is blessing, and whose curse is curse (whose blessings and curses are efficacious) are engaged in such things!—<span class=\"citation\">Y. Snh. VII, 25ᵃ</span> bot. <span dir=\"rtl\">קיללת השם</span> (usu. <a href=\"#\" data-headword=\"בְּרֵכַת\">ברכת</a>) blasphemy. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מהו לקרוע על קיללת הגוי</span> how about rending one’s garments on hearing blasphemy by a gentile?; a. fr.—Pl. <span dir=\"rtl\">קְלָלוֹת</span>. <span class=\"citation\">Meg. 31ᵇ</span> <span dir=\"rtl\">ק׳ שבתורת כהנים</span> the curses in Leviticus (XXVI, 14-43); <span dir=\"rtl\">שבמשנה תורה</span> the curses in Deuteronomy (XXVIII, 15-68). Ib. <span dir=\"rtl\">שתכלה השנה וקִלְלוֹתֶיהָ</span> that the year and its curses my end together. <span class=\"citation\">Erub. 100ᵇ</span> עשר ק׳ וכ׳ Eve was cursed with ten curses; a. fr.</div>","alt":[]},"28348":{"h":"*קְלַם","r":"S01358","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"*קְלַם\">קַלֵּם</a> (cmp. <span dir=\"rtl\">קרם</span>) <i>to pare off</i>. <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> top <span dir=\"rtl\">חמתה מחלחלה וקַלְּמָה</span> he saw that it (the plaster) was poisoned, and he pared it off; [prob. to be read: <span dir=\"rtl\">וקַלְקָהּ</span>, v. <a href=\"#\" data-headword=\"קְלַק\">קְלַק</a>].</div>","alt":[]},"28349":{"h":"קַלְמָא","r":"S01359","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"קָלָמִין\">קַלְמִין</a>, <span dir=\"rtl\">קַלְמֵי</span>, v. <a href=\"#\" data-headword=\"כַּלְמְתָא\">כַּלְמְתָא</a>.</div>","alt":[]},"28350":{"h":"קלמא","r":"S01360","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ez. XXVII, 17</span>, quot. in Rashi a. l., misreading for <span dir=\"rtl\">קלווא</span>, v. <a href=\"#\" data-headword=\"קוּלְיָא II\"><span dir=\"rtl\">קוּלְיָא</span> I</a></div>","alt":[]},"28351":{"h":"קָלָמוֹס","r":"S01361","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κάλαμος) <i>reed, pen</i>. <span class=\"citation\">Sabb. 80ᵃ</span> Ms. O., v. <a href=\"#\" data-headword=\"קוֹלְמוֹס\">קוֹלְמוֹס</a>.—Pl. <a href=\"#\" data-headword=\"קָלָמִין\">קָלָמִין</a>. <span class=\"citation\">Gen. R. s. 1</span>; Y’lamd. to Num. XXIII, 9, v. <a href=\"#\" data-headword=\"מִילָן\">מִילָן</a>.—<span dir=\"rtl\">קַלְמוֹסִים</span>, v. <a href=\"#\" data-headword=\"קוֹלְמוֹס\">קוֹלְמוֹס</a>.</div>","alt":[]},"28352":{"h":"קלמז","r":"S01362","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַזְיָא\">מַזְיָא</a></div>","alt":["קלמזמסיא","קלמסמסיא"]},"28353":{"h":"קָלָמִין","r":"S01363","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָלָמוֹס\">קָלָמוֹס</a></div>","alt":[]},"28354":{"h":"קלמסמסיא","r":"S01364","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קלמז\">קלמז</a></div>","alt":[]},"28355":{"h":"קלמרים","r":"S01365","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַלְמָרִין\">next w.</a></div>","alt":[]},"28356":{"h":"קַלְמָרִין","r":"S01366","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (καλαμάριον) </div><div class=\"sense\"><b>1)</b> <i>pen-case</i>. <span class=\"citation\">Yalk. Num. 766</span>, v. <a href=\"#\" data-headword=\"מִילָן\">מִילָן</a>.</div><div class=\"sense\"><b>—2)</b> <i>inkstand</i>. <span class=\"citation\">Mikv. X, 1</span> <span dir=\"rtl\">ק׳ הדיוטות וכ׳</span> (read: <span dir=\"rtl\">הדיוטית</span> or <span dir=\"rtl\">של הדיוטות</span>) the inkstand of ordinary men (with a rim bent inside to prevent spilling) does not become clean by immersion until you make a hole in its side; <span dir=\"rtl\">וק׳ של יוסף הכהן וכ׳</span> and the inkstand of Joseph the priest (Josephus Flavius?) had a hole in its side (through which it could be emptied and cleaned). <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> bot. <span dir=\"rtl\">הנייר … ק׳ צריכה</span> paper and pen are considered ornamental objects (with regard to idolatrous decorations on them); as to the inkstand, it is doubtful. <span class=\"citation\">Sabb. 80ᵃ</span> <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">בק׳</a> (Ms. M. <span dir=\"rtl\">בקומרין</span>, ed. Sonc. <span dir=\"rtl\">בקלרין</span>, corr. acc.) forming a letter by dropping ink out of the inkstand.—Pl. <a href=\"#\" data-headword=\"קלמרים\">קַלְמָרִים</a>, <a href=\"#\" data-headword=\"קַלְמָרִין\">קַלְמָרִין</a>. <span class=\"citation\">Kel. II, 7</span> <span dir=\"rtl\">ק׳ המותאמות</span> ed. Dehr. (oth. ed. <span dir=\"rtl\">המתואמות</span>; Ar. <span dir=\"rtl\">המתאמת</span> sing.) a double inkstand (v. Sm. Ant. s. v. Atramentum).</div>","alt":[]},"28357":{"h":"קַלְמְתָא","r":"S01367","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְמְתָא\">כַּלְמְתָא</a></div>","alt":[]},"28358":{"h":"קַלָּן","r":"S01368","html":"<div class=\"sense\"> or <a href=\"#\" data-headword=\"קָלָן\">קָלָן</a>, pl. <span dir=\"rtl\">קַלָּנִים</span>, <span dir=\"rtl\">קַלָּנִין</span>, <a href=\"#\" data-headword=\"קוֹלְבּוֹן\">קָלָ׳</a>, v. <a href=\"#\" data-headword=\"קוֹלָן II\"><span dir=\"rtl\">קוֹלָן</span> II</a>.</div>","alt":[]},"28359":{"h":"קָלָן","r":"S01369","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קָלוֹן I\">קָלוֹן</a>, <i>shame, disgrace, disgraceful deed; nakedness</i>. <span class=\"citation\">Targ. Is. XXII, 18</span>. <span class=\"citation\">Targ. Deut. XXII, 21</span>. <span class=\"citation\">Targ. O. Lev. XX, 18</span>; a. fr.</div>","alt":["קְלָן","קְלָנָא"]},"28360":{"h":"קַלְנְבוֹ","r":"S01370","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḳaln’bo</i> in Babylonia. <span class=\"citation\">Snh. 63ᵇ</span> (Ms. F. a. K. <span dir=\"rtl\">קל נבו</span>, v. Rabb. D. S. a. l. note 50). <span class=\"citation\">Zeb. 96ᵃ</span> <span dir=\"rtl\">שמעיה מק׳</span> (<a href=\"#\" data-headword=\"רַב\">רב</a>) (not <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">בק׳</a>, v. Rabb. D. S. a. l. note 40) (Rab) Sh’maya of Ḳ.; <span class=\"citation\">Yoma 21ᵃ</span> (v. Rabb. D. S. a. l. note 9); <span class=\"citation\">Yalk. Lev. 490</span> (corr. acc.).</div>","alt":[]},"28361":{"h":"קלנדא","r":"S01371","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָלִנְדַּס\">next w.</a></div>","alt":["קלנדה"]},"28362":{"h":"קָלִנְדַּס","r":"S01372","html":"<div class=\"sense\"> c. (calendæ, accus.) <i>kalends</i>, the first day of the Roman month, (applied only to the kalendæ Januariæ) <i>the Roman New Year</i>. <span class=\"citation\">Ab. Zar. I, 3</span> (<span class=\"citation\">8ᵃ</span>) <a href=\"#\" data-headword=\"קָלִנְדַּס\">קלנדס</a> Y. ed. (Mish. a. Bab. <a href=\"#\" data-headword=\"קלנדא\">קלנדא</a>). Y. ib. 39ᶜ top <span dir=\"rtl\">ק׳ אדם וכ׳</span> Adam instituted the kalends; <span dir=\"rtl\">כיון דחמא … ק׳ קלון וכ׳</span> when he observed that the days were growing longer, he exclaimed, <i>kalendas</i> &amp;c., v. <a href=\"#\" data-headword=\"*דיאו\">דיאו</a>. Ib. <span dir=\"rtl\">ק׳ יינובריס</span>, v. <a href=\"#\" data-headword=\"יָינוּבְרִיס\">יָינוּבְרִיס</a>. Ib. <span dir=\"rtl\">ק׳ אסורה לכל</span> on the Roman New Year it is forbidden to deal with all gentiles; [oth. opin.] <span dir=\"rtl\">אין אסורה אלא לפלחין בה</span> it is forbidden to deal with those only who worship on it; Bab. ib. 8ᵃ; Tosef. ib. I, 4 <a href=\"#\" data-headword=\"קלנדא\">קלנדא</a> ed. Zuck. (Var. <span dir=\"rtl\">ה …</span>, <span dir=\"rtl\">ס …</span>). Ab. Zar. l. c. <span dir=\"rtl\">ק׳ שמנה ימים אחר וכ׳</span> the New Year takes place eight days after the solstice, the Saturnalia eight days before the solstice; Y. ib. l. c. (corr. acc.). Bab. ib. l. c. <span dir=\"rtl\">רומי שעשתה ק׳ וכ׳</span> (Alf. <a href=\"#\" data-headword=\"*עַיִר\">עיר</a>) if a Roman city (as Cæsaræa) introduced the Roman New Year, and all the townships near her are subject to her rule, are these townships forbidden or not?; a. e.</div>","alt":[]},"28363":{"h":"קָלָנְיָא","r":"S01373","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (colonia) <i>a Roman colony</i> (v. Sm. Ant. s. v. Colonia). <span class=\"citation\">Ab. Zar. 10ᵃ</span> <span dir=\"rtl\">ותתעביד טבריא ק׳</span> and that Tiberias be declared a Roman colony. <span class=\"citation\">Succ. 45ᵃ</span>, v. <a href=\"#\" data-headword=\"מוֹצָא II\"><span dir=\"rtl\">מוֹצָא</span> II</a>; Y. ib. IV, beg. 54ᵇ <a href=\"#\" data-headword=\"קָלוֹנְיָא\">קָלוֹנְיָיא</a>. <span class=\"citation\">Deut. R. s. 10</span> <span dir=\"rtl\">לאיסטרטיגין ששימש … פרס וקלאונה</span> (read <a href=\"#\" data-headword=\"רומי\">רומי</a> for <span dir=\"rtl\">פרס</span>, a corr. acc.) a general that held offices in two provinces, one a Roman province, the other a colony; (Yalk. ib. 942 <span dir=\"rtl\">פרס וק׳</span>, omitted). <span class=\"citation\">B. Bath. 4ᵃ</span> את הורודוס עבדא בישא מתעביד ק׳ Ms. R. (v. Rabb. D. S. a. l. note 70) thou, Herod, being a bad servant (of Rome), (thy country) be declared a colony (an anachronistic allusion to the reduction of Judæa to a Roman province on the banishment of Archelaus).—<span class=\"citation\">Yeb. 115ᵇ</span> <span dir=\"rtl\">בצד קלוניא מתא</span> by the side of the town of Colonia (?).</div>","alt":[]},"28364":{"h":"קַלָּנִיתָא","r":"S01374","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְלַל\">קְלַל</a>) name of <i>a very lean bird, ḳallanitha</i>. <span class=\"citation\">Ḥull. 102ᵇ</span> <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">בק׳</a> such is the case with the ḳ.; <span dir=\"rtl\">והא ק׳ עוף טמא הוא</span> but the ḳ. is an unclean bird?; <span dir=\"rtl\">כעין ק׳</span> a clean bird similar in build to the ḳ.—<span class=\"citation\">B. Bath. 20ᵃ</span> <span dir=\"rtl\">ק׳ לא מסרטא</span> but the ḳ. does not scratch (and a child may play with it)!; <span dir=\"rtl\">כעין ק׳</span></div>","alt":[]},"28365":{"h":"קלניתא","r":"S01375","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִנְתְּיָא\">next w.</a></div>","alt":[]},"28366":{"h":"קְלִנְתְּיָא","r":"S01376","html":"<div class=\"sense\"> c. (Κορίνθιος) <i>Corinthian</i>. <span class=\"citation\">Tosef. Yoma II, 4</span>; <span class=\"citation\">Yoma 38ᵃ</span> <a href=\"#\" data-headword=\"קלוניתא\">קלוניתא</a> (Ms. M. <a href=\"#\" data-headword=\"קלניתא\">קלניתא</a>), v. <a href=\"#\" data-headword=\"נְחוּשְׁתָּן ²\"><span dir=\"rtl\">נְחוּשְׁתָּן</span> I</a>.</div>","alt":[]},"28367":{"h":"קָלַס I","r":"S01377","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"קָלַס I\">קִלֵּס</a> (denom. of <a href=\"#\" data-headword=\"קוֹלָס\">קוֹלָס</a>) <i>to put a helmet on</i>; part. pass. <a href=\"#\" data-headword=\"מְקוּלָּס\">מְקוּלָּס</a> <i>an animal roasted in its entirety with the entrails and legs on the head</i>. <span class=\"citation\">Pes. 74ᵃ</span> R. Ṭarfon called it <span dir=\"rtl\">גדי מ׳</span> a kid with a helmet on. <span class=\"citation\">Tosef. Bets. II, 15</span> <span dir=\"rtl\">איזוהי גדי מ׳ … וקרבו</span> (not <span dir=\"rtl\">בקרבו</span>) what is a <i>g’di m’ḳullas</i>? Entirely roasted, with head, legs, and entrails. Ib. <span dir=\"rtl\">עגל מ׳</span> a calf roasted with the head &amp;c. Ib. Todos taught the Roman Jews to take lambs <span dir=\"rtl\">ועושין אותו מְקוּלָּסִין וכ׳</span> and prepare them ‘helmeted’ on Passover nights.—[<span class=\"citation\">Midr. Till. to Ps. XCII</span> <span dir=\"rtl\">מקולסין</span>, v. <a href=\"#\" data-headword=\"נִיקְלְוָוס\">נִיקְלְוָוס</a>.]</div>","alt":[]},"28368":{"h":"קָלַס II","r":"S01378","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"קָלַס I\">קִלֵּס</a>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a> (denom. of <a href=\"#\" data-headword=\"קוֹל\">קוֹל</a>, <i>Pales</i>) [<i>to shout, make noise</i>,] </div><div class=\"sense\"><b>1)</b> <i>to praise</i>; [b. h. <i>to decry, deride</i>]. <span class=\"citation\">B. Bath. 176ᵃ</span> <span dir=\"rtl\">אע&quot;פ שק׳ ר&quot;י וכ׳</span> although R. Yishm. praised Ben N. (commended his argument) the practice follows his (R. Yishmael’s) opinion; Y. ib. X, end, 17ᵈ <span dir=\"rtl\">על מדרשו קִילְּסוֹ</span> he commended him for his mode of argumentation. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">ניקח … ונְקַלֵּס להקב&quot;ה</span> let us take up the Lulab and Ethrog and offer praise to the Lord. <span class=\"citation\">Midr. Till. to Ps. CXIV</span> (expl. <span dir=\"rtl\">סֹלּוּ</span>, <span class=\"citation\">Ps. LXVIII, 5</span>) <span dir=\"rtl\">קַלְּסוּ</span> (not <span dir=\"rtl\">קילסו</span>) praise him. Ib. <span class=\"citation\">Ps. CIV</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to tramp</i> or <i>clap</i> (in wailing ceremonies or on joyous occasions), v. <a href=\"#\" data-headword=\"קִילּוּס II\"><span dir=\"rtl\">קִילּוּס</span> II</a>, 2; <span class=\"citation\">M. Kat. 27ᵇ</span> <span dir=\"rtl\">המְקַלֵּס לא יְקַלֵּס וכ׳</span> the tramper (at mourning ceremonies) must not tramp with a sandal on his foot, but with a shoe, to avoid accident.</div><div class=\"sense\"><b>Hithpa. הִתְקַלֵּס</b> <div class=\"sense\"><i>to be praised; to be done honor to by song, clapping</i> &amp;c. Y. Ḥag. I, 76ᶜ <span dir=\"rtl\">כשהיה רואה … מִתְקַלְּסִין</span> (not <span dir=\"rtl\">סון …</span>) whenever he saw a deceased person or a bride honored.</div></div>","alt":[]},"28369":{"h":"קְלַס","r":"S01379","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"קָלַס I\">קַלֵּס</a> ch. same, <i>to call out; to praise; to tramp</i>. <span class=\"citation\">Targ. Esth. VI, 9</span>; <span class=\"citation\">11</span> (h. text <span dir=\"rtl\">קרא</span>). <span class=\"citation\">Targ. Y. II, Deut. XXXII, 43</span>. <span class=\"citation\">Targ. Y. II, Ex. XXXII, 18</span>; a. fr.—<span class=\"citation\">Keth. 21ᵇ</span> <span dir=\"rtl\">משום דקַלְּסָהּ … את נמי מְקַלְּסַת לה</span> because thy mother’s father commended it, thou commendest it likewise. <span class=\"citation\">Y. Kil. VIII, 31ᵇ</span>, a. e. <span dir=\"rtl\">והוה … מְקַלֵּס ליה הזלים וכ׳</span> R. J. praised him by applying the verse (<span class=\"citation\">Is. XLVI, 6</span>) &amp;c. Y. Maas. Sh. I, end, 53ᵃ <span dir=\"rtl\">אמרה … וקַלְּסֵיה</span> he said it before R. Abina, and he applauded him, opp. <span dir=\"rtl\">קנתריה</span>; a. e.—Y. Peah I, 15d; Y. Ab. Zar. I, 42ᶜ top <span dir=\"rtl\">מקלס קומי וכ׳</span> did honor to bridal couples (singing, dancing &amp;c.); (<span class=\"citation\">Keth. 17ᵃ</span> <span dir=\"rtl\">מרקד</span>).</div>","alt":[]},"28370":{"h":"קֹלָס","r":"S01380","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוֹלָס\">קוֹלָס</a>, <a href=\"#\" data-headword=\"קוֹלַס\"><a href=\"#\" data-headword=\"קוֹלַס\">קוּלְסָא</a>.</a></div>","alt":["קַלְסָא"]},"28371":{"h":"*קַלָּסָא","r":"S01381","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"קָלַס I\">קָלַס</a>) <i>shouting, derision</i>. <span class=\"citation\">Targ. Ps. XLIV, 14</span> Ms. (ed. <a href=\"#\" data-headword=\"קָלָן\">קלנא</a>).</div>","alt":[]},"28372":{"h":"קָלַסְטוֹר","r":"S01382","html":"<div class=\"sense\"> (better <a href=\"#\" data-headword=\"קְלַסְטֵיר\">קוֹלַסְטֵיר</a>) m. (κολαστήρ) <i>torturer, executioner</i>. <span class=\"citation\">Ab. Zar. 18ᵃ</span> ר׳ חנינא … וּקְלַסְטוֹרוֹ וכ׳ Ar. (ed. <span dir=\"rtl\">וקלצטוניריה</span>; Ms. M. <span dir=\"rtl\">וקלסטינריה</span>, arisen from confusing our w. with <i>questionarius</i>, v. <a href=\"#\" data-headword=\"קוּסְטִינָר\">קוּסְטִינָר</a>, <a href=\"#\" data-headword=\"*קְלוּסַנְטְרִין\">קְלוּסִינְטְרִין</a>) R. Ḥanina … and his executioner are destined to enjoy the happiness of the hereafter. Ib. <span dir=\"rtl\">אמר לו קלצטונירי</span> (Ms. M. <span dir=\"rtl\">קליסטנרי</span>, En Yaʿăk. <span dir=\"rtl\">קליסטנירוֹ</span>, v. Rabb. D. S. a. l. note 60) the (his) executioner said to him.</div>","alt":[]},"28373":{"h":"קְלַסְטוֹרָא","r":"S01383","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלַסְטֵירָא\">קְלַסְטֵירָא</a></div>","alt":[]},"28374":{"h":"קְלַסְטֵיר","r":"S01384","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a transpos. of κάρταλλος, v. <a href=\"#\" data-headword=\"טְרַסְקָל\">טְרַסְקָל</a> a. <a href=\"#\" data-headword=\"קְרַסְטָל\"><a href=\"#\" data-headword=\"קְרַסְטָל\">קְרַסְטָל</a>)</a><i>basket</i>, esp. <i>fodder-basket</i> used instead of a muzzle. <span class=\"citation\">Kel. XX, 1</span> <a href=\"#\" data-headword=\"קְלַסְטֵיר\">קלסטר</a> ed. Dehr. a. Ar. (ed. <a href=\"#\" data-headword=\"קלוסטור\">קלוסטור</a>, <a href=\"#\" data-headword=\"קלוסטור\">קלוסטר</a>; R. H. G. <a href=\"#\" data-headword=\"קְרַסְטָל\">קרסטל</a>); Sifra, M’tsorʿa, Zab., Par. 1, ch. II <a href=\"#\" data-headword=\"קְלַסְטֵיר ²\">קְלַסְתָּר</a>.—Pl. <span dir=\"rtl\">קְלַסְטֵירִין</span>. <span class=\"citation\">Y. Sabb. V, beg. 7ᵇ</span></div>","alt":["קְלַסְטָר I"]},"28375":{"h":"קְלַסְטֵיר ²","r":"S01385","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κρύσταλλος, crystallum) <i>crystal</i>; trnsf. <i>brightness</i>, (with, or sub. <span dir=\"rtl\">פנים</span>; cmp. <a href=\"#\" data-headword=\"זִיו\">זִיו</a>) <i>beauty of features, countenance</i>. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">בשכר … זכה לק׳ פנים</span> as a reward for hiding his face (<span class=\"citation\">Ex. III, 6</span>) he was granted the shining face (<span class=\"citation\">Ex. XXXIV, 29</span> sq.). <span class=\"citation\">Nidd. 31ᵃ</span> <span dir=\"rtl\">והקב&quot;ה נותן … וק׳ פנים וכ׳</span> and God gives it (the embryo) spirit and soul, and beauty of features, and power of sight &amp;c. <span class=\"citation\">B. Mets. 87ᵃ</span> נהפך ק׳ פנים וכ׳ Isaac’s features were changed and made to resemble Abraham’s. <span class=\"citation\">Lev. R. s. 18</span>, beg. (ref. to <span class=\"citation\">Koh. XII, 2</span>) <span dir=\"rtl\">השמש זו ק׳ פ׳</span> ‘the sun (is darkened)’, that means the bright countenance; a. fr.—<i>Pl.</i> (used as sing.) <span dir=\"rtl\">קְלַסְטֵירִין</span>. <span class=\"citation\">Ex. R. s. 28</span>, beg. <span dir=\"rtl\"><span dir=\"rtl\">עשה</span> (<a href=\"#\" data-headword=\"בּוֹ\">בו</a>) <span dir=\"rtl\">הקב&quot;ה ק׳ של פניו … דומה וכ׳</span></span> the Lord made Moses’ features resemble those of Abraham.—[<span class=\"citation\">Snh. 104ᵇ</span> קלסתר Rashi, v. <a href=\"#\" data-headword=\"קְלַסְתָּא\">קְלַסְתָּא</a>.]</div>","alt":["קְלַסְטָר II","קְלַסְתָּר"]},"28376":{"h":"קְלַסְטֵירָא","r":"S01386","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XIV, 20</span> <span dir=\"rtl\">קְלַסְתְּרֵיה</span> (ed. Lag. <a href=\"#\" data-headword=\"קְלַסְתּוֹרָא\">קְלַסְתֵּיר׳</a>; Regia <span dir=\"rtl\">קלסטור׳</span>; h. text <span dir=\"rtl\">פניו</span>). <span class=\"citation\">Ib. XXIX, 24</span> קְלַסְטֵר אַפַּי Ar. (ed. <a href=\"#\" data-headword=\"תּוֹר I\">תּוֹר …</a>; Ms. <span dir=\"rtl\">תַּר …</span>); a. e.—[<span class=\"citation\">Snh. 104ᵇ</span>, v. <a href=\"#\" data-headword=\"קְלַסְתָּא\">קְלַסְתָּא</a>.]—Pl. <span dir=\"rtl\">קְלַסְטֵירִין</span>, <span dir=\"rtl\">קְלַסְתּוֹרִין</span>. <span class=\"citation\">Targ. Job XVII, 7</span> קְלַסְטֵירַי Ms. (ed. <span dir=\"rtl\">קלסתורַי</span>, not <span dir=\"rtl\">רֵי …</span>; h. text <span dir=\"rtl\">יְצֻרַי</span>).</div>","alt":["קְלַסְטְרָא","קְלַסְתּוֹרָא","קְלַסְתְּרָא"]},"28377":{"h":"*קְלַסְרִיקִין","r":"S01387","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Κοιλη-συρικός) <i>Cœlesyrians</i>. <span class=\"citation\">Esth. R. to II, 21</span>, v. <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבָּרִי</a>. V., however, <a href=\"#\" data-headword=\"*קְלוּסַנְטְרִין\">קְלוּסַנְטְרִין</a>.</div>","alt":[]},"28378":{"h":"קְלַסְתָּא","r":"S01388","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (adapt. of γελοιαστής, as if a redupl. of <a href=\"#\" data-headword=\"קְלַס\">קְלַס</a>) <i>jester, dancer, buffoon</i>; <span dir=\"rtl\">ק׳ של מלך</span> <i>King’s fool</i>. <span class=\"citation\">Snh. 104ᵇ</span> Ms. M. (in a passage omitted in ed.; Ar. s. v. <a href=\"#\" data-headword=\"קְלַסְטֵיר\">קלסטר</a>: <span dir=\"rtl\">קלסתרא</span>; Rashi <span dir=\"rtl\">קלסתר</span>; Rev. des Ét. Juives XI, p. 215 קלסטר γελοιαστήρ; Yalk. Lam. 1000 <span dir=\"rtl\">רקד שהיה זמר</span> dancer and musician).—V. <a href=\"#\" data-headword=\"*קְלוּסַנְטְרִין\">קְלוּסַנְטְרִין</a>.</div>","alt":[]},"28379":{"h":"קְלַסְתּוֹרָא","r":"S01389","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">קלסט׳</span>.</div>","alt":["קְלַסְתֵּיר","קְלַסְתָּר","קְלַסְתְּרָא"]},"28380":{"h":"קָלַע I","r":"S01390","html":"<div class=\"sense\"> (b. h.) [<i>to swing</i>,] <i>to cast, sling</i>.</div><div class=\"sense\"><b>Pi. קִילֵּעַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קְלַסְתּוֹרָא\">same</a>. <span class=\"citation\">Sabb. 152ᵇ</span> <span dir=\"rtl\">ומְקַלְּעִין נִשְׁמָתָן זה לזה</span> and they (the angels) cast their (the sinners’) souls to one another (like washers) (with ref. to <span class=\"citation\">I Sam. XXV, 29</span>, v. <a href=\"#\" data-headword=\"*זוּם\">זוּם</a>); <span class=\"citation\">Yalk. Sam. 134</span>.</div></div>","alt":[]},"28381":{"h":"קְלַע","r":"S01391","html":"<div class=\"sense\"><i>Af.</i> <span dir=\"rtl\">אַקְלַע</span> <a href=\"#\" data-headword=\"קָלַע I\">same</a>. <span class=\"citation\">Targ. I Sam. XVII, 49</span>. <span class=\"citation\">Targ. Y. Ex. X, 19</span> אקלע Ar. (ed. <a href=\"#\" data-headword=\"טְלַק\">טלק</a>).</div><div class=\"sense\"><b>Ithpe. אִיקְּלַע</b> <div class=\"sense\"><i>to be thrown; to happen to come, happen to fall</i> (<i>on a certain day</i>). <span class=\"citation\">Ḥull. 110ᵃ</span> <span dir=\"rtl\">א׳ לסורא וכ׳</span> happened to come to Sura on the eve of &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אִיקְלְעוּ לבי וכ׳</span> happened to come to the house (were the guests) of &amp;c. <span class=\"citation\">Pes. 46ᵇ</span> <span dir=\"rtl\">הואיל ומִיקְלְעֵי וכ׳</span> since guests may happen to come to him. <span class=\"citation\">Ned. 8ᵃ</span> <span dir=\"rtl\">עד דמִקְלְעֵי ליה וכ׳</span> until ten persons … pass by him. <span class=\"citation\">R. Hash. 20ᵃ</span> <span dir=\"rtl\">דא׳ יום שלשים וכ׳</span> if the thirtieth day happens to fall on a Sabbath. <span class=\"citation\">Ber. 53ᵇ</span> <span dir=\"rtl\">אי מִקְּלַע לי ממילא</span> if I happen to get it. <span class=\"citation\">Sabb. 117ᵇ</span> <span dir=\"rtl\">כי מיקלע להו וכ׳</span> if they by chance had bread that had been used for an ʿErub <a href=\"#\" data-headword=\"עֵירוּב\">(עֵירוּב</a>); a. fr.</div></div>","alt":[]},"28382":{"h":"קָלַע II","r":"S01392","html":"<div class=\"sense\"><i>to twist, plait</i>; [b. h. <i>to form a raised figure</i>, cmp. <a href=\"#\" data-headword=\"גָּדַל II\"><span dir=\"rtl\">גָּדַל</span> II</a>]. <span class=\"citation\">Yoma VI, 7</span> <span dir=\"rtl\">קְלָעָן</span>, v. <a href=\"#\" data-headword=\"מַקֵּל\">מַקֵּל</a>. <span class=\"citation\">Sabb. 64ᵃ</span> <span dir=\"rtl\">עני קוֹלֵעַ שלש וכ׳</span> a poor man twists three threads and hangs the cord around his daughter’s neck. Y. ib. X, 12ᶜ bot. <span dir=\"rtl\">הקולע שלש וכ׳</span> he that plaits three strings of hair on a person’s head. <span class=\"citation\">Tosef. Maasr. I, 6</span> <span dir=\"rtl\">היה עתיד לִקְלוֹעַ בשום ולאגוד וכ׳</span> (ed. Zuck. <span dir=\"rtl\">ליקָּלֵעַ … וליאגד</span>, <i>Nif.</i>) if the intention was about the garlic crop to plait, and about the onions to tie them in bunches, <span dir=\"rtl\">אינו חייב עד שיִקְלַע ויאגד</span> he is not bound to give the tithes until he plaits or ties (or <span dir=\"rtl\">עד שיִקָּלֵעַ ויֵאָגֵד</span> until the things are plaited or bunched); a. e.—Trnsf. [<i>to weave a wreath</i>,] <i>to adorn, praise</i>. <span class=\"citation\">Midr. Till. to Ps. XCII</span>, end; <span class=\"citation\">Yalk. Ps. 846</span> <span dir=\"rtl\">הוא קוֹלֵעַ על יריאיו … קוֹלְעִים לו וכ׳</span> he (God) praises those who fear him, and those who fear him praise him; you say (<span class=\"citation\">Ps. XCII, 16</span>) &amp;c., and I say, (<span class=\"citation\">Zeph. III, 13</span></div><div class=\"sense\"><b>Pi. קִילֵּעַ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"קְלַע\">same</a>. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">היא קִילְּעָה לו וכ׳</span> (not <span dir=\"rtl\">קולעה</span>) she plaited her hair to please him (her paramour), therefore the priest loosens her hair; <span class=\"citation\">Tosef. Sot. III, 3</span> ed. Zuck. note <span dir=\"rtl\">קלעה</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">קִילְּעֶה</span> or <span dir=\"rtl\">קִלְּעֶה</span> (cmp. <span dir=\"rtl\">נתעלפה</span>, s. v. <a href=\"#\" data-headword=\"עָלַף II\"><span dir=\"rtl\">עָלַף</span> II</a>) <i>to plait a person’s hair, dress, adorn</i> (v. supra). <span class=\"citation\">Ber. 61ᵃ</span>; <span class=\"citation\">Koh. R. to VII, 2</span>; <span class=\"citation\">Sabb. 95ᵃ</span>; <span class=\"citation\">Erub. 18ᵃ</span>; <span class=\"citation\">Nidd. 45ᵇ</span>; <span class=\"citation\">Koh. R. to VII, 2</span> (ref. to <span dir=\"rtl\">ויבן</span>, <span class=\"citation\">Gen. II, 22</span>) <span dir=\"rtl\">מלמד שקילעה הקב&quot;ה לחוה וכ׳</span> this intimates that the Lord dressed Eve &amp;c., v. <a href=\"#\" data-headword=\"בִּנְיָיתָא\">בִּנְיָיתָא</a>. Y. Snh. II, 20ᵃ bot. (ref. to <span class=\"citation\">II Sam. XX, 3</span> <span dir=\"rtl\">ויכלכל</span>, v. <a href=\"#\" data-headword=\"כִּלְכֵּל\">כִּלְכֵּל</a>) <span dir=\"rtl\">מלמד שהיה דוד מְקַלַּעֲתָן וכ׳</span></div></div><div class=\"sense\"><b>Nif. נִקְלַע</b> <div class=\"sense\"><i>to be plaited</i>, v. supra.</div></div>","alt":[]},"28383":{"h":"קְלַע ²","r":"S01393","html":"<div class=\"sense\">, <i>to plait</i>. <span class=\"citation\">Targ. Y. Num. V, 18</span> (v. <span class=\"citation\">Num. R. s. 9</span>, quot. in <a href=\"#\" data-headword=\"קָלַע II\">preced.</a>).</div>","alt":[]},"28384":{"h":"רַבִּין","r":"T00095","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (= <span dir=\"rtl\">רב אבין</span>) <i>Rabbin, Rabin</i>, an Amora. <span class=\"citation\">Pes. 25ᵃ</span>, a. fr. <span dir=\"rtl\">כי אתא ר׳</span> when R. came (to Babylonia). <span class=\"citation\">Ib. 34ᵇ</span> <span dir=\"rtl\">כי סליק ר׳</span> when R. came up (to Palestine); a. fr.—V. Fr. M’bo, p. 60ᵇ</div>","alt":["(רָבִין)"]},"28385":{"h":"רָבִינָא","r":"T00096","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (= <span dir=\"rtl\">רב אבינא</span>) <i>Rabina, Rabbina</i>, name of several Amoraim. <span class=\"citation\">B. Mets. 86ᵃ</span>. <span class=\"citation\">Ḥull. 43ᵇ</span> <span dir=\"rtl\">מר בריה דרב א׳</span>. <span class=\"citation\">Ib. 46ᵇ</span>; a. fr.</div>","alt":["(רַבִּינָא)"]},"28386":{"h":"רַבֵּינוּ","r":"T00097","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַבֵּנוּ\">רַבֵּנוּ</a></div>","alt":[]},"28387":{"h":"רָבִיעַ","r":"T00098","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רְבִיעִי\">רְבִיעִי</a>) </div><div class=\"sense\"><b>1)</b> <i>one fourth</i>; </div><div class=\"sense\"><b>2)</b> <i>square</i>. <span class=\"citation\">Tosef. Sot. V, 13</span>; <span class=\"citation\">Erub. 56ᵇ</span> <span dir=\"rtl\">מגרש ר׳</span> the pasture ground of Levitic townships was one-fourth of the area; <span class=\"citation\">Y. Sot. V, 20ᵇ</span> bot. <span dir=\"rtl\">ר׳ מגרש</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ מאלף</span> it means a square of one thousand cubits; <span dir=\"rtl\">אפי׳ תימא ר׳ מכל צד ר׳ חוא</span> even if you say that it means ‘square’, at all events it is one-fourth of the area. <span class=\"citation\">Gitt. V, 6</span> <span dir=\"rtl\">נותן … ר׳</span>, v. <a href=\"#\" data-headword=\"סִיקָרִיקוֹן\">סִיקָרִיקוֹן</a>. <span class=\"citation\">Ib. 58ᵇ</span> <span dir=\"rtl\">ר׳ בקרקע או ר׳ וכ׳</span> one-fourth of the property bought, or one-fourth of the purchase price. <span class=\"citation\">Y. Pes. X, 37ᶜ</span> top, a. e., v. <a href=\"#\" data-headword=\"טִיטַרְטוֹן\">טִיטַרְטוֹן</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"רְבִיעִין\">רְבִיעִין</a> <i>blocks</i>. <span class=\"citation\">Midd. III, 5</span> <span dir=\"rtl\">ר׳ של ארז וכ׳</span> (Bart. <span dir=\"rtl\">רִבּוּעִין</span>) cedar blocks were on top (of the columns). <span class=\"citation\">Tam. III, 5</span> <a href=\"#\" data-headword=\"רְבִיעִית\">רְבִיעִית</a>.—[<span class=\"citation\">Tosef. Taan. I, 4</span>, v. <a href=\"#\" data-headword=\"רְבִיעָה\">רְבִיעָה</a>.]</div>","alt":[]},"28388":{"h":"רְבִיעַ","r":"T00099","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְבַע\">רְבַע</a></div>","alt":[]},"28389":{"h":"רְבִיעָאָה","r":"T00100","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רְבִיעִי\">רְבִיעִי</a>, <i>fourth</i>. <span class=\"citation\">Targ. Gen. I, 19</span> (ed. Berl. <span dir=\"rtl\">עָי …</span>). Ib. II, 14; a. fr.—Pl. <a href=\"#\" data-headword=\"רְבִיעִין\">רְבִיעִין</a>, <a href=\"#\" data-headword=\"רְבִיעִין\">רְבִיעָאִין</a>, <a href=\"#\" data-headword=\"רְבִיעָאָה\">רְבִיעָאֵי</a>. <span class=\"citation\">Targ. II Kings X, 30</span>; <span class=\"citation\">XV, 12</span>. <span class=\"citation\">Targ. Y. Ex. XX, 5</span>; a. e.—<i>Fem.</i> <a href=\"#\" data-headword=\"רְבִיעֵיתָא\">רְבִיעֵיתָא</a>, <a href=\"#\" data-headword=\"רְבִיעֵיתָא\">רְבִיעָתָא</a>. <span class=\"citation\">Targ. Lev. XIX, 24</span> ed. Berl. <span dir=\"rtl\">רביעי׳</span>. <span class=\"citation\">Targ. II Chr. XXVIII, 3</span> <span dir=\"rtl\">בר׳</span> the fourth time.</div>","alt":["רְבִיעַאי","רְבִיעַי"]},"28390":{"h":"רְבִיעָה","r":"T00101","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַע\">רָבַע</a>) </div><div class=\"sense\"><b>1)</b> <i>coupling</i>, esp. (v. <span class=\"citation\">Lev. XX, 16</span>) <i>carnal connection with beasts, buggery</i>. <span class=\"citation\">Ab. Zar. II, 1</span> <span dir=\"rtl\">מפני … הר׳</span> because they (the gentiles) are suspected of using beasts for buggery. <span class=\"citation\">Ib. 23ᵃ</span>. <span class=\"citation\">B. Kam. 40ᵇ</span>, sq.; a. e.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"בַּעַל\">בַּעַל</a> h.  [<i>fructification</i>,] <i>rainfall</i> in the autumn. <span class=\"citation\">Taan. 6ᵇ</span> <span dir=\"rtl\">עד … ר׳ שנייה</span> until the second rainfall comes down. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי לשון ר׳ דבר שרובע וכ׳</span> what is the radical meaning of <a href=\"#\" data-headword=\"רְבִיעָה\">רביעה</a>? Something which fructifies the ground, as R. J. says, ‘the rain is the husband &amp;c.’ <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ר׳ ראשונה כדי וכ׳</span> the first rainfall (is satisfactory, and you need no fast-day), when there is enough to enter the ground to the depth of one handbreadth; <span dir=\"rtl\">ר׳ שנייה כדי לגוף וכ׳</span> the second rainfall (is satisfactory), when the soil is fit to be used for sealing the mouth of a cask. Ib. 6ᵃ; Tosef. ib. I, 3. Ib. 4 <span dir=\"rtl\">רביע</span> ed. Zuck. (corr. acc.). <span class=\"citation\">Gen. R. s. 13</span> <span dir=\"rtl\">כדי ר׳</span> enough rain to be called <i>r’biʿah</i> (fructification); a. fr.—<span class=\"citation\">Tosef. B. Kam. I, 9</span> <span dir=\"rtl\">ועל ר׳</span> ed. Zuck., v. <a href=\"#\" data-headword=\"רְבִיצָה\">רְבִיצָה</a>.]</div>","alt":[]},"28391":{"h":"רְבִיעוּת","r":"T00102","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְבִיעָה\">preced.</a>) <i>fructification, copulation</i>.—Pl. <span dir=\"rtl\">רְבִיעִיּוֹת</span>. <span class=\"citation\">Num. R. s. 20</span> (ref. to <a href=\"#\" data-headword=\"רָבַע\">רֹבַע</a>, <span class=\"citation\">Num. XXIII, 10</span>) <span dir=\"rtl\">הר׳ שלהן … אוכלוסין שיצאו וכ׳</span> (ed. Wil. <span dir=\"rtl\">הרביעית</span>, corr. acc.) who can count their fructifications, that is, the masses that came forth from those (women) who anxiously seized the opportunity of, and loved noble deeds &amp;c.; <span class=\"citation\">Nidd. 31ᵃ</span> <span dir=\"rtl\">הקב&quot;ה … רְבִיעִיּוֹתֵיהֶם וכ׳</span> the Lord counts Israel’s fructifications, ‘when will the sperm come of which the righteous shall be created’?</div>","alt":[]},"28392":{"h":"רְבִיעוּתָא","r":"T00103","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Deut. XXXII, 2</span> <span dir=\"rtl\">כרְבִיעוּת רוּחֵי וכ׳</span> (not <span dir=\"rtl\">רוּחִי</span>) like the fructification of the rain-winds &amp;c.—Cmp. <a href=\"#\" data-headword=\"רְבִיעֲתָא\">רְבִיעֲתָא</a>.</div>","alt":[]},"28393":{"h":"רְבִיעִי","r":"T00104","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>fourth</i>. <span class=\"citation\">Taan. 29ᵇ</span> <span dir=\"rtl\">חל להיות … בר׳</span> (sub. <span dir=\"rtl\">בשבת</span>) if the ninth of Ab falls … on a Wednesday; <span class=\"citation\">Meg. 22ᵇ</span>. <span class=\"citation\">Keth. I, 1</span> <span dir=\"rtl\">בתילה נשאת ליום הר׳</span> it is customary for a virgin to be married on the fourth day of the week; a. v. fr.—Esp. <i>fourth grade of uncleanness</i>. <span class=\"citation\">Ḥag. III, 2</span>; <span class=\"citation\">Tosef. ib. III, 7</span> <span dir=\"rtl\">הר׳ פסול וכ׳</span> the fourth grade is a disqualification in sacrificial food, the third, in T’rumah. <span class=\"citation\">Ib. 18</span>; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"רְבִיעִית\">רְבִיעִית</a>. <span class=\"citation\">Meg. III, 4</span> (<span class=\"citation\">29ᵃ</span>) <span dir=\"rtl\">בר׳</span> on the fourth Sabbath of Adar; a. fr.—Esp. (sub. <a href=\"#\" data-headword=\"לוֹג\">לוֹג</a>) <i>one fourth of a Log</i>. <span class=\"citation\">B. Bath. 58ᵇ</span> <span dir=\"rtl\">איזהו אנטל זהו ר׳</span> what is Anṭal? The fourth of a Log mentioned in connection with religious ceremonies (v. comment.). Y. Sabb. VIII, 11ᵃ bot. <span dir=\"rtl\">ר׳ של תורה וכ׳</span> Ar. (ed. <span dir=\"rtl\">שיעורו של כוס</span>) the legal <i>r’biʿith</i> (for the cup of the Passover night) is a bottom of two fingers by two, with a height of one and five-sixths of a finger. <span class=\"citation\">Sot. 5ᵃ</span> <span dir=\"rtl\">אדם שאין בו אלא ר׳ אחת וכ׳</span> man in whom there is only one-fourth of a Log (of vital blood, v. Rashi) &amp;c.; <span class=\"citation\">Sabb. 31ᵇ</span> bot.; a. v. fr.—Pl. <span dir=\"rtl\">רְבִיעִיּוֹת</span>. Sot. l. c. <span class=\"citation\">Lam. R. to IV, 1</span> (ref. to <span dir=\"rtl\">אבני קדש</span>, ib.) <span dir=\"rtl\">אלו שתי ר׳ של דם וכ׳</span> this refers to the two-fourths of blood (of king Josiah) which Jeremiah took up (from the battlefield) and buried (v. <span class=\"citation\">II Chr. XXXV, 24</span> sq.). <span class=\"citation\">Pes. 112ᵃ</span> <span dir=\"rtl\">לילי ר׳</span> the nights of the fourth days of the week, Tuesday evenings; a. fr.</div>","alt":[]},"28394":{"h":"רְבִיעַי","r":"T00105","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְבִיעָאָה\">רְבִיעָאָה</a></div>","alt":[]},"28395":{"h":"רְבִיעִין","r":"T00106","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\">name of <i>a musical instrument, sistra</i> (v. Sm. Ant. s. v. Sistrum and illustration). <span class=\"citation\">Targ. II Sam. VI, 5</span> (h. text <span dir=\"rtl\">מנענעים</span>).</div>","alt":[]},"28396":{"h":"רְבִיעִית","r":"T00107","html":"<p class=\"morphology\">f.</p><div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רְבִיעִין\">same</a>. <span class=\"citation\">Kel. XVI, 7</span> (v. Maim. a. l.).—2) fem. of <a href=\"#\" data-headword=\"רְבִיעִי\">רְבִיעִי</a> q. v.—3) <i>square block</i>. <span class=\"citation\">Tam. III, 5</span>, v. <a href=\"#\" data-headword=\"רָבִיעַ\">רָבִיעַ</a>.</div>","alt":[]},"28397":{"h":"רְבִיעֵיתָא","r":"T00108","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְבִיעָאָה\">רְבִיעָאָה</a></div>","alt":["רְבִיעָתָא"]},"28398":{"h":"רְבִיעֲתָא","r":"T00109","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רְבִיעָה\">רְבִיעָה</a>, <i>rain</i>. <span class=\"citation\">Y. Taan. II, 65ᵇ</span> top <span dir=\"rtl\">ר׳ קדמיתא</span> the first rainfall. <span class=\"citation\">Gen. R. s. 13</span>, end; a. e.</div>","alt":[]},"28399":{"h":"רְבִיצָה","r":"T00110","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַץ\">רָבַץ</a>) <i>lying down</i>, esp. <i>damage caused by an animal falling on an object</i>. <span class=\"citation\">B. Kam. 2ᵇ</span>; Y. ib. I, beg. 2ᵃ; <span class=\"citation\">Tosef. ib. I, 9</span>; ib. <a href=\"#\" data-headword=\"רְבִיעָה\">רביעה</a> ed. Zuck. (corr. acc.)</div>","alt":[]}};
